final String? _incomingReferralCode = _extractIncomingReferralCode();

String? _extractIncomingReferralCode() {
  final query = Uri.base.queryParameters['ref'] ??
      Uri.base.queryParameters['referral'] ??
      Uri.base.queryParameters['code'];
  if (query != null && query.trim().isNotEmpty) {
    return query.trim().toUpperCase();
  }
  final segments = Uri.base.pathSegments;
  final joinIndex = segments.indexWhere((segment) => segment == 'join');
  if (joinIndex >= 0 && segments.length > joinIndex + 1) {
    return segments[joinIndex + 1].trim().toUpperCase();
  }
  return null;
}

Future<void> _attachIncomingReferralIfPresent() async {
  final code = _incomingReferralCode;
  if (code == null || code.isEmpty) return;
  try {
    await FirebaseFunctions.instance
        .httpsCallable('attachReferralCode')
        .call({'referralCode': code});
  } catch (error) {
    debugPrint('Referral attach skipped: $error');
  }
}

Future<void> _activateReferralSafely({
  required String activityType,
  required String activityId,
}) async {
  try {
    await FirebaseFunctions.instance.httpsCallable('activateReferral').call({
      'activityType': activityType,
      'activityId': activityId,
    });
  } catch (error) {
    debugPrint('Referral activation skipped: $error');
  }
}

enum _WebAppMode {
  landing,
  sender,
  rider,
  gifts,
  admin,
  iris,
  healthPlus,
  terms,
  privacy,
  cookies,
  vanguard,
  business,
  businessDashboard,
}

bool _isPublicHostingHost() {
  final host = Uri.base.host.toLowerCase();
  return host == 'circumuk.com' ||
      host == 'www.circumuk.com' ||
      host == 'circum-2797c.web.app' ||
      host == 'circum-app-2797c.web.app';
}

Future<void> _ensureCircumFirebaseReady() async {
  if (Firebase.apps.isEmpty) {
    await Firebase.initializeApp(options: DefaultFirebaseOptions.web);
  }
}

class WebSenderApp extends StatefulWidget {
  const WebSenderApp({super.key});

  @override
  State<WebSenderApp> createState() => _WebSenderAppState();
}

class _WebSenderAppState extends State<WebSenderApp> {
  bool _darkMode = true;
  late _WebAppMode _mode = _initialMode();
  late _SenderStep _senderInitialStep = _initialSenderStep();

  bool get _senderArchitecturePreview {
    return Uri.base.queryParameters['preview'] == 'sender-ui';
  }

  bool get _riderArchitecturePreview {
    final path = Uri.base.path.toLowerCase().replaceAll(RegExp(r'/+$'), '');
    return path == '/rider' || Uri.base.queryParameters['app'] == 'rider';
  }

  String get _normalizedPath =>
      Uri.base.path.toLowerCase().replaceAll(RegExp(r'/+$'), '');

  bool get _isSenderAppPath {
    final path = _normalizedPath;
    return path == '/sender' || path == '/app';
  }

  bool get _isPublicMarketingPath {
    final path = _normalizedPath;
    return path.isEmpty ||
        path == '/' ||
        path == '/iris' ||
        path == '/health' ||
        path == '/health-plus' ||
        path == '/gifts' ||
        path == '/business' ||
        path == '/vanguard' ||
        path == '/terms' ||
        path == '/privacy' ||
        path == '/cookies';
  }

  _WebAppMode? get _publicMarketingModeForPath {
    final path = _normalizedPath;
    return switch (path) {
      '' || '/' => _WebAppMode.landing,
      '/iris' => _WebAppMode.iris,
      '/health' || '/health-plus' => _WebAppMode.healthPlus,
      '/gifts' => _WebAppMode.gifts,
      '/business' => _WebAppMode.business,
      '/vanguard' => _WebAppMode.vanguard,
      '/terms' => _WebAppMode.terms,
      '/privacy' => _WebAppMode.privacy,
      '/cookies' => _WebAppMode.cookies,
      _ => null,
    };
  }

  @override
  void initState() {
    super.initState();
    _logWebsiteVisit();
  }

  _WebAppMode _initialMode() {
    if (_adminHostingTarget && !_isPublicHostingHost()) {
      return _WebAppMode.admin;
    }
    final path = _normalizedPath;
    if (path == '/sender' || path == '/app') return _WebAppMode.sender;
    if (path == '/rider') return _WebAppMode.rider;
    if (path == '/iris') return _WebAppMode.iris;
    if (path == '/health' || path == '/health-plus') {
      return _WebAppMode.healthPlus;
    }
    if (path == '/gifts') return _WebAppMode.gifts;
    if (path == '/terms') return _WebAppMode.terms;
    if (path == '/privacy') return _WebAppMode.privacy;
    if (path == '/cookies') return _WebAppMode.cookies;
    if (path == '/vanguard') return _WebAppMode.vanguard;
    if (path == '/business') return _WebAppMode.business;
    if (path == '/business/dashboard') return _WebAppMode.businessDashboard;
    // Mobile sender app dashboard must not be mounted on the public marketing web homepage.
    if (_isPublicMarketingPath &&
        const {'sender', 'app', 'dashboard'}
            .contains(Uri.base.queryParameters['app'])) {
      return _WebAppMode.landing;
    }
    return switch (Uri.base.queryParameters['app']) {
      'health' => _WebAppMode.healthPlus,
      'business' => _WebAppMode.business,
      'business-dashboard' => _WebAppMode.businessDashboard,
      'rider' || 'driver' || 'earn' || 'circum-order' => _WebAppMode.rider,
      'gifts' => _WebAppMode.gifts,
      'iris' => _WebAppMode.iris,
      _ => _WebAppMode.landing,
    };
  }

  _SenderStep _initialSenderStep() {
    final path = Uri.base.path.toLowerCase().replaceAll(RegExp(r'/+$'), '');
    if (path == '/sender' || path == '/app') {
      return switch (Uri.base.queryParameters['section'] ??
          Uri.base.queryParameters['service']) {
        'health' || 'health-plus' => _SenderStep.healthPlus,
        'business' => _SenderStep.business,
        'account' || 'profile' => _SenderStep.account,
        _ => _SenderStep.dashboard,
      };
    }
    return switch (Uri.base.queryParameters['app']) {
      _ => _SenderStep.dashboard,
    };
  }

  Future<void> _logWebsiteVisit() async {
    try {
      await _ensureCircumFirebaseReady();
      final user = FirebaseAuth.instance.currentUser;
      await FirebaseFirestore.instance.collection('websiteVisitors').add({
        'url': Uri.base.toString(),
        'path': Uri.base.path,
        'query': Uri.base.queryParameters,
        'appMode': _mode.name,
        'userId': user?.uid,
        'email': user?.email,
        'signedIn': user != null,
        'source': 'circum-web',
        'createdAt': FieldValue.serverTimestamp(),
      });
    } catch (_) {
      // Visitor analytics must never block the app.
    }
  }

  @override
  Widget build(BuildContext context) {
    final colors = _CircumColors(_darkMode);
    // Mobile sender app dashboard must not be mounted on the public marketing web homepage.
    final effectiveMode = _publicMarketingModeForPath ??
        (_mode == _WebAppMode.sender && !_isSenderAppPath
            ? _WebAppMode.landing
            : _mode);

    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: _companyName,
      theme: ThemeData(
        useMaterial3: true,
        fontFamily: 'Helvetica',
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xff2563eb),
          brightness: _darkMode ? Brightness.dark : Brightness.light,
        ),
      ),
      home: Scaffold(
        backgroundColor: colors.background,
        body: Stack(
          children: [
            AnimatedSwitcher(
              duration: const Duration(milliseconds: 260),
              child: switch (effectiveMode) {
                _WebAppMode.sender => _PhoneStage(
                    key: const ValueKey('sender-app'),
                    colors: colors,
                    child: _senderArchitecturePreview
                        ? _SenderArchitecturePreviewApp(
                            colors: colors,
                            onOpenGifts: () =>
                                setState(() => _mode = _WebAppMode.gifts),
                          )
                        : _CustomerPortal(
                            darkMode: _darkMode,
                            colors: colors,
                            initialStep: _senderInitialStep,
                            onBack: () =>
                                setState(() => _mode = _WebAppMode.landing),
                            onRoleSelected: _openRole,
                            onOpenGifts: () =>
                                setState(() => _mode = _WebAppMode.gifts),
                            onToggleTheme: () =>
                                setState(() => _darkMode = !_darkMode),
                          ),
                  ),
                _WebAppMode.rider => _PhoneStage(
                    key: const ValueKey('rider-app'),
                    colors: colors,
                    child: _riderArchitecturePreview
                        ? _RiderArchitecturePreviewApp(colors: colors)
                        : _RiderEnrollmentPortal(
                            darkMode: _darkMode,
                            colors: colors,
                            onBack: () =>
                                setState(() => _mode = _WebAppMode.landing),
                            onRoleSelected: _openRole,
                            onToggleTheme: () =>
                                setState(() => _darkMode = !_darkMode),
                          ),
                  ),
                _WebAppMode.admin => _AdminOperationsPanel(
                    key: const ValueKey('admin-ops'),
                    colors: colors,
                    darkMode: _darkMode,
                    onBack: _adminHostingTarget
                        ? () {}
                        : () => setState(() => _mode = _WebAppMode.landing),
                    onToggleTheme: () => setState(() => _darkMode = !_darkMode),
                  ),
                _WebAppMode.gifts => _GiftsRequestPage(
                    key: const ValueKey('gifts-request'),
                    colors: colors,
                    onBack: () => setState(() => _mode = _WebAppMode.landing),
                  ),
                _WebAppMode.iris => _PublicIrisPage(
                    key: const ValueKey('iris-public'),
                    colors: colors,
                    darkMode: _darkMode,
                    onBack: () => setState(() => _mode = _WebAppMode.landing),
                    onToggleTheme: () => setState(() => _darkMode = !_darkMode),
                  ),
                _WebAppMode.healthPlus => _PublicHealthPlusPage(
                    key: const ValueKey('health-public'),
                    colors: colors,
                    darkMode: _darkMode,
                    onStartHealth: () => _openSenderHealthPlus(),
                    onBack: () => setState(() => _mode = _WebAppMode.landing),
                    onToggleTheme: () => setState(() => _darkMode = !_darkMode),
                  ),
                _WebAppMode.terms => _LegalDocumentPage(
                    key: const ValueKey('terms'),
                    colors: colors,
                    title: 'Terms of Service',
                    documentPath: '/legal/CIRCUM_Terms_of_Service.pdf',
                    onBack: () => setState(() => _mode = _WebAppMode.landing),
                  ),
                _WebAppMode.privacy => _LegalDocumentPage(
                    key: const ValueKey('privacy'),
                    colors: colors,
                    title: 'Privacy Policy',
                    documentPath: '/legal/CIRCUM_Privacy_Policy.pdf',
                    onBack: () => setState(() => _mode = _WebAppMode.landing),
                  ),
                _WebAppMode.cookies => _PublicInfoPage(
                    key: const ValueKey('cookies-public'),
                    colors: colors,
                    darkMode: _darkMode,
                    title: 'Cookies',
                    eyebrow: 'Privacy',
                    body:
                        'Circum uses essential cookies and local browser storage to keep the website and authenticated dashboards working securely.',
                    icon: Icons.cookie_outlined,
                    primaryLabel: 'Privacy Policy',
                    onPrimary: () =>
                        setState(() => _mode = _WebAppMode.privacy),
                    onBack: () => setState(() => _mode = _WebAppMode.landing),
                    onToggleTheme: () => setState(() => _darkMode = !_darkMode),
                  ),
                _WebAppMode.vanguard => _VanguardExplainerPage(
