  AdminRole _adminInviteRole = AdminRole.operationsAdmin;
  User? _adminUser;
  List<String> _roles = const [];
  bool _loading = true;
  bool _signingIn = false;
  String? _message;
  AdminMetricSnapshot _metrics = AdminMetricSnapshot.empty();
  List<Map<String, dynamic>> _deliveries = const [];
  List<Map<String, dynamic>> _giftRequests = const [];
  List<Map<String, dynamic>> _giftBrands = const [];
  List<Map<String, dynamic>> _businessAccounts = const [];
  List<Map<String, dynamic>> _businessWallets = const [];
  List<Map<String, dynamic>> _businessInvoices = const [];
  List<Map<String, dynamic>> _businessRothPurchases = const [];
  List<Map<String, dynamic>> _giftCampaignParticipants = const [];
  List<Map<String, dynamic>> _senders = const [];
  List<Map<String, dynamic>> _drivers = const [];
  List<Map<String, dynamic>> _payments = const [];
  List<Map<String, dynamic>> _ratings = const [];
  List<Map<String, dynamic>> _supportTickets = const [];
  List<Map<String, dynamic>> _healthPlusPayments = const [];
  List<Map<String, dynamic>> _healthPlusPickups = const [];
  List<Map<String, dynamic>> _recurringPickupSchedules = const [];
  List<Map<String, dynamic>> _payoutRequests = const [];
  List<Map<String, dynamic>> _riderWallets = const [];
  List<Map<String, dynamic>> _roleRothWallets = const [];
  List<Map<String, dynamic>> _walletTransactions = const [];
  List<Map<String, dynamic>> _rothWallets = const [];
  List<Map<String, dynamic>> _rothTransactions = const [];
  List<Map<String, dynamic>> _adminUsers = const [];
