  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? _supportTicketsSub;

  @override
  void initState() {
    super.initState();
    _restoreAdmin();
  }

  @override
  void dispose() {
    _email.dispose();
    _password.dispose();
    _search.dispose();
    _adminInviteEmail.dispose();
    _adminInviteNote.dispose();
    _adminChatInput.dispose();
    _rothUserId.dispose();
    _rothAmount.dispose();
    _rothReason.dispose();
    _adminChatSub?.cancel();
    _supportTicketsSub?.cancel();
    super.dispose();
  }

  Future<void> _restoreAdmin() async {
    setState(() => _loading = true);
    try {
      await _ensureCircumFirebaseReady();
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) {
        setState(() {
          _adminUser = null;
          _roles = const [];
          _loading = false;
        });
        return;
      }
      await _loadAdminAccess(user);
      if (AdminAccessPolicy.hasAnyAdminRole(_roles)) {
        await _loadAdminData();
      }
    } catch (_) {
      if (!mounted) return;
      setState(() => _message = 'Could not load admin access.');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _loadAdminAccess(User user) async {
    final token = await user.getIdTokenResult(true);
    final claims = token.claims ?? const <String, dynamic>{};
    final claimRoles = <String>[
      if (claims['adminRole'] != null) '${claims['adminRole']}',
      if (claims['role'] != null) '${claims['role']}',
      if (claims['roles'] is List)
        ...(claims['roles'] as List<dynamic>).map((role) => '$role'),
    ];
    final adminDoc = await FirebaseFirestore.instance
        .collection('adminUsers')
        .doc(user.uid)
        .get();
    final email = user.email?.trim().toLowerCase();
    final emailDoc = email == null || email.isEmpty
        ? null
        : await FirebaseFirestore.instance
            .collection('adminUsers')
            .doc(email)
            .get();
    final adminRecords = [
      if (adminDoc.exists) adminDoc.data(),
      if (emailDoc?.exists == true) emailDoc?.data(),
    ];
    final inactiveAdmin = AdminUserAccess.hasInactiveAdminRecord(adminRecords);
    final docRoles = inactiveAdmin
        ? <String>[]
        : adminRecords
            .expand((record) => AdminUserAccess.activeRolesFromRecord(record))
            .toList();
    final nextRoles = {...claimRoles, ...docRoles}.toList();
    if (inactiveAdmin) nextRoles.clear();
    setState(() {
      _adminUser = user;
      _email.text = user.email ?? _email.text;
      _roles = nextRoles;
    });
    if (nextRoles.isNotEmpty) {
      final db = FirebaseFirestore.instance;
      final patch = {'lastLoginAt': FieldValue.serverTimestamp()};
      if (adminDoc.exists) {
        await db
            .collection('adminUsers')
            .doc(user.uid)
            .set(patch, SetOptions(merge: true));
      }
      if (emailDoc?.exists == true && email != null) {
        await db
            .collection('adminUsers')
            .doc(email)
            .set(patch, SetOptions(merge: true));
      }
    }
  }

  Future<void> _signIn() async {
    if (_signingIn) return;
    setState(() {
      _signingIn = true;
      _message = 'Checking admin access...';
    });
    try {
      await _ensureCircumFirebaseReady();
      final credential = await FirebaseAuth.instance.signInWithEmailAndPassword(
        email: _email.text.trim(),
        password: _password.text.trim(),
      );
      await _loadAdminAccess(credential.user!);
      if (!AdminAccessPolicy.hasAnyAdminRole(_roles)) {
        setState(
          () => _message =
              'This account is signed in but has no active Circum admin role.',
        );
        return;
      }
      await _loadAdminData();
      setState(() => _message = 'Admin panel ready.');
    } on FirebaseAuthException catch (error) {
      setState(() => _message = _friendlyAdminAuthMessage(error));
    } finally {
      if (mounted) setState(() => _signingIn = false);
    }
  }

  Future<void> _signOut() async {
    await _adminChatSub?.cancel();
    await _supportTicketsSub?.cancel();
    await FirebaseAuth.instance.signOut();
    setState(() {
      _adminUser = null;
      _roles = const [];
      _message = 'Signed out of admin.';
      _adminChatOpen = false;
      _activeAdminChatId = null;
      _activeAdminChatTitle = 'Booking chat';
      _adminChatMessages.clear();
    });
  }

  Future<void> _loadAdminData() async {
    final db = FirebaseFirestore.instance;
    final results = await Future.wait([
      _readCollection(db.collection('deliveryRequests').limit(80)),
      _readCollection(db.collection('users').limit(80)),
      _readCollection(db.collection('riderProfiles').limit(80)),
      _can(AdminPermission.manageAdmins)
          ? _readCollection(db.collection('adminUsers').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(db.collection('payments').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      _readCollection(db.collection('driverRatings').limit(80)),
      _can(AdminPermission.viewSupport)
          ? _readCollection(db.collection('supportTickets').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      (_can(AdminPermission.viewFinance) ||
              _roles.contains(AdminRole.operationsAdmin.value))
          ? _readCollection(db.collection('healthPlusPayments').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewHealthPlus)
          ? _readCollection(db.collection('prescriptionPickups').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewHealthPlus)
          ? _readCollection(db.collection('recurringPickupSchedules').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(db.collection('payoutRequests').limit(80))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(db.collection('riderEarnings').limit(120))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(
              db
                  .collection('riderWalletTransactions')
                  .orderBy('createdAt', descending: true)
                  .limit(120),
            )
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(db.collection('wallets').limit(120))
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(
              db
                  .collection('walletTransactions')
                  .orderBy('createdAt', descending: true)
                  .limit(160),
            )
          : Future.value(<Map<String, dynamic>>[]),
      _readCollection(
        db
            .collection('websiteVisitors')
            .orderBy('createdAt', descending: true)
            .limit(80),
      ),
      _readCollection(db.collection('riderDocuments').limit(120)),
      _readCollection(
        db
            .collection('giftRequests')
            .orderBy('createdAt', descending: true)
            .limit(80),
      ),
      _readCollection(db.collection('giftBrands').limit(100)),
      _readCollection(db.collection('businessAccounts').limit(100)),
      _readCollection(db.collection('business_wallets').limit(100)),
      _can(AdminPermission.viewFinance)
          ? _readCollection(
              db
                  .collection('businessInvoices')
                  .orderBy('createdAt', descending: true)
                  .limit(50),
            )
          : Future.value(<Map<String, dynamic>>[]),
      _can(AdminPermission.viewFinance)
          ? _readCollection(
              db
                  .collection('businessRothPurchases')
                  .orderBy('createdAt', descending: true)
                  .limit(50),
            )
          : Future.value(<Map<String, dynamic>>[]),
      _readCollection(db.collection('giftCampaignParticipants').limit(100)),
      _readCollection(
        db
            .collection('adminAuditLogs')
            .orderBy('createdAt', descending: true)
            .limit(40),
      ),
    ]);
    final roleRothWallets = _can(AdminPermission.viewFinance)
        ? await _readRoleRothWallets(db)
        : <Map<String, dynamic>>[];
    final deliveries = results[0];
    final senders = results[1];
    final drivers = results[2];
    final adminUsers = results[3];
    final payments = results[4];
    final ratings = results[5];
    final tickets = results[6];
    final healthPayments = results[7];
    final healthPickups = results[8];
    final schedules = results[9];
    final payouts = results[10];
    final riderWallets = results[11];
    final walletTransactions = results[12];
    final rothWallets = results[13];
    final rothTransactions = results[14];
    final visitors = results[15];
    final riderDocuments = results[16];
    final giftRequests = results[17];
    final giftBrands = results[18];
    final businessAccounts = results[19];
    final businessWallets = results[20];
    final businessInvoices = results[21];
    final businessRothPurchases = results[22];
    final giftCampaignParticipants = results[23];
    setState(() {
      _deliveries = deliveries;
      _senders = senders;
      _drivers = drivers;
      _adminUsers = adminUsers;
      _payments = payments;
      _ratings = ratings;
      _supportTickets = tickets;
      _healthPlusPayments = healthPayments;
      _healthPlusPickups = healthPickups;
      _recurringPickupSchedules = schedules;
      _payoutRequests = payouts;
      _riderWallets = riderWallets;
      _roleRothWallets = roleRothWallets;
      _walletTransactions = walletTransactions;
      _rothWallets = rothWallets;
      _rothTransactions = rothTransactions;
      _websiteVisitors = visitors;
      _riderDocuments = riderDocuments;
      _giftRequests = giftRequests;
      _giftBrands = giftBrands;
      _businessAccounts = businessAccounts;
      _businessWallets = businessWallets;
      _businessInvoices = businessInvoices;
      _businessRothPurchases = businessRothPurchases;
      _giftCampaignParticipants = giftCampaignParticipants;
      _auditLogs = results[21];
      _metrics = AdminMetricSnapshot.fromData(
        deliveries: deliveries,
        senders: senders,
        drivers: drivers,
        payments: payments,
        ratings: ratings,
        supportTickets: tickets,
        healthPlusPayments: healthPayments,
      );
    });
    _startSupportTicketListener();
  }

  void _startSupportTicketListener() {
    _supportTicketsSub?.cancel();
    if (!_can(AdminPermission.viewSupport)) return;
    _supportTicketsSub = FirebaseFirestore.instance
        .collection('supportTickets')
        .limit(80)
        .snapshots()
        .listen((snapshot) {
      if (!mounted) return;
      final tickets = snapshot.docs
          .map((doc) => <String, dynamic>{'id': doc.id, ...doc.data()})
          .toList(growable: false);
      setState(() {
        _supportTickets = tickets;
        _metrics = AdminMetricSnapshot.fromData(
          deliveries: _deliveries,
          senders: _senders,
          drivers: _drivers,
          payments: _payments,
          ratings: _ratings,
          supportTickets: tickets,
          healthPlusPayments: _healthPlusPayments,
        );
      });
    });
  }

  Future<List<Map<String, dynamic>>> _readCollection(
    Query<Map<String, dynamic>> query,
  ) async {
    final snapshot = await query.get();
    return snapshot.docs
        .map((doc) => {
              ...doc.data(),
              '_docId': doc.id,
              'id': doc.data()['id'] ?? doc.id,
            })
        .toList(growable: false);
  }

  Future<List<Map<String, dynamic>>> _readRoleRothWallets(
    FirebaseFirestore db,
  ) async {
    final snapshot = await db.collectionGroup('wallets').limit(240).get();
    return snapshot.docs
        .where((doc) {
          final walletType = '${doc.data()['walletType'] ?? ''}'.toLowerCase();
          return walletType == 'sender' || walletType == 'rider';
        })
        .map((doc) => {
              'id': doc.id,
              'userId': doc.reference.parent.parent?.id ?? '',
              ...doc.data(),
            })
        .toList(growable: false);
  }

  Future<void> _writeAudit(AdminAuditEntry entry) async {
    await FirebaseFirestore.instance.collection('adminAuditLogs').add({
      ...entry.toJson(),
      'createdAt': FieldValue.serverTimestamp(),
    });
  }

  Future<void> _saveAdminUser({
    Map<String, dynamic>? existing,
    String? status,
  }) async {
    if (!_can(AdminPermission.manageAdmins)) {
      setState(() => _message = 'Only super admins can manage admin users.');
      return;
    }
    final email = (existing?['email'] ?? _adminInviteEmail.text)
        .toString()
        .trim()
        .toLowerCase();
    if (email.isEmpty || !email.contains('@')) {
      setState(() => _message = 'Enter a valid employee email address.');
      return;
    }
    if (email == _adminUser?.email?.trim().toLowerCase()) {
      setState(
        () => _message = 'You cannot change your own admin access here.',
      );
      return;
    }
    final role = existing == null
        ? _adminInviteRole.value
        : '${existing['role'] ?? (existing['roles'] is List && (existing['roles'] as List).isNotEmpty ? (existing['roles'] as List).first : AdminRole.operationsAdmin.value)}';
    final nextStatus = status ?? '${existing?['status'] ?? 'active'}';
    final id = '${existing?['id'] ?? AdminUserAccess.emailDocumentId(email)}';
    final patch = AdminUserAccess.adminUserPatch(
      email: email,
      role: role,
      status: nextStatus,
      invitedBy: _adminUser?.email ?? _adminUser?.uid ?? 'super_admin',
      createdAt: existing == null ? FieldValue.serverTimestamp() : null,
      updatedAt: FieldValue.serverTimestamp(),
    );
    await FirebaseFirestore.instance
        .collection('adminUsers')
        .doc(id)
        .set(patch, SetOptions(merge: true));
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType:
            existing == null ? 'admin_user_added' : 'admin_user_updated',
        recordType: 'adminUsers',
        recordId: id,
        oldValue: existing == null
            ? const {}
            : {
                'role': existing['role'] ?? existing['roles'],
                'status': existing['status'],
              },
        newValue: {'role': role, 'status': nextStatus, 'email': email},
        reason: _adminInviteNote.text.trim().isEmpty
            ? 'Admin access managed from admin panel'
            : _adminInviteNote.text.trim(),
      ),
    );
    _adminInviteEmail.clear();
    _adminInviteNote.clear();
    setState(() => _message = 'Admin access saved for $email.');
    await _loadAdminData();
  }

  Future<void> _changeAdminRole(
    Map<String, dynamic> adminUser,
    AdminRole role,
  ) async {
    if (!_can(AdminPermission.manageAdmins)) return;
    final email = '${adminUser['email'] ?? ''}'.trim().toLowerCase();
    if (email == _adminUser?.email?.trim().toLowerCase()) {
      setState(() => _message = 'You cannot change your own admin role.');
      return;
    }
    final id = '${adminUser['id'] ?? AdminUserAccess.emailDocumentId(email)}';
    final oldRole = adminUser['role'] ?? adminUser['roles'];
    await FirebaseFirestore.instance.collection('adminUsers').doc(id).set({
      'role': role.value,
      'roles': [role.value],
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: 'admin_user_role_changed',
        recordType: 'adminUsers',
        recordId: id,
        oldValue: {'role': oldRole},
        newValue: {'role': role.value},
        reason: 'Role changed from admin users page',
      ),
    );
    setState(() => _message = 'Updated $email to ${role.value}.');
    await _loadAdminData();
  }

  Future<void> _duplicateDelivery(Map<String, dynamic> delivery) async {
    if (!_can(AdminPermission.duplicateDeliveries)) {
      setState(() => _message = 'Your role cannot duplicate deliveries.');
      return;
    }
    final newId =
        'CIR-ADM-${DateTime.now().millisecondsSinceEpoch.toString().substring(7)}';
    final createdAt = FieldValue.serverTimestamp();
    final duplicate = AdminDeliveryTools.duplicateDelivery(
      delivery,
      newId: newId,
      createdAt: createdAt,
    );
    await FirebaseFirestore.instance
        .collection('deliveryRequests')
        .doc(newId)
        .set(duplicate);
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: 'delivery_duplicate',
        recordType: 'deliveryRequests',
        recordId: newId,
        oldValue: {'requestId': delivery['requestId'] ?? delivery['id']},
        newValue: {'requestId': newId},
        reason: 'Admin duplicated delivery from operations panel',
      ),
    );
    setState(() => _message = 'Duplicated delivery as $newId.');
    await _loadAdminData();
  }

  Future<void> _softDeleteDelivery(Map<String, dynamic> delivery) async {
    if (!_can(AdminPermission.editDeliveries)) {
      setState(() => _message = 'Your role cannot delete deliveries.');
      return;
    }
    final id =
        '${delivery['_docId'] ?? delivery['requestId'] ?? delivery['id'] ?? ''}'
            .trim();
    if (id.isEmpty) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Delete delivery transaction?'),
        content: Text(
          'This will hide delivery $id from the default admin delivery list. '
          'Roth ledger entries, payment records, and audit logs will not be deleted.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xffdc2626),
              foregroundColor: Colors.white,
            ),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final previousStatus = '${delivery['status'] ?? ''}';
    final adminId = _adminUser?.uid ?? _adminUser?.email ?? 'unknown-admin';
    await FirebaseFirestore.instance
        .collection('deliveryRequests')
        .doc(id)
        .set({
      'status': 'deleted',
      'deletedAt': FieldValue.serverTimestamp(),
      'deletedBy': adminId,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: 'delivery_soft_deleted',
        recordType: 'deliveryRequests',
        recordId: id,
        oldValue: {'status': previousStatus},
        newValue: {'status': 'deleted', 'deletedBy': adminId},
        reason: 'Admin soft deleted delivery transaction from deliveries table',
      ),
    );
    setState(() => _message = 'Delivery $id was deleted from the active list.');
    await _loadAdminData();
  }

  Future<void> _archiveStaleDelivery(Map<String, dynamic> delivery) async {
    if (!_can(AdminPermission.editDeliveries)) {
      setState(() => _message = 'Your role cannot archive stale orders.');
      return;
    }
    final id =
        '${delivery['_docId'] ?? delivery['requestId'] ?? delivery['id'] ?? ''}'
            .trim();
    if (id.isEmpty) return;
    final reasonController = TextEditingController();
    var reasonError = '';
    try {
      final reason = await showDialog<String>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            title: const Text('Archive stale order?'),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'This removes order ${delivery['trackingReference'] ?? delivery['reference'] ?? id} '
                  'from active matching, sender tracking, dispatch and active admin views. '
                  'Payment records and audit logs are preserved.',
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: reasonController,
                  minLines: 2,
                  maxLines: 4,
                  decoration: InputDecoration(
                    labelText: 'Cleanup reason',
                    errorText: reasonError.isEmpty ? null : reasonError,
                  ),
                ),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () {
                  final reason = reasonController.text.trim();
                  if (reason.length < 4) {
                    setDialogState(
                      () => reasonError = 'Add a clear cleanup reason.',
                    );
                    return;
                  }
                  Navigator.pop(dialogContext, reason);
                },
                child: const Text('Archive stale order'),
              ),
            ],
          ),
        ),
      );
      if (reason == null || reason.trim().isEmpty) return;
      final previousStatus = '${delivery['status'] ?? ''}';
      final reference =
          '${delivery['trackingReference'] ?? delivery['reference'] ?? delivery['requestId'] ?? id}';
      final adminId = _adminUser?.uid ?? _adminUser?.email ?? 'unknown-admin';
      final batch = FirebaseFirestore.instance.batch();
      final deliveryRef =
          FirebaseFirestore.instance.collection('deliveryRequests').doc(id);
      final cleanupRef = FirebaseFirestore.instance
          .collection('deliveryStaleCleanupEvents')
          .doc();
      batch.set(
          deliveryRef,
          {
            'status': 'archived',
            'matchingStatus': 'archived',
            'dispatchStatus': 'archived',
            'archived': true,
            'staleArchived': true,
            'active': false,
            'archivedAt': FieldValue.serverTimestamp(),
            'archivedByAdminId': adminId,
            'archivedByAdminEmail': _adminUser?.email,
            'staleCleanupReason': reason,
            'updatedAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true));
      final auditPayload = {
        'adminId': adminId,
        'adminEmail': _adminUser?.email,
        'orderId': id,
        'reference': reference,
        'previousStatus': previousStatus,
        'newStatus': 'archived',
        'reason': reason,
        'timestamp': FieldValue.serverTimestamp(),
      };
      batch.set(cleanupRef, auditPayload);
      batch.set(FirebaseFirestore.instance.collection('adminAuditLogs').doc(), {
        ...auditPayload,
        'action': 'stale_delivery_archived',
        'actionType': 'stale_delivery_archived',
        'recordType': 'deliveryRequests',
        'recordId': id,
        'createdAt': FieldValue.serverTimestamp(),
      });
      await batch.commit();
      setState(() =>
          _message = 'Order $reference was archived from active system views.');
      await _loadAdminData();
    } finally {
      reasonController.dispose();
    }
  }

  Future<List<String>> _uploadGiftStoryPhotoFiles(
    String giftRequestId,
    List<XFile> files,
  ) async {
    if (files.isEmpty) return const [];
    final urls = <String>[];
    for (var i = 0; i < files.length; i++) {
      final file = files[i];
      final lower = file.name.toLowerCase();
      final extension = lower.endsWith('.jpeg')
          ? 'jpg'
          : lower.endsWith('.png')
              ? 'png'
              : lower.endsWith('.webp')
                  ? 'webp'
                  : 'jpg';
      final valid = lower.endsWith('.jpg') ||
          lower.endsWith('.jpeg') ||
          lower.endsWith('.png') ||
          lower.endsWith('.webp');
      if (!valid) {
        throw StateError('Only JPG, JPEG, PNG or WEBP images can be attached.');
      }
      final bytes = await file.readAsBytes();
      if (bytes.length > 8 * 1024 * 1024) {
        throw StateError('${file.name} is larger than 8 MB.');
      }
      final contentType = switch (extension) {
        'png' => 'image/png',
        'webp' => 'image/webp',
        _ => 'image/jpeg',
      };
      final storageRef = FirebaseStorage.instance.ref(
        'gift_story/$giftRequestId/${DateTime.now().millisecondsSinceEpoch}_$i.$extension',
      );
      await storageRef.putData(
        bytes,
        SettableMetadata(
          contentType: contentType,
          customMetadata: {
            'purpose': 'gift_story_approved_photo',
            'uploadedBy': _adminUser?.uid ?? _adminUser?.email ?? 'admin',
          },
        ),
      );
      urls.add(await storageRef.getDownloadURL());
    }
    return urls;
  }

  Future<XFile?> _pickGiftStoryAudioFile() async {
    final completer = Completer<XFile?>();
    final input = html.FileUploadInputElement()
      ..accept =
          'audio/mpeg,audio/mp4,audio/wav,audio/x-wav,audio/aac,.mp3,.m4a,.wav,.aac';
    input.onChange.first.then((_) {
      final file = input.files?.isNotEmpty == true ? input.files!.first : null;
      if (file == null) {
        completer.complete(null);
        return;
      }
      debugPrint(
          'Gift Story admin audio selected: name=${file.name}, type=${file.type}, size=${file.size}');
      final reader = html.FileReader();
      reader.onLoadEnd.first.then((_) {
        final bytes = _bytesFromFileReaderResult(reader.result);
        if (bytes == null) {
          completer.completeError(StateError(
              'Corrupted file: the browser could not read this audio file.'));
          return;
        }
        debugPrint(
            'Gift Story admin audio read: name=${file.name}, bytes=${bytes.length}, type=${file.type}');
        completer.complete(XFile.fromData(
          bytes,
          name: file.name,
          mimeType: file.type.isEmpty ? 'audio/mpeg' : file.type,
        ));
      });
      reader.onError.first.then((_) {
        completer.completeError(StateError(
            'Corrupted file: the browser could not read this audio file.'));
      });
      reader.readAsArrayBuffer(file);
    });
    input.click();
    return completer.future;
  }

  Future<String> _uploadGiftStoryAudioFile(
    String giftRequestId,
    XFile file,
  ) async {
    final extension = _giftStoryAudioExtension(file.name, file.mimeType);
    if (extension == null) throw StateError(_unsupportedGiftStoryAudioMessage);
    final bytes = await file.readAsBytes();
    debugPrint(
        'Gift Story admin audio upload starting: name=${file.name}, mime=${file.mimeType}, ext=$extension, size=${bytes.length}');
    if (bytes.length > 20 * 1024 * 1024) {
      throw StateError('${file.name} is larger than 20 MB.');
    }
    final contentType = _giftStoryAudioContentType(extension);
    final storageRef = FirebaseStorage.instance.ref(
      'gift_story/$giftRequestId/audio/${DateTime.now().millisecondsSinceEpoch}.$extension',
    );
    try {
      await storageRef.putData(
        bytes,
        SettableMetadata(
          contentType: contentType,
          customMetadata: {
            'purpose': 'gift_story_custom_music',
            'uploadedBy': _adminUser?.uid ?? _adminUser?.email ?? 'admin',
            'originalFilename': file.name,
          },
        ),
      );
      final metadata = await storageRef.getMetadata();
      final url = await storageRef.getDownloadURL();
      debugPrint(
          'Gift Story admin audio uploaded: path=${metadata.fullPath}, size=${metadata.size}, contentType=${metadata.contentType}, url=$url');
      await _probeGiftStoryAudioUrl(url);
      return url;
    } on FirebaseException catch (error) {
      debugPrint(
          'Gift Story admin audio storage error: code=${error.code}, message=${error.message}');
      throw StateError(
          'Storage permission error: ${error.message ?? error.code}');
    } catch (error) {
      debugPrint('Gift Story admin audio upload/decode error: $error');
      rethrow;
    }
  }

  Future<void> _previewGiftStoryAudio(XFile? pendingAudio, String? url) async {
    try {
      String? source = url;
      if (pendingAudio != null) {
        final bytes = await pendingAudio.readAsBytes();
        final extension =
            _giftStoryAudioExtension(pendingAudio.name, pendingAudio.mimeType);
        if (extension == null) {
          throw StateError(_unsupportedGiftStoryAudioMessage);
        }
        source =
            'data:${_giftStoryAudioContentType(extension)};base64,${base64Encode(bytes)}';
      }
      if (source == null || source.trim().isEmpty) return;
      final audio = html.AudioElement(source)
        ..preload = 'auto'
        ..volume = 1;
      audio.onError.listen((_) {
        debugPrint(
            'Gift Story admin audio element error: network=${audio.networkState}, ready=${audio.readyState}, src=$source');
      });
      await audio.play();
      debugPrint('Gift Story admin audio preview playing: $source');
    } catch (error) {
      debugPrint('Gift Story admin audio preview failed: $error');
      rethrow;
    }
  }

