  Future<void> _updateRecordStatus(
    String collection,
    Map<String, dynamic> record,
    String status,
  ) async {
    final id =
        '${collection == 'deliveryRequests' ? (record['_docId'] ?? record['requestId'] ?? record['id']) : (record['id'] ?? record['requestId']) ?? ''}';
    if (id.isEmpty) return;
    final oldStatus = '${record['status'] ?? record['driverStatus'] ?? ''}';
    await FirebaseFirestore.instance.collection(collection).doc(id).set({
      if (collection == 'riderProfiles')
        'driverStatus': status
      else
        'status': status,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: 'status_update',
        recordType: collection,
        recordId: id,
        oldValue: {'status': oldStatus},
        newValue: {'status': status},
        reason: 'Updated from admin operations panel',
      ),
    );
    setState(() => _message = 'Updated $id to $status.');
    await _loadAdminData();
  }

  String _driverId(Map<String, dynamic> driver) {
    return '${driver['id'] ?? driver['uid'] ?? driver['riderId'] ?? driver['driverId'] ?? ''}'
        .trim();
  }

  Map<String, dynamic> _driverVehicle(Map<String, dynamic> driver) {
    final nested = driver['vehicle'];
    final vehicle = nested is Map ? Map<String, dynamic>.from(nested) : {};
    String read(List<String> keys) {
      for (final key in keys) {
        final value = '${vehicle[key] ?? driver[key] ?? ''}'.trim();
        if (value.isNotEmpty && value != 'null') return value;
      }
      return '';
    }

    return {
      'type': read(['type', 'vehicleType', 'typeOfVehicle']),
      'makeModel': read(['makeModel', 'vehicleMakeModel']),
      'colour': read(['colour', 'color', 'vehicleColour']),
      'plateNumber':
          read(['plateNumber', 'vehicleRegistration', 'registration']),
    };
  }

  String _driverVehicleSummary(Map<String, dynamic> driver) {
    final vehicle = _driverVehicle(driver);
    final parts = [
      '${vehicle['colour'] ?? ''}'.trim(),
      '${vehicle['makeModel'] ?? ''}'.trim(),
      '${vehicle['type'] ?? ''}'.trim(),
    ].where((part) => part.isNotEmpty).toList();
    return parts.isEmpty ? 'Vehicle not provided' : parts.join(' ');
  }

  String _driverPlateSummary(Map<String, dynamic> driver) {
    final plate = '${_driverVehicle(driver)['plateNumber'] ?? ''}'.trim();
    return plate.isEmpty ? 'Plate not provided' : plate;
  }

  String _driverPhone(Map<String, dynamic> driver) {
    final phone = '${driver['phone'] ?? driver['phoneNumber'] ?? ''}'.trim();
    return phone.isEmpty ? 'Phone not provided' : phone;
  }

  List<String> _driverApprovalBlockers(Map<String, dynamic> driver) {
    final blockers = <String>[];
    final vehicle = _driverVehicle(driver);
    final documents = _documentsForDriver(_driverId(driver));
    if (_driverPhone(driver) == 'Phone not provided') {
      blockers.add('Phone missing');
    }
    if (driver['phoneVerified'] != true) {
      blockers.add('Phone not verified');
    }
    if ('${vehicle['type'] ?? ''}'.trim().isEmpty) {
      blockers.add('Vehicle type missing');
    }
    if ('${vehicle['makeModel'] ?? ''}'.trim().isEmpty) {
      blockers.add('Vehicle make/model missing');
    }
    if ('${vehicle['colour'] ?? ''}'.trim().isEmpty) {
      blockers.add('Vehicle colour missing');
    }
    if ('${vehicle['plateNumber'] ?? ''}'.trim().isEmpty) {
      blockers.add('Vehicle registration missing');
    }
    if (!_hasApprovedRiderDocument(documents, const [
      'identity',
      'international passport',
      'passport',
      'id',
    ])) {
      blockers.add('Identity document missing');
    }
    if (!_hasApprovedRiderDocument(documents, const [
      'right_to_work',
      'right to work',
      'work permit',
    ])) {
      blockers.add('Right to work document missing');
    }
    if (!_hasApprovedRiderDocument(documents, const [
      'driving_licence',
      'drivers license',
      'driver license',
      'driving licence',
    ])) {
      blockers.add('Driving licence missing');
    }
    if (!_hasApprovedRiderDocument(documents, const ['insurance'])) {
      blockers.add('Insurance document missing');
    }
    final vehicleType = '${vehicle['type'] ?? ''}'.toLowerCase();
    if ((vehicleType.contains('car') || vehicleType.contains('van')) &&
        !_hasApprovedRiderDocument(documents, const [
          'vehicle_registration',
          'vehicle registration',
          'v5c',
          'mot',
        ])) {
      blockers.add('Vehicle Registration (V5C/MOT) missing');
    }
    return blockers;
  }

  bool _hasApprovedRiderDocument(
    List<Map<String, dynamic>> documents,
    List<String> typeHints,
  ) {
    return documents.any((document) {
      final type =
          '${document['documentType'] ?? document['type'] ?? document['idType'] ?? ''}'
              .toLowerCase();
      final status =
          '${document['status'] ?? document['verificationStatus'] ?? ''}'
              .toLowerCase();
      return status == 'approved' &&
          typeHints.any((hint) => type.contains(hint));
    });
  }

  String _driverWorkflowStatus(Map<String, dynamic> driver) {
    if (driver.containsKey('onboardingStatus')) {
      return switch (RiderOnboardingPolicy.status(driver)) {
        'approved' => 'approved',
        'rejected' => 'rejected',
        'suspended' => 'suspended',
        _ => 'pending',
      };
    }
    final raw = [
      driver['approvalStatus'],
      driver['driverStatus'],
      driver['verificationStatus'],
      driver['status'],
    ]
        .where((value) => value != null)
        .map((value) => '$value'.toLowerCase())
        .join(' ')
        .toLowerCase()
        .trim();
    if (raw.contains('suspend')) return 'suspended';
    if (raw.contains('reject')) return 'rejected';
    if (raw.contains('active') ||
        raw.contains('approve') ||
        raw.contains('verified')) {
      return 'approved';
    }
    return 'pending';
  }

  String _driverStatusLabel(Map<String, dynamic> driver) {
    return switch (_driverWorkflowStatus(driver)) {
      'approved' => 'approved',
      'suspended' => 'suspended',
      'rejected' => 'rejected',
      _ => 'pending',
    };
  }

  String _driverStripePayoutStatus(Map<String, dynamic> driver) {
    final accountId =
        '${driver['stripeAccountId'] ?? driver['stripeConnectAccountId'] ?? ''}'
            .trim();
    final stripeStatus = '${driver['stripeStatus'] ?? ''}'.trim();
    if (stripeStatus == 'payouts_enabled') return 'Payouts Enabled';
    if (stripeStatus == 'connected') return 'Connected';
    if (stripeStatus == 'action_required') return 'Action Required';
    if (stripeStatus == 'onboarding') return 'Onboarding';
    if (stripeStatus == 'restricted') return 'Restricted';
    if (stripeStatus == 'disabled') return 'Disabled';
    if (accountId.isEmpty) return 'Not started';
    if (driver['stripePayoutsEnabled'] == true ||
        driver['payoutsEnabled'] == true) {
      return 'Payouts Enabled';
    }
    if (driver['stripeOnboardingStatus'] == 'complete' ||
        driver['onboardingComplete'] == true) {
      return 'Complete';
    }
    if (driver['stripeDisabledReason'] != null ||
        driver['payoutPaused'] == true) {
      return 'Payouts disabled';
    }
    return 'Incomplete';
  }

  String _driverStripeModeLabel(Map<String, dynamic> driver) {
    final mode = '${driver['stripeMode'] ?? driver['staleStripeMode'] ?? ''}'
        .trim()
        .toLowerCase();
    if (mode == 'live') return 'live';
    if (mode == 'test' || mode == 'test_or_missing') return 'test';
    final accountId =
        '${driver['stripeAccountId'] ?? driver['stripeConnectAccountId'] ?? ''}'
            .trim();
    return accountId.isEmpty ? 'not started' : 'not synced';
  }

  bool _driverHasTestStripeAccount(Map<String, dynamic> driver) {
    final mode = '${driver['stripeMode'] ?? driver['staleStripeMode'] ?? ''}'
        .trim()
        .toLowerCase();
    return mode == 'test' || mode == 'test_or_missing';
  }

  Future<void> _syncDriverStripeStatus(Map<String, dynamic> driver) async {
    final riderId = _driverId(driver);
    if (riderId.isEmpty) return;
    setState(() => _message = 'Syncing rider Stripe status...');
    try {
      await FirebaseFunctions.instanceFor(region: 'us-central1')
          .httpsCallable('syncStripeConnectStatus')
          .call({'riderId': riderId});
      await _loadAdminData();
      if (!mounted) return;
      setState(() => _message = 'Rider Stripe status synced.');
    } on FirebaseFunctionsException catch (error) {
      if (!mounted) return;
      setState(
        () => _message = error.message ?? 'Could not sync rider Stripe status.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _message = 'Could not sync rider Stripe status.');
    }
  }

  Future<void> _resetDriverTestStripeAccount(
      Map<String, dynamic> driver) async {
    final riderId = _driverId(driver);
    if (riderId.isEmpty) return;
    setState(() => _message = 'Resetting rider Stripe account link...');
    try {
      await FirebaseFunctions.instanceFor(region: 'us-central1')
          .httpsCallable('resetRiderTestStripeAccount')
          .call({'riderId': riderId});
      await _loadAdminData();
      if (!mounted) return;
      setState(
        () => _message =
            'Test Stripe account reset. The rider can start live onboarding again.',
      );
    } on FirebaseFunctionsException catch (error) {
      if (!mounted) return;
      setState(
        () => _message =
            error.message ?? 'Could not reset this rider Stripe account.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _message = 'Could not reset this rider Stripe account.');
    }
  }

  Future<void> _setDriverWorkflowStatus(
    Map<String, dynamic> driver,
    String nextStatus,
  ) async {
    if (!_can(AdminPermission.approveDrivers)) {
      setState(() => _message = 'Your role cannot manage driver status.');
      return;
    }
    final id = _driverId(driver);
    if (id.isEmpty) return;
    final previous = _driverWorkflowStatus(driver);
    if (nextStatus == 'approved') {
      final blockers = _driverApprovalBlockers(driver);
      if (blockers.isNotEmpty) {
        setState(() {
          _message = 'Cannot approve rider:\n- ${blockers.join('\n- ')}';
        });
        return;
      }
    }
    final action = switch (nextStatus) {
      'approved' => previous == 'suspended' || previous == 'rejected'
          ? 'driver_reactivated'
          : 'driver_approved',
      'rejected' => 'driver_rejected',
      'suspended' => 'driver_suspended',
      _ => 'driver_status_updated',
    };
    final riderEventAction = switch (nextStatus) {
      'approved' => previous == 'suspended' || previous == 'rejected'
          ? 'rider_reactivated'
          : 'rider_approved',
      'rejected' => 'rider_rejected',
      'suspended' => 'rider_suspended',
      _ => 'rider_status_updated',
    };
    final driverStatus = switch (nextStatus) {
      'approved' => 'active',
      'rejected' => 'rejected',
      'suspended' => 'suspended',
      _ => nextStatus,
    };
    String rejectionReason = '';
    if (nextStatus == 'rejected') {
      rejectionReason = await _requestDriverRejectionReason() ?? '';
      if (rejectionReason.isEmpty) return;
    }
    final reviewPatch = nextStatus == 'approved' || nextStatus == 'rejected'
        ? RiderOnboardingPolicy.adminReviewPatch(
            approved: nextStatus == 'approved',
            rejectionReason: rejectionReason,
          )
        : <String, dynamic>{
            'approvalStatus': nextStatus,
            'verificationStatus': nextStatus,
          };
    final reviewedAt = FieldValue.serverTimestamp();
    await FirebaseFirestore.instance.collection('riderProfiles').doc(id).set({
      ...reviewPatch,
      'driverStatus': driverStatus,
      if (nextStatus == 'approved' &&
          '${driver['riderRank'] ?? ''}'.trim().isEmpty)
        'riderRank': 'agent',
      'onboardingReviewedAt': reviewedAt,
      'onboardingReviewedBy': _adminUser?.uid ?? _adminUser?.email,
      if (nextStatus == 'rejected') 'rejectionReason': rejectionReason,
      if (nextStatus == 'approved') 'rejectionReason': FieldValue.delete(),
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: action,
        recordType: 'riderProfiles',
        recordId: id,
        oldValue: {'status': previous},
        newValue: {
          'status': nextStatus,
          'adminId': _adminUser?.uid ?? 'unknown-admin',
          'action': action,
          'driverId': id,
        },
        reason: rejectionReason.isEmpty
            ? 'Driver management workflow action'
            : rejectionReason,
      ),
    );
    await FirebaseFirestore.instance.collection('riderAdminEvents').add({
      'riderId': id,
      'adminId': _adminUser?.uid ?? 'unknown-admin',
      'adminEmail': _adminUser?.email,
      'action': riderEventAction,
      'previousStatus': previous,
      'newStatus': nextStatus,
      'note': rejectionReason.isEmpty ? null : rejectionReason,
      'createdAt': FieldValue.serverTimestamp(),
    });
    setState(() {
      _message = 'Driver $id updated to $nextStatus.';
      if (_selectedDriverProfile != null &&
          _driverId(_selectedDriverProfile!) == id) {
        _selectedDriverProfile = {
          ..._selectedDriverProfile!,
          'onboardingStatus': nextStatus,
          'approvalStatus': nextStatus,
          'driverStatus': driverStatus,
          'verificationStatus':
              nextStatus == 'approved' ? 'approved' : nextStatus,
        };
      }
    });
    await _loadAdminData();
  }

