            ),
            FilledButton(
              onPressed: fields.isEmpty
                  ? null
                  : () => Navigator.pop(dialogContext, {
                        'fields': fields.toList(),
                        'note': noteController.text.trim(),
                      }),
              child: const Text('Request'),
            ),
          ],
        ),
      ),
    );
    noteController.dispose();
    if (result == null) return;
    final note = '${result['note'] ?? ''}'.trim();
    final patch = {
      'approvalStatus': 'needs_information',
      'driverStatus': 'pending',
      'adminReviewNote': note,
      'needsInformationFields': result['fields'],
      'updatedAt': FieldValue.serverTimestamp(),
    };
    await FirebaseFirestore.instance
        .collection('riderProfiles')
        .doc(riderId)
        .set(patch, SetOptions(merge: true));
    await FirebaseFirestore.instance
        .collection('riders')
        .doc(riderId)
        .set(patch, SetOptions(merge: true));
    await _writeRiderAdminEvent(
      riderId,
      'more_info_requested',
      previousStatus: _driverWorkflowStatus(driver),
      newStatus: 'needs_information',
      note: note,
    );
    setState(() => _message = 'Requested more information from rider.');
    await _loadAdminData();
  }

  List<_AdminAction> _driverWorkflowActions(Map<String, dynamic> driver) {
    final status = _driverWorkflowStatus(driver);
    final canApprove = _can(AdminPermission.approveDrivers);
    final canEdit = _can(AdminPermission.editDrivers);
    final actions = <_AdminAction>[];
    if (status == 'pending') {
      actions.addAll([
        _AdminAction(
          label: 'Approve',
          enabled: canApprove,
          onTap: () => _setDriverWorkflowStatus(driver, 'approved'),
        ),
        _AdminAction(
          label: 'Reject',
          enabled: canApprove,
          onTap: () => _setDriverWorkflowStatus(driver, 'rejected'),
        ),
      ]);
    } else if (status == 'approved') {
      actions.addAll([
        _AdminAction(
          label: 'Suspend',
          enabled: canApprove,
          onTap: () => _setDriverWorkflowStatus(driver, 'suspended'),
        ),
        _AdminAction(
          label: 'Message',
          enabled: canEdit,
          onTap: () => _openDriverMessage(driver),
        ),
      ]);
    } else if (status == 'suspended') {
      actions.addAll([
        _AdminAction(
          label: 'Reactivate',
          enabled: canApprove,
          onTap: () => _setDriverWorkflowStatus(driver, 'approved'),
        ),
        _AdminAction(
          label: 'Message',
          enabled: canEdit,
          onTap: () => _openDriverMessage(driver),
        ),
      ]);
    } else if (status == 'rejected') {
      actions.add(
        _AdminAction(
          label: 'Reactivate',
          enabled: canApprove,
          onTap: () => _setDriverWorkflowStatus(driver, 'approved'),
        ),
      );
    }
    actions.add(
      _AdminAction(
        label: 'Change Rank',
        enabled: _can(AdminPermission.manageDriverRanks),
        onTap: () => _changeDriverRank(driver),
      ),
    );
    actions.addAll([
      _AdminAction(
        label: 'Mark Phone Verified',
        enabled: canApprove && driver['phoneVerified'] != true,
        onTap: () => _markDriverTrustField(
          driver,
          'phoneVerified',
          'phone_verified_manually',
        ),
      ),
      _AdminAction(
        label: 'Mark Vehicle Verified',
        enabled: canApprove && driver['vehicleVerified'] != true,
        onTap: () => _markDriverTrustField(
          driver,
          'vehicleVerified',
          'vehicle_verified',
        ),
      ),
      _AdminAction(
        label: 'Mark Documents Verified',
        enabled: canApprove && driver['documentsVerified'] != true,
        onTap: () => _markDriverTrustField(
          driver,
          'documentsVerified',
          'documents_verified',
        ),
      ),
      _AdminAction(
        label: 'Request Info',
        enabled: canApprove,
        onTap: () => _requestDriverMoreInformation(driver),
      ),
      _AdminAction(
        label: 'Sync Stripe Status',
        enabled: _can(AdminPermission.viewFinance),
        onTap: () => _syncDriverStripeStatus(driver),
      ),
      _AdminAction(
        label: 'Reset Test Stripe Account',
        enabled: _can(AdminPermission.viewFinance) &&
            (_driverHasTestStripeAccount(driver) ||
                '${driver['stripeAccountId'] ?? driver['stripeConnectAccountId'] ?? ''}'
                    .trim()
                    .isNotEmpty),
        onTap: () => _resetDriverTestStripeAccount(driver),
      ),
    ]);
    actions.add(
      _AdminAction(
        label: 'View Profile',
        enabled: true,
        onTap: () => _openDriverProfile(driver),
      ),
    );
    return actions;
  }

  Future<void> _updateSupportTicket(
    Map<String, dynamic> ticket,
    String status,
  ) async {
    if (!_can(AdminPermission.manageIssues)) {
      setState(() => _message = 'Your role cannot update support tickets.');
      return;
    }
    final id = '${ticket['id'] ?? ''}';
    if (id.isEmpty) return;
    final oldStatus = '${ticket['status'] ?? ''}';
    final patch = AdminSupportTools.statusPatch(
      status: status,
      assignedTo: status == 'assigned' ? _adminUser?.email : null,
      resolutionNote: status == 'resolved'
          ? 'Resolved from the admin operations panel'
          : null,
      updatedAt: FieldValue.serverTimestamp(),
    );
    await FirebaseFirestore.instance
        .collection('supportTickets')
        .doc(id)
        .set(patch, SetOptions(merge: true));
    final chatId = '${ticket['chatId'] ?? ''}'.trim();
    if (chatId.isNotEmpty) {
      await FirebaseFirestore.instance.collection('chats').doc(chatId).set({
        'status': status == 'resolved' ? 'resolved' : 'open',
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: 'support_ticket_$status',
        recordType: 'supportTickets',
        recordId: id,
        oldValue: {'status': oldStatus},
        newValue: {'status': status},
        reason: 'Updated from admin operations panel',
      ),
    );
    setState(() => _message = 'Support ticket $id updated to $status.');
    await _loadAdminData();
  }

  Future<void> _updateHealthPlusPickup(
    Map<String, dynamic> pickup,
    String status,
  ) async {
    if (!_can(AdminPermission.manageHealthPlus)) {
      setState(() => _message = 'Your role cannot update Health+ pickups.');
      return;
    }
    final id = '${pickup['id'] ?? ''}';
    if (id.isEmpty) return;
    final requiresReason = [
      'escalated',
      'rescheduled',
      'prescription_not_ready',
      'customer_unavailable',
      'override_completed',
    ].contains(status);
    final reason = requiresReason
        ? await _healthPlusAdminReason(status.replaceAll('_', ' '))
        : 'Updated from the Health+ operations panel';
    if (reason == null) return;
    final oldStatus = '${pickup['status'] ?? ''}';
    final patch = AdminHealthPlusTools.statusPatch(
      status: status,
      updatedAt: FieldValue.serverTimestamp(),
    );
    await FirebaseFirestore.instance
        .collection('prescriptionPickups')
        .doc(id)
        .set(patch, SetOptions(merge: true));
    await FirebaseFirestore.instance.collection('healthPlusUsageEvents').add({
      'type': 'admin_status_updated',
      'pickupId': id,
      'status': status,
      'source': 'circum-admin',
      'adminUserId': _adminUser?.uid,
      'adminName': _adminUser?.displayName ?? _adminUser?.email,
      'reason': reason,
      'createdAt': FieldValue.serverTimestamp(),
    });
    await FirebaseFirestore.instance
        .collection('healthPlusCustodyArchive')
        .add({
      'pickupId': id,
      'profileId': pickup['profileId'],
      'scheduleId': pickup['scheduleId'],
      'userId': pickup['userId'] ?? pickup['senderId'],
      'eventType':
          status == 'override_completed' ? 'override_completion' : status,
      'timestamp': FieldValue.serverTimestamp(),
      'actorType': 'admin',
      'actorId': _adminUser?.uid,
      'actorName': _adminUser?.displayName ?? _adminUser?.email,
      'publicMessage': _healthPlusPublicStatusMessage(status),
      'internalNote': reason,
      'evidenceUrl': null,
      'statusAfterEvent': status,
      'createdAt': FieldValue.serverTimestamp(),
    });
    await _writeAudit(
      AdminAuditEntry(
        adminUserId: _adminUser?.uid ?? 'unknown-admin',
        actionType: 'health_plus_status_update',
        recordType: 'prescriptionPickups',
        recordId: id,
        oldValue: {'status': oldStatus},
        newValue: {'status': status},
        reason: reason,
      ),
    );
    setState(() => _message = 'Health+ pickup $id updated to $status.');
    await _loadAdminData();
  }

  Future<String?> _healthPlusAdminReason(String action) async {
    final controller = TextEditingController();
    final reason = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('Health+ ${action.trim()}'),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLines: 3,
          decoration: const InputDecoration(
            labelText: 'Admin reason',
            hintText: 'Required for the custody archive',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () {
              final value = controller.text.trim();
              if (value.isNotEmpty) Navigator.pop(dialogContext, value);
            },
            child: const Text('Confirm action'),
          ),
        ],
      ),
    );
    controller.dispose();
    return reason;
  }

