  void _openAdminChat(Map<String, dynamic> delivery) {
    final id = '${delivery['id'] ?? delivery['requestId'] ?? ''}'.trim();
    if (id.isEmpty) return;
    _adminChatSub?.cancel();
    _adminChatSub = FirebaseFirestore.instance
        .collection('chats')
        .doc(id)
        .collection('messages')
        .orderBy('createdAt')
        .limit(100)
        .snapshots()
        .listen(
      (snapshot) {
        if (!mounted) return;
        setState(() {
          _adminChatMessages
            ..clear()
            ..addAll(
              snapshot.docs.map((doc) {
                final data = doc.data();
                final role =
                    '${data['senderRole'] ?? data['senderType'] ?? ''}';
                return _ChatMessage(
                  fromMe:
                      role == 'admin' || data['senderId'] == _adminUser?.uid,
                  text: '${data['messageText'] ?? data['message'] ?? ''}',
                  time: _formatMessageTime(
                    data['createdAt'],
                    data['timeStamp'],
                  ),
                  label: role == 'admin' || role == 'support'
                      ? 'CIRCUM Support'
                      : role == 'rider' || role == 'driver'
                          ? 'Rider'
                          : 'Sender',
                );
              }).where((message) => message.text.trim().isNotEmpty),
            );
        });
      },
      onError: (_) {
        if (!mounted) return;
        setState(() => _message = 'Could not open booking chat.');
      },
    );
    setState(() {
      _activeAdminChatId = id;
      _activeAdminTicketId = null;
      _activeAdminChatTitle = 'Booking chat';
      _adminChatOpen = true;
    });
  }

  Future<void> _openSupportTicketChat(Map<String, dynamic> ticket) async {
    final ticketId = '${ticket['id'] ?? ''}'.trim();
    if (ticketId.isEmpty) return;
    final chatId = '${ticket['chatId'] ?? 'support_$ticketId'}'.trim();
    final customerId = '${ticket['userId'] ?? ticket['senderId'] ?? ''}'.trim();
    final participants = <String>{'circum-support'};
    if (customerId.isNotEmpty) participants.add(customerId);
    final chatRef = FirebaseFirestore.instance.collection('chats').doc(chatId);
    await chatRef.set({
      'threadId': chatId,
      'type': 'support',
      'ticketId': ticketId,
      'participants': FieldValue.arrayUnion(participants.toList()),
      'participantRoles': {
        'circum-support': 'admin',
        if (customerId.isNotEmpty) customerId: 'shipper',
      },
      'status':
          AdminSupportTools.isResolved(ticket['status']) ? 'resolved' : 'open',
      'updatedAt': FieldValue.serverTimestamp(),
      'source': 'circum-admin',
    }, SetOptions(merge: true));
    await FirebaseFirestore.instance
        .collection('supportTickets')
        .doc(ticketId)
        .set({
      'chatId': chatId,
      'adminUnreadCount': 0,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));

    final initialText = '${ticket['message'] ?? ''}'.trim();
    if (initialText.isNotEmpty) {
      final initialRef = chatRef.collection('messages').doc('ticket_initial');
      final initial = await initialRef.get();
      if (!initial.exists) {
        await initialRef.set({
          'threadId': chatId,
          'ticketId': ticketId,
          'senderId': customerId.isEmpty ? 'support-guest' : customerId,
          'senderRole': 'shipper',
          'messageText': initialText,
          'message': initialText,
          'attachments': const [],
          'initialSupportRequest': true,
          'readBy': const [],
          'createdAt': ticket['createdAt'] ?? FieldValue.serverTimestamp(),
        });
      }
    }

    _listenToAdminChat(chatId, errorMessage: 'Could not open support chat.');
    setState(() {
      _activeAdminChatId = chatId;
      _activeAdminTicketId = ticketId;
      _activeAdminChatTitle = 'Support ticket $ticketId';
      _adminChatOpen = true;
    });
  }

  void _listenToAdminChat(String chatId, {required String errorMessage}) {
    _adminChatSub?.cancel();
    _adminChatSub = FirebaseFirestore.instance
        .collection('chats')
        .doc(chatId)
        .collection('messages')
        .orderBy('createdAt')
        .limit(100)
        .snapshots()
        .listen(
      (snapshot) {
        if (!mounted) return;
        setState(() {
          _adminChatMessages
            ..clear()
            ..addAll(snapshot.docs.map((doc) {
              final data = doc.data();
              final role = '${data['senderRole'] ?? data['senderType'] ?? ''}';
              return _ChatMessage(
                fromMe: role == 'admin' || data['senderId'] == _adminUser?.uid,
                text: '${data['messageText'] ?? data['message'] ?? ''}',
                time: _formatMessageTime(data['createdAt'], data['timeStamp']),
                label: role == 'admin' || role == 'support'
                    ? 'CIRCUM Support'
                    : role == 'rider' || role == 'driver'
                        ? 'Rider'
                        : 'Shipper',
              );
            }).where((message) => message.text.trim().isNotEmpty));
        });
      },
      onError: (_) {
        if (mounted) setState(() => _message = errorMessage);
      },
    );
  }

  void _openDriverProfile(Map<String, dynamic> driver) {
    setState(() {
      _selectedDriverProfile = driver;
      _driverProfileOpen = true;
    });
  }

  Future<void> _issueRothToRider(Map<String, dynamic> driver) async {
    if (!_can(AdminPermission.viewFinance)) {
      setState(() => _message = 'Only finance admins can issue Rider Roth.');
      return;
    }
    final riderId = _driverId(driver);
    if (riderId.isEmpty) {
      setState(() => _message = 'Rider account ID is missing.');
      return;
    }
    final amountController = TextEditingController();
    final reasonController = TextEditingController();
    final riderName = '${driver['fullName'] ?? driver['name'] ?? 'this rider'}';
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Issue Rider Roth'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Rider account: $riderName'),
            const SizedBox(height: 12),
            TextField(
              controller: amountController,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
              ),
              decoration: const InputDecoration(labelText: 'Roth amount'),
            ),
            const SizedBox(height: 10),
            TextField(
              controller: reasonController,
              decoration: const InputDecoration(labelText: 'Reason/note'),
            ),
            const SizedBox(height: 12),
            const Text(
              'This credits the Rider wallet only. Roth is Circum internal credit and cannot be withdrawn as cash.',
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Issue Roth'),
          ),
        ],
      ),
    );
    if (confirmed != true) {
      amountController.dispose();
      reasonController.dispose();
      return;
    }
    final amount = double.tryParse(amountController.text.trim()) ?? 0;
    final reason = reasonController.text.trim();
    amountController.dispose();
    reasonController.dispose();
    if (amount <= 0 || reason.isEmpty) {
      setState(() => _message = 'Rider Roth issue requires amount and reason.');
      return;
    }
    try {
      final idempotencyKey =
          'admin_rider_${_adminUser?.uid ?? _adminUser?.email}_${riderId}_${DateTime.now().microsecondsSinceEpoch}';
      final result = await FirebaseFunctions.instance
          .httpsCallable('issueRothToWallets')
          .call({
        'recipientUid': riderId,
        'walletTarget': 'rider',
        'amount': amount,
        'reason': reason,
        'idempotencyKey': idempotencyKey,
      });
      final data = Map<String, dynamic>.from(result.data as Map);
      setState(() => _message =
          'Rider Roth issued. Admin issue ID: ${data['adminIssueId']}');
      await _loadAdminData();
    } catch (error) {
      setState(() => _message = 'Rider Roth issue failed: $error');
    }
  }

