    if (_adminUser == null || !AdminAccessPolicy.hasAnyAdminRole(_roles)) {
      return _AdminLoginView(
        colors: colors,
        darkMode: widget.darkMode,
        email: _email,
        password: _password,
        signingIn: _signingIn,
        message: _message,
        onBack: widget.onBack,
        onToggleTheme: widget.onToggleTheme,
        onSubmit: _signIn,
      );
