            TextButton(
              onPressed: () {
                final recommendation = const GiftsRecommendationEngine().recommend(
                    budget: ((item['grossBudget'] as num?)?.toDouble() ??
                        (item['budget'] as num?)?.toDouble() ??
                        50),
                    relationship: '${item['relationship'] ?? 'Friend'}',
                    occasion: '${item['occasion'] ?? 'Birthday'}',
                    interests: (item['interests'] as List?)
                            ?.map((interest) => '$interest') ??
                        const <String>[],
                    ageRange: '${item['ageRange'] ?? ''}'.trim().isEmpty
                        ? null
                        : '${item['ageRange']}',
                    gender: '${item['gender'] ?? ''}'.trim().isEmpty
                        ? null
                        : '${item['gender']}',
                    deliveryDate: item['deliveryDate'] is Timestamp
                        ? (item['deliveryDate'] as Timestamp).toDate()
                        : DateTime.tryParse('${item['deliveryDate'] ?? ''}'),
                    notes:
                        '${item['notes'] ?? ''} ${item['personalMessage'] ?? ''}');
                generatedRecommendation = recommendation.toMap();
                setDialogState(() => irisGiftRecommendation = recommendation);
                plan.text = _formatGiftRecommendationForAdmin(recommendation);
                if (decision.text.trim().isEmpty) {
                  decision.text =
                      'Gifts Team to review recommended experience, safety warnings and procurement notes before approval.';
                }
              },
              child: const Text('Generate Recommended Experience'),
            ),
            TextButton(
                onPressed: () => Navigator.pop(context),
                child: const Text('Close')),
            FilledButton(
              onPressed: uploadingStoryPhotos
                  ? null
                  : () async {
                      final candidate = <String, dynamic>{
                        ...item,
                        'recipientContentConsent': recipientConsent,
                        'allowCircumSocialUse': allowSocial,
                        'allowPublicPosting': allowPublicPosting,
                        'allowBrandTagging': allowBrandTagging,
                      };
                      if (contentStatus == 'posted' &&
                          !GiftsSocialPolicy.canPostPublicly(candidate)) {
                        ScaffoldMessenger.of(context)
                            .showSnackBar(const SnackBar(
                          content: Text(
                              'Public consent is required before content can be marked posted.'),
                        ));
                        return;
                      }
                      if (brandTagApproved &&
                          !GiftsSocialPolicy.canApproveBrandTags(candidate)) {
                        ScaffoldMessenger.of(context)
                            .showSnackBar(const SnackBar(
                          content: Text(
                              'Brand tagging consent is required before tags can be approved.'),
                        ));
                        return;
                      }
                      setDialogState(() {
                        uploadingStoryPhotos = true;
                        storyPhotoError = null;
                      });
                      try {
                        final uploaded = await _uploadGiftStoryPhotoFiles(
                          '${item['id']}',
                          pendingStoryPhotos,
                        );
                        storyPhotos
                          ..addAll(uploaded)
                          ..removeWhere((url) => url.trim().isEmpty);
                        pendingStoryPhotos.clear();
                        if (pendingStoryAudio != null) {
                          giftStoryCustomAudioUrl =
                              await _uploadGiftStoryAudioFile(
                            '${item['id']}',
                            pendingStoryAudio!,
                          );
                          pendingStoryAudio = null;
                          giftStoryMusicEnabled = true;
                        }
                      } catch (error) {
                        setDialogState(() {
                          uploadingStoryPhotos = false;
                          if ('$error'.toLowerCase().contains('audio')) {
                            storyAudioError =
                                _giftStoryAudioDisplayError(error);
                          } else {
                            storyPhotoError = '$error';
                          }
                        });
                        return;
                      }
                      Navigator.pop(context, {
                        'status': status,
                        'manualGiftPlan': plan.text.trim(),
                        'adminDecision': decision.text.trim(),
                        'internalNotes': notes.text.trim(),
                        'procurementItemTitle': procurementTitle.text.trim(),
                        'procurementSupplier': procurementSupplier.text.trim(),
                        'procurementEstimatedCost': double.tryParse(
                            procurementEstimatedCost.text.trim()),
                        'procurementActualCost':
                            double.tryParse(procurementActualCost.text.trim()),
                        'procurementNotes': procurementNotes.text.trim(),
                        'giftStoryEnabled': giftStoryEnabled,
                        'giftStoryApproved': giftStoryApproved,
                        'giftStoryShareEnabled': giftStoryShareEnabled,
                        'giftStorySharePrivacy': giftStorySharePrivacy,
                        'giftStoryPhotos': storyPhotos.toSet().toList(),
                        'giftStoryPhotoUrls': storyPhotos.toSet().toList(),
                        'giftStoryCircumMessage': circumMessage.text.trim(),
                        'giftStoryMusicEnabled': giftStoryMusicEnabled,
                        'giftStoryCustomAudioUrl': giftStoryCustomAudioUrl,
                        'giftStoryUpdatedAt': FieldValue.serverTimestamp(),
                        if (generatedRecommendation != null) ...{
                          'irisGiftRecommendation': generatedRecommendation,
                          'irisSuggestion':
