  List<Widget> _deliveryRow(Map<String, dynamic> item) {
    final id = '${item['id'] ?? item['requestId'] ?? ''}';
    final pickupCanonical = item['pickupAddressCanonical'] as Map?;
    final dropoffCanonical = item['dropoffAddressCanonical'] as Map?;
    String addressSummary(String fallback, Map? canonical) {
      if (canonical == null) return fallback;
      final address = '${canonical['displayAddress'] ?? fallback}';
      final lat = canonical['lat'];
      final lng = canonical['lng'];
      final source =
          '${canonical['addressSource'] ?? canonical['provider'] ?? ''}';
      final verified = '${canonical['validationStatus'] ?? ''}' == 'verified' ||
          (canonical['geocodeConfidence'] is num &&
              (canonical['geocodeConfidence'] as num) >= 0.8);
      final details = <String>[
        if (verified) 'Verified',
        if (source.isNotEmpty) source,
        if (lat is num && lng is num)
          '${lat.toStringAsFixed(5)}, ${lng.toStringAsFixed(5)}',
      ];
      return details.isEmpty ? address : '$address\n${details.join(' • ')}';
    }

    final waitSummary = _adminPickupWaitSummary(item);

    return [
      _AdminCell.primary(
        '${item['requestId'] ?? id}\n${_movementServiceLabel(_movementServiceType(item))}'
        '${item['vanguardEnabled'] == true ? '\n🛡 Vanguard' : ''}',
      ),
      _AdminCell(_jobReceivedText(item)),
      _AdminCell(
        '${addressSummary('${item['pickupAddress'] ?? item['pickupLocality'] ?? ''}', pickupCanonical)}\n→ ${addressSummary('${item['dropoffAddress'] ?? ''}', dropoffCanonical)}${waitSummary.isEmpty ? '' : '\n$waitSummary'}',
      ),
      _AdminStatusCell(
        colors: widget.colors,
        status: '${item['status'] ?? 'requested'}',
      ),
      _AdminCell(_adminIrisWeightSummary(item)),
      _AdminCell('£${_adminMoney(item).toStringAsFixed(2)}'),
      _AdminActions(
        colors: widget.colors,
        actions: [
          _AdminAction(
            label: 'Duplicate',
            enabled: _can(AdminPermission.duplicateDeliveries),
            onTap: () => _duplicateDelivery(item),
          ),
          _AdminAction(
            label: 'Failed',
            enabled: _can(AdminPermission.editDeliveries),
            onTap: () =>
                _updateRecordStatus('deliveryRequests', item, 'failed'),
          ),
          _AdminAction(
            label: 'Resolved',
            enabled: _can(AdminPermission.editDeliveries),
            onTap: () =>
                _updateRecordStatus('deliveryRequests', item, 'resolved'),
          ),
          _AdminAction(
            label: 'Chat',
            enabled: _can(AdminPermission.viewSupport),
            onTap: () => _openAdminChat(item),
          ),
          _AdminAction(
            label: 'Archive stale order',
            enabled: _can(AdminPermission.editDeliveries) &&
                (_isStaleDeliveryArchiveEligible(item) ||
                    (_roles.contains(AdminRole.superAdmin.value) &&
                        _isStaleDeliveryCandidate(item))),
            onTap: () => _archiveStaleDelivery(item),
          ),
          _AdminAction(
            label: 'Delete',
            enabled: _can(AdminPermission.editDeliveries) &&
                '${item['status'] ?? ''}'.toLowerCase() != 'deleted',
            onTap: () => _softDeleteDelivery(item),
          ),
        ],
      ),
    ];
  }

