  String _adminPickupWaitSummary(Map<String, dynamic> item) {
    final parts = <String>[];
    if (item['riderArrivedAtPickupAt'] != null) {
      parts.add('Arrived ${_adminDateText(item['riderArrivedAtPickupAt'])}');
    }
    if (item['pickupWaitStartedAt'] != null) {
      parts.add('Wait started ${_adminDateText(item['pickupWaitStartedAt'])}');
    }
    if (item['pickupWaitDeadlineAt'] != null) {
      parts.add('Deadline ${_adminDateText(item['pickupWaitDeadlineAt'])}');
    }
    if (item.containsKey('senderContactEstablished')) {
      parts.add(
          'Contact established: ${item['senderContactEstablished'] == true ? 'yes' : 'no'}');
    }
    if (item['pickupWaitExtended'] == true) {
      final minutes = item['pickupWaitExtensionMinutes'] ?? '';
      final charge = ((item['pickupWaitExtensionChargeGbp'] ??
              item['pickupWaitExtensionCharge'] ??
              0) as num)
          .toDouble();
      parts.add('Waiting extended ${minutes}m · £${charge.toStringAsFixed(2)}');
    }
    if (item['pickupNoShowAt'] != null) {
      final charge =
          ((item['pickupNoShowSurchargeGbp'] ?? 0) as num).toDouble();
      parts.add(
          'No-show ${_adminDateText(item['pickupNoShowAt'])} · £${charge.toStringAsFixed(2)}');
    }
    return parts.join('\n');
  }

  List<Widget> _financeRow(Map<String, dynamic> item) {
    final recordType = '${item['recordType'] ?? 'payment'}';
    final transactionType = '${item['type'] ?? ''}';
    double moneyValue(Object? value) {
      if (value is num) return value.toDouble();
      return double.tryParse('$value') ?? 0;
    }

    final isPendingEarning = recordType == 'wallet_transaction' &&
        '${item['status']}' == 'pending' &&
        transactionType == 'earning' &&
        '${item['deliveryId'] ?? item['requestId'] ?? ''}'.isNotEmpty;
    final isWithdrawal = recordType == 'driver_payout';
    return [
      _AdminCell.primary(
        recordType == 'roth_ledger'
            ? 'Roth · ${item['balanceType'] ?? ''}'
                '${item['progressionPointsAwarded'] == null ? '' : '\n+${item['progressionPointsAwarded']} progression points'}'
            : recordType == 'wallet_transaction'
                ? transactionType
                : recordType,
      ),
      _AdminCell(
        '${item['id'] ?? item['paymentId'] ?? item['payoutId'] ?? ''}',
      ),
      _AdminStatusCell(
        colors: widget.colors,
        status: recordType == 'roth_ledger'
            ? '${item['type'] ?? 'recorded'}'
            : '${item['status'] ?? 'pending'}',
      ),
      _AdminCell(isWithdrawal
          ? 'Gross £${moneyValue(item['riderGrossShare'] ?? item['amount']).toStringAsFixed(2)}\n'
              'Stripe/payment fee £${moneyValue(item['stripeFeeDeductedFromRider'] ?? item['estimatedStripeFees']).toStringAsFixed(2)}\n'
              'Net payout £${moneyValue(item['riderNetPayout'] ?? item['amount']).toStringAsFixed(2)}'
          : '£${_adminMoney(item).toStringAsFixed(2)}'),
      _AdminActions(
        colors: widget.colors,
        actions: [
          if (isPendingEarning)
            _AdminAction(
              label: 'Make available',
              enabled: _can(AdminPermission.viewFinance),
              onTap: () => _settleEarning(item),
            ),
          if (isWithdrawal)
            _AdminAction(
              label: 'Approve',
              enabled: _can(AdminPermission.viewFinance) &&
                  ['requested', 'pending'].contains('${item['status']}'),
              onTap: () => _processWithdrawal(item, 'approved'),
            ),
          if (isWithdrawal)
            _AdminAction(
              label: 'Reject',
              enabled: _can(AdminPermission.viewFinance) &&
                  ['requested', 'pending'].contains('${item['status']}'),
              onTap: () => _processWithdrawal(item, 'rejected'),
            ),
        ],
      ),
    ];
  }

