  Future<void> _confirmAdminAccessChange(
    Map<String, dynamic> adminUser,
    String status,
  ) async {
    final email = '${adminUser['email'] ?? ''}'.trim().toLowerCase();
    if (email == _adminUser?.email?.trim().toLowerCase()) {
      setState(() => _message = 'You cannot change your own admin access.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(
          status == 'active'
              ? 'Activate admin access?'
              : 'Deactivate admin access?',
        ),
        content: Text(
          status == 'active'
              ? 'This will let $email access the admin panel with their Firebase Auth login.'
              : 'This will block $email from the admin panel.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Confirm'),
          ),
        ],
      ),
    );
    if (confirmed == true) {
      await _saveAdminUser(existing: adminUser, status: status);
    }
  }

  List<Map<String, dynamic>> _issueRows() {
    final issues = <Map<String, dynamic>>[];
    for (final delivery in _deliveries) {
      final status = '${delivery['status'] ?? ''}'.toLowerCase();
      final id = '${delivery['requestId'] ?? delivery['id'] ?? ''}';
      if (status == 'requested' || status == 'pending') {
        issues.add({
          'title': 'Driver unassigned',
          'recordType': 'deliveryRequests',
          'recordId': id,
          'priority': 'High',
          'status': status,
        });
      }
      if (status.contains('failed') || status.contains('cancel')) {
        issues.add({
          'title':
              status.contains('failed') ? 'Failed delivery' : 'Cancelled job',
          'recordType': 'deliveryRequests',
          'recordId': id,
          'priority': 'Medium',
          'status': status,
        });
      }
      if (delivery['weightReviewRequired'] == true ||
          '${delivery['weightDisputeStatus'] ?? ''}' == 'admin_review') {
        issues.add({
          'title': 'Weight verification review',
          'recordType': 'deliveryRequests',
          'recordId': id,
          'priority': 'High',
          'status': delivery['weightDisputeStatus'] ?? 'open',
        });
      }
    }
    for (final rating in _ratings) {
      final stars = rating['starRating'] as num?;
      if (stars != null && stars <= 2) {
        issues.add({
          'title': 'Low-rated driver',
          'recordType': 'driverRatings',
          'recordId': rating['id'] ?? rating['deliveryId'] ?? '',
          'priority': 'High',
          'status': 'open',
        });
      }
    }
    for (final ticket in _supportTickets.where(
      (ticket) => '${ticket['type']}'.contains('refund'),
    )) {
      issues.add({
        'title': 'Refund request',
        'recordType': 'supportTickets',
        'recordId': ticket['id'] ?? '',
        'priority': 'Medium',
        'status': ticket['status'] ?? 'open',
      });
    }
    return issues;
  }

  List<Map<String, dynamic>> _financeRows() {
    return [
      ..._rothTransactions.map(
        (item) => {'recordType': 'roth_ledger', ...item},
      ),
      ..._walletTransactions.map(
        (item) => {'recordType': 'wallet_transaction', ...item},
      ),
      ..._payments.map((item) => {'recordType': 'payment', ...item}),
      ..._healthPlusPayments.map(
        (item) => {'recordType': 'health_plus_payment', ...item},
      ),
      ..._payoutRequests.map(
        (item) => {'recordType': 'driver_payout', ...item},
      ),
      ..._supportTickets
          .where((ticket) => '${ticket['type']}'.contains('refund'))
          .map((item) => {'recordType': 'refund_request', ...item}),
    ];
  }

  double _walletTotal(String field) => _riderWallets.fold<double>(
        0,
        (total, wallet) => total + ((wallet[field] as num?)?.toDouble() ?? 0),
      );

  double _rothWalletTotal(String field) => _rothWallets.fold<double>(
        0,
        (total, wallet) => total + ((wallet[field] as num?)?.toDouble() ?? 0),
      );

  Map<String, dynamic> _walletForRider(String riderId) {
    return _riderWallets.firstWhere(
      (wallet) => '${wallet['riderId'] ?? wallet['id'] ?? ''}' == riderId,
      orElse: () => const <String, dynamic>{},
    );
  }

  double _roleRothBalanceForDriver(
    Map<String, dynamic> driver,
    String walletType,
  ) {
    final riderId = _driverId(driver);
    final wallet = _roleRothWallets.firstWhere(
      (item) =>
          '${item['walletType'] ?? ''}'.toLowerCase() ==
              walletType.toLowerCase() &&
          '${item['userId'] ?? ''}' == riderId,
      orElse: () => const <String, dynamic>{},
    );
    return ((wallet['balanceRoth'] ?? wallet['balance'] ?? 0) as num?)
            ?.toDouble() ??
        0;
  }

  double _senderRothBalanceForDriver(Map<String, dynamic> driver) {
    final roleSenderBalance = _roleRothBalanceForDriver(driver, 'sender');
    if (roleSenderBalance > 0) return roleSenderBalance;
    final email = '${driver['email'] ?? ''}'.trim().toLowerCase();
    if (email.isEmpty) return 0;
    final wallet = _rothWallets.firstWhere(
      (item) {
        final walletId =
            '${item['id'] ?? item['walletId'] ?? item['userId'] ?? ''}'
                .trim()
                .toLowerCase();
        final userEmail =
            '${item['userEmail'] ?? item['normalizedEmail'] ?? ''}'
                .trim()
                .toLowerCase();
        return walletId == email || userEmail == email;
      },
      orElse: () => const <String, dynamic>{},
    );
    return ((wallet['balance'] ?? wallet['rothCredit'] ?? 0) as num?)
            ?.toDouble() ??
        0;
  }

  bool _riderCanWithdraw(String riderId, String riderEmail) {
    if (riderEmail.trim().toLowerCase() == RoleAccessPolicy.superAdminEmail) {
      return true;
    }
    final rider = _drivers.firstWhere(
      (driver) => _driverId(driver) == riderId,
      orElse: () => const <String, dynamic>{},
    );
    final status =
        '${rider['approvalStatus'] ?? rider['verificationStatus'] ?? ''}'
            .trim()
            .toLowerCase();
    return status == 'approved' || status == 'verified';
  }

  Future<void> _submitRothCreditAction(bool credit) async {
    if (!_can(AdminPermission.viewFinance)) return;
    final userId = _rothUserId.text.trim();
    final amount = double.tryParse(_rothAmount.text.trim()) ?? 0;
    final reason = _rothReason.text.trim();
    if (userId.isEmpty || amount <= 0 || reason.isEmpty) {
      setState(
          () => _message = 'Roth action requires user, amount and reason.');
      return;
    }
    try {
      if (credit) {
        final summary = _rothWalletTarget == 'both'
            ? 'Issue ${amount.toStringAsFixed(2)} Roth to both Sender and Rider wallets?'
            : 'Issue ${amount.toStringAsFixed(2)} Roth to ${_rothWalletTarget == 'sender' ? 'Sender' : 'Rider'} wallet?';
        final confirmed = await showDialog<bool>(
          context: context,
          builder: (context) => AlertDialog(
            title: const Text('Confirm Roth issue'),
            content: Text('$summary\n\nRecipient: $userId\nReason: $reason'),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () => Navigator.pop(context, true),
                child: const Text('Issue Roth'),
              ),
            ],
          ),
        );
        if (confirmed != true) return;
        final idempotencyKey =
            'admin_${_adminUser?.uid ?? _adminUser?.email}_${DateTime.now().microsecondsSinceEpoch}';
        final result = await FirebaseFunctions.instance
            .httpsCallable('issueRothToWallets')
            .call({
          (userId.contains('@') ? 'recipientEmail' : 'recipientUid'): userId,
          'walletTarget': _rothWalletTarget,
          'amount': amount,
          'reason': reason,
          'idempotencyKey': idempotencyKey,
        });
        final data = Map<String, dynamic>.from(result.data as Map);
        _rothAmount.clear();
        _rothReason.clear();
        setState(() => _message =
            'Roth issued to ${data['walletTarget']} wallet(s). Admin issue ID: ${data['adminIssueId']}');
        await _loadAdminData();
        return;
      }
      final callable = FirebaseFunctions.instance.httpsCallable(
        'debitRothCredit',
      );
      await callable.call({
        'userId': userId,
        'amount': amount,
        'reason': reason,
      });
      _rothAmount.clear();
      _rothReason.clear();
      setState(() => _message = credit
          ? 'Roth Credit issued and ledgered.'
          : 'Roth Credit debit recorded.');
      await _loadAdminData();
    } catch (error) {
      setState(() => _message = 'Roth ledger action failed: $error');
    }
  }

  Future<void> _setWalletFrozen(bool frozen) async {
    if (!_can(AdminPermission.viewFinance)) return;
    final userId = _rothUserId.text.trim();
    final reason = _rothReason.text.trim();
    if (userId.isEmpty || reason.isEmpty) {
      setState(
          () => _message = 'Wallet freeze action requires user and reason.');
      return;
    }
    try {
      await FirebaseFunctions.instance.httpsCallable('setWalletFrozen').call({
        'userId': userId,
        'isFrozen': frozen,
        'reason': reason,
      });
      setState(() => _message = frozen ? 'Wallet frozen.' : 'Wallet unfrozen.');
      await _loadAdminData();
    } catch (error) {
      setState(() => _message = 'Wallet freeze action failed: $error');
    }
  }

