  Future<void> _settleEarning(Map<String, dynamic> item) async {
    if (!_can(AdminPermission.viewFinance) || item['status'] != 'pending') {
      return;
    }
    final riderId = '${item['riderId'] ?? ''}';
    final transactionId = '${item['id'] ?? item['transactionId'] ?? ''}';
    final amount = (item['amount'] as num?)?.toDouble() ?? 0;
    if (riderId.isEmpty || transactionId.isEmpty || amount <= 0) return;
    final db = FirebaseFirestore.instance;
    await db.runTransaction((transaction) async {
      final ledgerRef =
          db.collection('riderWalletTransactions').doc(transactionId);
      final walletRef = db.collection('riderEarnings').doc(riderId);
      final rothWalletRef = db.collection('wallets').doc(riderId);
      final rothLedgerRef =
          db.collection('walletTransactions').doc('roth_settle_$transactionId');
      final ledger = await transaction.get(ledgerRef);
      final rothWallet = await transaction.get(rothWalletRef);
      final rothLedger = await transaction.get(rothLedgerRef);
      if (!ledger.exists || ledger.data()?['status'] != 'pending') return;
      transaction.set(
          ledgerRef,
          {
            'status': 'available',
            'updatedAt': FieldValue.serverTimestamp(),
            'settledBy': _adminUser?.uid,
          },
          SetOptions(merge: true));
      transaction.set(
          walletRef,
          {
            'pendingBalance': FieldValue.increment(-amount),
            'availableBalance': FieldValue.increment(amount),
            'updatedAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true));
      if (!rothLedger.exists) {
        final pendingBefore =
            (rothWallet.data()?['pendingEarnings'] as num?)?.toDouble() ?? 0;
        final availableBefore =
            (rothWallet.data()?['availableEarnings'] as num?)?.toDouble() ?? 0;
        transaction.set(
            rothLedgerRef,
            {
              'id': 'roth_settle_$transactionId',
              'userId': riderId,
              'amount': amount,
              'balanceType': 'availableEarnings',
              'type': 'earnings_available',
              'reason': 'Admin settlement moved rider earnings to available.',
              'relatedEntityId': transactionId,
              'paymentProvider': 'manual_admin',
              'issuedByAdminId': _adminUser?.uid,
              'issuedByAdminEmail': _adminUser?.email,
              'balanceBefore': availableBefore,
              'balanceAfter':
                  double.parse((availableBefore + amount).toStringAsFixed(2)),
              'createdAt': FieldValue.serverTimestamp(),
              'metadata': {
                'pendingBefore': pendingBefore,
                'pendingAfter':
                    double.parse((pendingBefore - amount).toStringAsFixed(2)),
                'legacyTransactionId': transactionId,
              },
            },
            SetOptions(merge: false));
        transaction.set(
            rothWalletRef,
            {
              'userId': riderId,
              'pendingEarnings': FieldValue.increment(-amount),
              'availableEarnings': FieldValue.increment(amount),
              'updatedAt': FieldValue.serverTimestamp(),
              'createdAt': FieldValue.serverTimestamp(),
            },
            SetOptions(merge: true));
      }
    });
    await _writeAudit(AdminAuditEntry(
      adminUserId: _adminUser?.uid ?? '',
      actionType: 'rider_earning_made_available',
      recordType: 'riderWalletTransactions',
      recordId: transactionId,
      newValue: {'riderId': riderId, 'amount': amount, 'status': 'available'},
    ));
    await _loadAdminData();
  }

  Future<void> _processWithdrawal(
    Map<String, dynamic> item,
    String nextStatus,
  ) async {
    if (!_can(AdminPermission.viewFinance)) return;
    final requestId = '${item['id'] ?? item['requestId'] ?? ''}';
    final riderId = '${item['riderId'] ?? ''}';
    final amount = (item['amount'] as num?)?.toDouble() ?? 0;
    if (requestId.isEmpty || riderId.isEmpty || amount <= 0) return;
    if (nextStatus == 'approved' &&
        !_riderCanWithdraw(riderId, '${item['riderEmail'] ?? ''}')) {
      setState(
        () => _message =
            'Withdrawal blocked: this rider has incomplete onboarding.',
      );
      return;
    }
    if (nextStatus == 'approved') {
      try {
        await FirebaseFunctions.instanceFor(region: 'us-central1')
            .httpsCallable('createRiderTransferOrPayout')
            .call({
          'requestId': requestId,
          'riderId': riderId,
          'amount': amount,
        });
        await _writeAudit(AdminAuditEntry(
          adminUserId: _adminUser?.uid ?? '',
          actionType: 'rider_stripe_payout_started',
          recordType: 'payoutRequests',
          recordId: requestId,
          newValue: {
            'riderId': riderId,
            'amount': amount,
            'status': 'processing',
            'paymentProvider': 'stripe_connect_express',
            'payoutFeePayer': 'rider',
          },
        ));
        await _loadAdminData();
      } on FirebaseFunctionsException catch (error) {
        if (!mounted) return;
        setState(
          () =>
              _message = error.message ?? 'Stripe payout could not be started.',
        );
      } catch (_) {
        if (!mounted) return;
        setState(() => _message = 'Stripe payout could not be started.');
      }
      return;
    }
    final db = FirebaseFirestore.instance;
    await db.runTransaction((transaction) async {
      final requestRef = db.collection('payoutRequests').doc(requestId);
      final walletRef = db.collection('riderEarnings').doc(riderId);
      final rothWalletRef = db.collection('wallets').doc(riderId);
      final request = await transaction.get(requestRef);
      final wallet = await transaction.get(walletRef);
      final rothWallet = await transaction.get(rothWalletRef);
      final currentStatus = '${request.data()?['status'] ?? ''}';
      if (!request.exists ||
          !['requested', 'pending'].contains(currentStatus)) {
        return;
      }
      if (nextStatus == 'rejected') {
        transaction.set(
            requestRef,
            {
              'status': 'rejected',
              'processedAt': FieldValue.serverTimestamp(),
              'processedBy': _adminUser?.uid,
              'updatedAt': FieldValue.serverTimestamp(),
            },
            SetOptions(merge: true));
        transaction.set(
            walletRef,
            {
              'pendingWithdrawal': FieldValue.increment(-amount),
              'updatedAt': FieldValue.serverTimestamp(),
            },
            SetOptions(merge: true));
        return;
      }
      final available =
          (wallet.data()?['availableBalance'] as num?)?.toDouble() ?? 0;
      if (available < amount) {
        throw StateError('Withdrawal exceeds available rider balance.');
      }
      final ledgerId = 'withdrawal_$requestId';
      final rothLedgerId = 'roth_withdrawal_$requestId';
      transaction.set(
        db.collection('riderWalletTransactions').doc(ledgerId),
        {
          'id': ledgerId,
          'riderId': riderId,
          'deliveryId': null,
          'withdrawalRequestId': requestId,
          'type': 'withdrawal',
          'amount': -amount,
          'status': 'paid',
          'notes': 'Manual rider withdrawal approved by Circum.',
          'createdAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
        },
        SetOptions(merge: false),
      );
      transaction.set(
          requestRef,
          {
            'status': 'approved',
            'processedAt': FieldValue.serverTimestamp(),
            'processedBy': _adminUser?.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true));
      transaction.set(
          walletRef,
          {
            'availableBalance': FieldValue.increment(-amount),
            'pendingWithdrawal': FieldValue.increment(-amount),
            'totalWithdrawn': FieldValue.increment(amount),
            'withdrawnEarnings': FieldValue.increment(amount),
            'updatedAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true));
      final rothAvailable =
          (rothWallet.data()?['availableEarnings'] as num?)?.toDouble() ?? 0;
      transaction.set(
        db.collection('walletTransactions').doc(rothLedgerId),
        {
          'id': rothLedgerId,
          'userId': riderId,
          'amount': -amount,
          'balanceType': 'availableEarnings',
          'type': 'withdrawal',
          'reason': 'Manual rider withdrawal approved by Circum.',
          'relatedEntityId': requestId,
          'paymentProvider': 'manual_admin',
          'issuedByAdminId': _adminUser?.uid,
          'issuedByAdminEmail': _adminUser?.email,
          'balanceBefore': rothAvailable,
          'balanceAfter':
              double.parse((rothAvailable - amount).toStringAsFixed(2)),
          'createdAt': FieldValue.serverTimestamp(),
          'metadata': {
            'legacyWithdrawalTransactionId': ledgerId,
            'withdrawalRequestId': requestId,
          },
        },
        SetOptions(merge: false),
      );
      transaction.set(
          rothWalletRef,
          {
            'userId': riderId,
            'availableEarnings': FieldValue.increment(-amount),
            'updatedAt': FieldValue.serverTimestamp(),
            'createdAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true));
    });
    await _writeAudit(AdminAuditEntry(
      adminUserId: _adminUser?.uid ?? '',
      actionType: nextStatus == 'rejected'
          ? 'rider_withdrawal_rejected'
          : 'rider_withdrawal_approved',
      recordType: 'payoutRequests',
      recordId: requestId,
      newValue: {'riderId': riderId, 'amount': amount, 'status': nextStatus},
    ));
    await _loadAdminData();
  }

  List<Map<String, dynamic>> _healthPlusRows() {
    return [
      ..._healthPlusPickups.map(
        (item) => {'recordType': 'prescriptionPickups', ...item},
      ),
      ..._recurringPickupSchedules.map(
        (item) => {'recordType': 'recurringPickupSchedules', ...item},
      ),
    ];
  }

  Future<void> _resolveIssueAction(
    Map<String, dynamic> issue,
    String status,
  ) async {
    if (issue['recordType'] == 'supportTickets') {
      final ticket = _supportTickets.firstWhere(
        (item) => '${item['id']}' == '${issue['recordId']}',
        orElse: () => {'id': issue['recordId']},
      );
      await _updateSupportTicket(ticket, status);
      return;
    }
    await _addAdminNote(
      '${issue['recordType']}',
      '${issue['recordId']}',
      'Issue marked $status from operations panel',
    );
  }

  double _adminMoney(Map<String, dynamic> item) {
    final value =
        item['amount'] ?? item['price'] ?? item['quote'] ?? item['total'];
    if (value is num) return value.toDouble();
    return double.tryParse('$value') ?? 0;
  }

  String _adminIrisWeightSummary(Map<String, dynamic> item) {
    final learning = item['irisLearningData'] is Map
        ? Map<String, dynamic>.from(item['irisLearningData'] as Map)
        : const <String, dynamic>{};
    final finalWeight = item['finalWeightUsed'] ??
        item['finalChargeableWeight'] ??
        item['confirmedWeightKg'] ??
        item['weightKg'] ??
        'n/a';
    final source = item['weightSource'] ??
        item['irisWeightSource'] ??
        learning['source'] ??
        'unknown';
    final reason = '${learning['reason'] ?? ''}'.trim();
    final vanguard = item['vanguardEnabled'] == true
        ? '\nVanguard: collection ${item['collectionPinVerified'] == true ? 'passed' : 'pending'}, delivery ${item['deliveryPinVerified'] == true ? 'passed' : 'pending'}'
        : '';
    final discrepancy = item['loadDiscrepancy'] is Map
        ? Map<String, dynamic>.from(item['loadDiscrepancy'] as Map)
        : const <String, dynamic>{};
    final discrepancyText = discrepancy.isEmpty
        ? ''
        : '\nLoad discrepancy: ${discrepancy['riderReason'] ?? 'reported'}'
            '\nOriginal £${_adminMoneyValue(discrepancy['originalQuote'])} → revised £${_adminMoneyValue(discrepancy['revisedQuote'])}'
            '\nAdditional £${_adminMoneyValue(discrepancy['additionalAmount'])} • Sender: ${discrepancy['senderDecision'] ?? 'pending'}'
            '\nEvidence: ${(discrepancy['evidencePhotos'] as List?)?.length ?? 0} photo(s)';
    return reason.isEmpty
        ? '$finalWeight kg\n$source$vanguard$discrepancyText'
        : '$finalWeight kg\n$source\n$reason$vanguard$discrepancyText';
  }

  String _adminMoneyValue(Object? value) {
    final amount = value is num ? value.toDouble() : double.tryParse('$value');
    return (amount ?? 0).toStringAsFixed(2);
  }
}

