String _jobReceivedTextFromDate(DateTime? date) {
  if (date == null) return 'Time received unavailable';
  final local = date.toLocal();
  final now = DateTime.now();
  final hour = local.hour.toString().padLeft(2, '0');
  final minute = local.minute.toString().padLeft(2, '0');
  if (local.year == now.year &&
      local.month == now.month &&
      local.day == now.day) {
    return 'Received: Today, $hour:$minute';
  }
  final monthIndex = local.month < 1
      ? 0
      : local.month > 12
          ? 11
          : local.month - 1;
  final month = _shortMonthNames[monthIndex];
  return 'Received: ${local.day} $month, $hour:$minute';
}

bool _isArchivedDeliveryRecord(Map<String, dynamic> delivery) {
  final status = '${delivery['status'] ?? ''}'.toLowerCase().trim();
  final matchingStatus =
      '${delivery['matchingStatus'] ?? ''}'.toLowerCase().trim();
  final dispatchStatus =
      '${delivery['dispatchStatus'] ?? ''}'.toLowerCase().trim();
  const archivedStatuses = {
    'archived',
    'void',
    'voided',
    'cancelled_by_admin',
    'deleted',
    'resolved',
  };
  return delivery['archived'] == true ||
      delivery['active'] == false ||
      delivery['deletedAt'] != null ||
      delivery['archivedAt'] != null ||
      delivery['resolvedAt'] != null ||
      archivedStatuses.contains(status) ||
      archivedStatuses.contains(matchingStatus) ||
      archivedStatuses.contains(dispatchStatus);
}

bool _isStaleDeliveryArchiveEligible(Map<String, dynamic> delivery) {
  if (_isArchivedDeliveryRecord(delivery)) return false;
  if (delivery['stale'] == true || delivery['manuallyMarkedStale'] == true) {
    return true;
  }
  if (!_isStaleDeliveryCandidate(delivery)) return false;
  final createdAt = _deliveryRecordDate(delivery);
  if (createdAt == null) return false;
  return DateTime.now().difference(createdAt).inHours >= 24;
}

bool _isStaleDeliveryCandidate(Map<String, dynamic> delivery) {
  if (_isArchivedDeliveryRecord(delivery)) return false;
  final status = '${delivery['status'] ?? ''}'.toLowerCase().trim();
  final matchingStatus =
      '${delivery['matchingStatus'] ?? ''}'.toLowerCase().trim();
  const staleStatuses = {
    'finding_rider',
    'pending',
    'unmatched',
    'requested',
  };
  return staleStatuses.contains(status) ||
      staleStatuses.contains(matchingStatus);
}

DateTime? _deliveryRecordDate(Map<String, dynamic> delivery) {
  final raw = delivery['createdAt'] ??
      delivery['receivedAt'] ??
      delivery['requestedAt'] ??
      delivery['timestamp'] ??
      delivery['updatedAt'];
  if (raw is Timestamp) return raw.toDate();
  if (raw is DateTime) return raw;
  if (raw is String) return DateTime.tryParse(raw);
  return null;
}

bool _isActiveSenderDeliveryStatus(String status) {
  final normalized = status.toLowerCase().trim().replaceAll('-', '_');
  const activeStatuses = {
    'pending',
    'requested',
    'received',
    'finding_rider',
    'rider_assigned',
    'assigned',
    'accepted',
    'en_route_to_pickup',
    'rider_arrived_pickup',
    'arrived_at_pickup',
    'sender_no_show_pickup',
    'collected',
    'picked_up',
    'in_transit',
    'arriving',
    'disputed',
  };
  const inactiveStatuses = {
    'completed',
    'complete',
    'delivered',
    'cancelled',
    'cancelled_by_sender',
    'canceled',
    'failed',
    'refunded',
    'archived',
    'voided',
    'void',
    'cancelled_by_admin',
    'deleted',
  };
  if (inactiveStatuses.contains(normalized)) return false;
  return activeStatuses.contains(normalized);
}

String _displayStatusLabel(String status) {
  final normalized = status.trim().replaceAll('_', ' ');
  if (normalized.isEmpty) return 'Status pending';
  return normalized
      .split(RegExp(r'\s+'))
      .where((part) => part.isNotEmpty)
      .map((part) => '${part[0].toUpperCase()}${part.substring(1)}')
      .join(' ');
}

String _customerDeliveryStatusLabel(String status) {
  final normalized = status.trim().toLowerCase();
  if (normalized == 'pending' || normalized == 'requested') {
    return 'Finding a rider';
  }
  if (normalized == 'accepted' ||
      normalized == 'rider_assigned' ||
      normalized == 'assigned') {
    return 'Rider assigned';
  }
  if (normalized == 'en_route_pickup' || normalized == 'en_route_to_pickup') {
    return 'Rider travelling to pickup';
  }
  if (normalized == 'rider_arrived_pickup' ||
      normalized == 'arrived_at_pickup') {
    return 'Rider arrived at pickup';
  }
  if (normalized == 'sender_no_show_pickup') return 'Sender no-show';
  if (normalized == 'collected' || normalized == 'picked_up') {
    return 'Parcel collected';
  }
  if (normalized == 'in_transit') return 'In transit';
  if (normalized == 'arriving') return 'Rider arriving';
  if (normalized == 'completed' ||
      normalized == 'complete' ||
      normalized == 'delivered') {
    return 'Delivered';
  }
  if (normalized == 'cancelled' ||
      normalized == 'canceled' ||
      normalized == 'cancelled_by_sender') {
    return 'Cancelled';
  }
  return _displayStatusLabel(status);
}

String _adminDateText(dynamic value) {
  DateTime? date;
  if (value is Timestamp) date = value.toDate();
  if (value is DateTime) date = value;
  if (value is String) date = DateTime.tryParse(value);
  if (date == null) return 'Not yet';
  return '${date.day.toString().padLeft(2, '0')}/${date.month.toString().padLeft(2, '0')}/${date.year}';
}

String _formatGiftRecommendationForAdmin(GiftRecommendationResult result) {
  final buffer = StringBuffer(result.experienceSummary);
  buffer.writeln();
  buffer.writeln();
  buffer.writeln('Budget allocation:');
  for (final entry in result.budgetAllocation.entries) {
    buffer.writeln('- ${_displayStatusLabel(entry.key)}: £${entry.value}');
  }
  buffer.writeln();
  buffer.writeln('Top internal candidate ideas:');
  for (final candidate in result.topCandidates.take(10)) {
    buffer.writeln(
        '- ${candidate.item.name} (${candidate.item.category}) · score ${candidate.score}');
  }
  if (result.riskWarnings.isNotEmpty) {
    buffer.writeln();
    buffer.writeln('Risk warnings:');
    for (final warning in result.riskWarnings) {
      buffer.writeln('- $warning');
    }
  }
  buffer.writeln();
  buffer.writeln('Procurement notes:');
  for (final note in result.procurementNotes) {
    buffer.writeln('- $note');
  }
  return buffer.toString().trim();
}

