  void _listenToAvailableJobs() {
    _availableJobsSub?.cancel();
    _availableJobsSub = FirebaseFirestore.instance
        .collection('deliveryRequests')
        .where('status', isEqualTo: 'requested')
        .limit(20)
        .snapshots()
        .listen(
      (snapshot) {
        if (!mounted) return;
        setState(() {
          final jobs = snapshot.docs
              .map((doc) => {'id': doc.id, ...doc.data()})
              .where((job) {
            final matchingStatus =
                '${job['matchingStatus'] ?? 'available'}'.toLowerCase();
            if (_isArchivedDeliveryRecord(job)) return false;
            final ignoredBy = (job['ignoredByRiders'] as List?) ?? const [];
            final rejectedBy = (job['rejectedByRiders'] as List?) ?? const [];
            final currentRider = _riderUser?.uid;
            if (currentRider != null &&
                (ignoredBy.contains(currentRider) ||
                    rejectedBy.contains(currentRider))) {
              return false;
            }
            final riderVehicle = '${_riderProfile?['vehicleType'] ?? ''}';
            final requiredVehicle =
                '${job['vehicleType'] ?? job['irisRecommendedVehicle'] ?? ''}';
            if (!_superAdminRiderBypass &&
                riderVehicle.isNotEmpty &&
                requiredVehicle.isNotEmpty &&
                !DeliveryPricing.vehicleMeetsMinimum(
                  riderVehicle,
                  requiredVehicle,
                )) {
              return false;
            }
            final riderRank = _riderProfile?['rank'] ??
                _riderProfile?['riderRank'] ??
                'agent';
            if (!_superAdminRiderBypass &&
                !RiderDispatchPolicy.canViewJob(
                  riderRank: riderRank,
                  job: job,
                )) {
              return false;
            }
            return matchingStatus == 'available' ||
                matchingStatus == 'requested';
          }).toList();
          jobs.sort(_compareRiderJobs);
          final jobIds = jobs.map((job) => '${job['id']}').toSet();
          final hasNewJob = _availableJobsInitialised &&
              jobIds.difference(_knownAvailableJobIds).isNotEmpty;
          _availableJobs = jobs;
          _knownAvailableJobIds = jobIds;
          _availableJobsInitialised = true;
          if (hasNewJob && _newJobSoundEnabled) _playNewJobSound();
        });
      },
      onError: (_) {
        if (!mounted) return;
        setState(
          () => _jobMessage = 'Could not load available jobs right now.',
        );
      },
    );
  }

  void _playNewJobSound() {
    try {
      final audio = html.AudioElement('assets/assets/audio/new_job.wav')
        ..volume = 0.55;
      unawaited(audio.play().catchError((_) {}));
    } catch (_) {
      // Browser autoplay policies may block sound until the rider interacts.
    }
  }

  int _compareRiderJobs(Map<String, dynamic> a, Map<String, dynamic> b) {
    final riderRank =
        _riderProfile?['rank'] ?? _riderProfile?['riderRank'] ?? 'agent';
    final rankPriority = RiderDispatchPolicy.priorityScore(
      riderRank: riderRank,
      job: b,
    ).compareTo(RiderDispatchPolicy.priorityScore(
      riderRank: riderRank,
      job: a,
    ));
    if (rankPriority != 0) return rankPriority;
    final serviceA = '${a['selectedServiceLevel'] ?? a['serviceLevel'] ?? ''}';
    final serviceB = '${b['selectedServiceLevel'] ?? b['serviceLevel'] ?? ''}';
    final priorityCompare = DeliveryPricing.matchingPriorityRank(
      serviceA,
    ).compareTo(DeliveryPricing.matchingPriorityRank(serviceB));
    if (priorityCompare != 0) return priorityCompare;

    final pickupCompare =
        '${a['scheduledPickupDate'] ?? ''} ${a['scheduledPickupWindow'] ?? ''}'
            .compareTo(
      '${b['scheduledPickupDate'] ?? ''} ${b['scheduledPickupWindow'] ?? ''}',
    );
    if (pickupCompare != 0) return pickupCompare;

    return _jobDistanceMiles(a).compareTo(_jobDistanceMiles(b));
  }

  void _listenToRiderJobs(String riderId) {
    _acceptedJobsSub?.cancel();
    _completedJobsSub?.cancel();
    _acceptedJobsSub = FirebaseFirestore.instance
        .collection('deliveryRequests')
        .where('riderId', isEqualTo: riderId)
        .where(
          'status',
          whereIn: [
            'accepted',
            'en_route_to_pickup',
            'arrived_at_pickup',
            'rider_arrived_pickup',
            'collected',
            'picked_up',
            'in_transit',
            'arriving',
            'sender_no_show_pickup',
          ],
        )
        .limit(20)
        .snapshots()
        .listen(
          (snapshot) {
            if (!mounted) return;
            setState(() {
              _acceptedJobs = snapshot.docs
                  .map((doc) => {'id': doc.id, ...doc.data()})
                  .toList(growable: false);
            });
            _syncRiderLiveLocationPublishing();
          },
          onError: (_) {
            if (!mounted) return;
            setState(() => _jobMessage = 'Could not load accepted jobs.');
          },
        );
    _completedJobsSub = FirebaseFirestore.instance
        .collection('deliveryRequests')
        .where('riderId', isEqualTo: riderId)
        .where('status', isEqualTo: 'completed')
        .limit(20)
        .snapshots()
        .listen((snapshot) {
      if (!mounted) return;
      setState(() {
        _completedJobs = snapshot.docs
            .map((doc) => {'id': doc.id, ...doc.data()})
            .toList(growable: false);
      });
    });
  }

  Future<void> _acceptDeliveryJob(Map<String, dynamic> job) async {
    final user = _riderUser;
    if (user == null) {
      setState(() => _jobMessage = 'Sign in before accepting a job.');
      return;
    }
    if (!RiderOnboardingPolicy.canAcceptJobs(
      email: user.email,
      profile: _riderProfile,
      verifiedSuperAdmin: _superAdminRiderBypass,
    )) {
      setState(() => _jobMessage =
          'Your rider account must be approved before accepting jobs.');
      return;
    }
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    if (requestId.isEmpty) return;
    setState(() => _jobMessage = 'Accepting job $requestId...');
    try {
      await _ensureCircumFirebaseReady();
      final db = FirebaseFirestore.instance;
      final riderDoc = await db.collection('riderProfiles').doc(user.uid).get();
      final rider = riderDoc.data() ?? const <String, dynamic>{};
      final riderVehicle =
          (rider['vehicle'] as Map?)?.cast<String, dynamic>() ??
              const <String, dynamic>{};
      final riderName =
          '${rider['fullName'] ?? user.displayName ?? user.email}';
      final riderPhotoUrl =
          '${rider['photoURL'] ?? rider['photoUrl'] ?? user.photoURL ?? ''}'
              .trim();
      final riderRank = '${rider['riderRank'] ?? rider['rank'] ?? 'agent'}';
      final vehicleType =
          '${riderVehicle['type'] ?? rider['vehicleType'] ?? rider['vehicle'] ?? ''}';
      final vehicleMakeModel =
          '${riderVehicle['makeModel'] ?? rider['vehicleMakeModel'] ?? ''}';
      final vehicleColour =
          '${riderVehicle['colour'] ?? riderVehicle['color'] ?? rider['vehicleColour'] ?? ''}';
      final registrationNumber =
          '${riderVehicle['plateNumber'] ?? rider['plateNumber'] ?? rider['vehicleRegistration'] ?? ''}';
      final assignedRider = {
        'riderId': user.uid,
        'name': riderName,
        'photoURL': riderPhotoUrl,
        'rank': riderRank,
        'vehicleType': vehicleType,
        'vehicleMakeModel': vehicleMakeModel,
        'vehicleColour': vehicleColour,
        'registrationNumber': registrationNumber,
        'verified': true,
      };
      await db.collection('deliveryRequests').doc(requestId).set({
        'status': 'accepted',
        'dispatchStatus': 'accepted',
        'matchingStatus': 'accepted',
        'riderId': user.uid,
        'driverId': user.uid,
        'assignedDriverId': user.uid,
        'assignedRider': assignedRider,
        'riderName': riderName,
        'driverName': riderName,
        'riderPhotoURL': riderPhotoUrl,
        'driverPhotoUrl': riderPhotoUrl,
        'riderRank': riderRank,
        'driverVehicle': rider['vehicle'],
        'driverPlateNumber': registrationNumber,
        'vehicleType': vehicleType,
        'vehicleMakeModel': vehicleMakeModel,
        'vehicleColour': vehicleColour,
        'vehicleRegistration': registrationNumber,
        'plateNumber': registrationNumber,
        'acceptedAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      await _startRiderLiveLocationPublishing(requestId, user.uid, 'accepted');
      await db.collection('chats').doc(requestId).set({
        'threadId': requestId,
        'bookingId': requestId,
        'requestId': requestId,
        'participants': FieldValue.arrayUnion([user.uid, 'circum-support']),
        'participantRoles': {user.uid: 'rider', 'circum-support': 'admin'},
        'assignedRiderId': user.uid,
        'updatedAt': FieldValue.serverTimestamp(),
        'source': 'circum-web',
      }, SetOptions(merge: true));
      if (!mounted) return;
      setState(() => _jobMessage = 'Job accepted. Head to pickup.');
    } catch (_) {
      if (!mounted) return;
      setState(() => _jobMessage = 'Could not accept this job. Try again.');
    }
  }

  void _syncRiderLiveLocationPublishing() {
    final user = _riderUser;
    if (user == null) {
      _stopRiderLiveLocationPublishing(status: 'offline');
      return;
    }
    final activeJob = _acceptedJobs.cast<Map<String, dynamic>?>().firstWhere((
      job,
    ) {
      final status = '${job?['status'] ?? ''}'.toLowerCase();
      return status == 'accepted' ||
          status == 'rider_arrived_pickup' ||
          status == 'arrived_at_pickup' ||
          status == 'picked_up' ||
          status == 'in_transit' ||
          status == 'in_progress';
    }, orElse: () => null);
    if (activeJob == null) {
      _stopRiderLiveLocationPublishing(status: 'offline');
      return;
    }
    final requestId =
        '${activeJob['requestId'] ?? activeJob['id'] ?? ''}'.trim();
    final status = '${activeJob['status'] ?? 'accepted'}'.toLowerCase();
    if (requestId.isEmpty || requestId == _trackingDeliveryId) return;
    _startRiderLiveLocationPublishing(requestId, user.uid, status);
  }

  Future<void> _startRiderLiveLocationPublishing(
    String deliveryId,
    String riderId,
    String status,
  ) async {
    if (_trackingDeliveryId == deliveryId && _riderLiveLocationTimer != null) {
      return;
    }
    _stopRiderLiveLocationPublishing(status: 'switching');
    final allowed = await _ensureRiderLocationPermission();
    if (!allowed) {
      if (mounted) {
        setState(
          () => _jobMessage =
              'Location permission is needed for live tracking while travelling.',
        );
      }
      return;
    }
    _trackingDeliveryId = deliveryId;
    await _publishRiderLiveLocation(deliveryId, riderId, status);
    _riderLiveLocationTimer = Timer.periodic(const Duration(seconds: 7), (_) {
      _publishRiderLiveLocation(deliveryId, riderId, status);
    });
  }

  void _stopRiderLiveLocationPublishing({required String status}) {
    final deliveryId = _trackingDeliveryId;
    final riderId = _riderUser?.uid;
    _riderLiveLocationTimer?.cancel();
    _riderLiveLocationTimer = null;
    _trackingDeliveryId = null;
    if (deliveryId != null && riderId != null) {
      FirebaseFirestore.instance
          .collection('deliveryRequests')
          .doc(deliveryId)
          .collection('tracking')
          .doc('liveLocation')
          .set({
        'riderId': riderId,
        'status': status,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }
  }

  Future<bool> _ensureRiderLocationPermission() async {
    try {
      final serviceEnabled = await Geolocator.isLocationServiceEnabled();
      if (!serviceEnabled) return false;
      var permission = await Geolocator.checkPermission();
      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
      }
      return permission == LocationPermission.always ||
          permission == LocationPermission.whileInUse;
    } catch (_) {
      return false;
    }
  }

  Future<void> _publishRiderLiveLocation(
    String deliveryId,
    String riderId,
    String status,
  ) async {
    try {
      final position = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.high,
          timeLimit: Duration(seconds: 6),
        ),
      );
      await FirebaseFirestore.instance
          .collection('deliveryRequests')
          .doc(deliveryId)
          .collection('tracking')
          .doc('liveLocation')
          .set({
        'riderId': riderId,
        'latitude': position.latitude,
        'longitude': position.longitude,
        'heading': position.heading,
        'speed': position.speed,
        'accuracy': position.accuracy,
        'status': status,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    } catch (_) {
      if (mounted) {
        setState(() => _jobMessage = 'Live tracking update could not be sent.');
      }
    }
  }

  Future<void> _rejectOrIgnoreJob(
    Map<String, dynamic> job,
    String action,
  ) async {
    final user = _riderUser;
    if (user == null) {
      setState(() => _jobMessage = 'Sign in before updating a job.');
      return;
    }
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    if (requestId.isEmpty) return;
    final field = action == 'reject' ? 'rejectedByRiders' : 'ignoredByRiders';
    final timestampField = action == 'reject' ? 'rejectedAt' : 'ignoredAt';
    try {
      await FirebaseFirestore.instance
          .collection('deliveryRequests')
          .doc(requestId)
          .set({
        field: FieldValue.arrayUnion([user.uid]),
        timestampField: FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      if (!mounted) return;
      setState(
        () => _jobMessage =
            action == 'reject' ? 'Job rejected.' : 'Job hidden for now.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _jobMessage = 'Could not update this job. Try again.');
    }
  }

  Future<void> _updateAcceptedJobStatus(
    Map<String, dynamic> job,
    String status,
  ) async {
    final user = _riderUser;
    if (user == null) {
      setState(() => _jobMessage = 'Sign in before updating a job.');
      return;
    }
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    if (requestId.isEmpty) return;
    setState(() => _jobMessage = 'Updating job $requestId...');
    try {
      final db = FirebaseFirestore.instance;
      if (status == 'rider_arrived_pickup') {
        await _markRiderArrivedAtPickup(db, requestId, user.uid);
        if (!mounted) return;
        setState(() => _jobMessage = 'Sender notified. Waiting timer started.');
        return;
      }
      if (status == 'sender_contact_established' ||
          status == 'sender_no_contact') {
        await _updateSenderContactStatus(
          db,
          requestId,
          user.uid,
          established: status == 'sender_contact_established',
        );
        if (!mounted) return;
        setState(() => _jobMessage = status == 'sender_contact_established'
            ? 'Contact marked as established.'
            : 'No contact marked.');
        return;
      }
      if (status.startsWith('extend_wait_')) {
        final minutes = int.tryParse(status.replaceFirst('extend_wait_', ''));
        if (minutes == null) return;
        await _extendPickupWaiting(db, job, requestId, user.uid, minutes);
        if (!mounted) return;
        setState(() => _jobMessage = 'Waiting time extended.');
        return;
      }
      if (status == 'sender_no_show_pickup') {
        await _markSenderNoShowAtPickup(db, requestId, user.uid);
        if (!mounted) return;
        setState(() => _jobMessage = 'Sender no-show recorded.');
        return;
      }
      final vanguardPatch = await _collectVanguardPinVerification(
        job,
        requestId,
        user.uid,
        status,
      );
      if (vanguardPatch == null &&
          _jobVanguardEnabled(job) &&
          (status == 'picked_up' || status == 'completed')) {
        return;
      }
      final verificationPatch = status == 'picked_up'
          ? await _collectWeightVerification(job, requestId, user.uid)
          : null;
      if (status == 'picked_up' && verificationPatch == null) {
        if (!mounted) return;
        setState(() => _jobMessage = 'Verify parcel weight before pickup.');
        return;
      }
      final updates = <String, dynamic>{
        'status': status,
        'dispatchStatus': status,
        'updatedAt': FieldValue.serverTimestamp(),
      };
      if (status == 'picked_up') {
        updates['pickedUpAt'] = FieldValue.serverTimestamp();
        if (vanguardPatch != null) updates.addAll(vanguardPatch);
        updates.addAll(verificationPatch!);
      }
      if (status == 'in_transit') {
        updates['outForDeliveryAt'] = FieldValue.serverTimestamp();
      }
      if (status == 'completed') {
        updates['completedAt'] = FieldValue.serverTimestamp();
        if (vanguardPatch != null) updates.addAll(vanguardPatch);
        final payout = _jobPayout(job);
        final tip = _jobTip(job);
        final totalCredit = payout + tip;
        final txId = RiderMarketplaceRules.earningTransactionId(
          deliveryId: requestId,
          riderId: user.uid,
        );
        final deliveryRef = db.collection('deliveryRequests').doc(requestId);
        final walletRef = db.collection('riderWalletTransactions').doc(txId);
        final earningsRef = db.collection('riderEarnings').doc(user.uid);
        final rothWalletRef = db.collection('wallets').doc(user.uid);
        final rothLedgerRef =
            db.collection('walletTransactions').doc('roth_$txId');
        await db.runTransaction((transaction) async {
          final existingWallet = await transaction.get(walletRef);
          final existingRothLedger = await transaction.get(rothLedgerRef);
          final rothWallet = await transaction.get(rothWalletRef);
          transaction.set(deliveryRef, updates, SetOptions(merge: true));
          if (existingWallet.exists) return;
          transaction.set(
              walletRef,
              {
                'id': txId,
                'transactionId': txId,
                'deliveryId': requestId,
                'requestId': requestId,
                'riderId': user.uid,
                'type': 'earning',
                'deliveryEarning': payout,
                'tipAmount': tip,
                'amount': totalCredit,
                'status': 'pending',
                'notes': 'Completed delivery awaiting admin settlement.',
                'createdAt': FieldValue.serverTimestamp(),
                'updatedAt': FieldValue.serverTimestamp(),
              },
              SetOptions(merge: true));
          transaction.set(
              earningsRef,
              {
                'riderId': user.uid,
                'availableBalance': FieldValue.increment(0),
                'pendingBalance': FieldValue.increment(totalCredit),
                'lifetimeEarnings': FieldValue.increment(totalCredit),
                'totalWithdrawn': FieldValue.increment(0),
                'tipsReceived': FieldValue.increment(tip),
                'completedJobs': FieldValue.increment(1),
                'updatedAt': FieldValue.serverTimestamp(),
              },
              SetOptions(merge: true));
          if (!existingRothLedger.exists) {
            final rothBefore =
                (rothWallet.data()?['pendingEarnings'] as num?)?.toDouble() ??
                    0;
            final rothAfter =
                double.parse((rothBefore + totalCredit).toStringAsFixed(2));
            transaction.set(
                rothLedgerRef,
                {
                  'id': 'roth_$txId',
                  'userId': user.uid,
                  'amount': totalCredit,
                  'balanceType': 'pendingEarnings',
                  'type': 'earnings_pending',
                  'reason': 'Completed delivery awaiting admin settlement.',
                  'relatedEntityId': requestId,
                  'paymentProvider': 'roth_internal',
                  'providerTransactionId': null,
                  'balanceBefore': rothBefore,
                  'balanceAfter': rothAfter,
                  'createdAt': FieldValue.serverTimestamp(),
                  'metadata': {
                    'deliveryId': requestId,
                    'riderId': user.uid,
                    'legacyTransactionId': txId,
                    'deliveryEarning': payout,
                    'tipAmount': tip,
                  },
                },
                SetOptions(merge: false));
            transaction.set(
                rothWalletRef,
                {
                  'userId': user.uid,
                  'rothCredit': FieldValue.increment(0),
                  'pendingEarnings': FieldValue.increment(totalCredit),
                  'availableEarnings': FieldValue.increment(0),
                  'updatedAt': FieldValue.serverTimestamp(),
                  'createdAt': FieldValue.serverTimestamp(),
                },
                SetOptions(merge: true));
          }
        });
      } else {
        await db
            .collection('deliveryRequests')
            .doc(requestId)
            .set(updates, SetOptions(merge: true));
      }
      if (status == 'completed' || status == 'cancelled') {
        _stopRiderLiveLocationPublishing(status: status);
      }
      if (!mounted) return;
      setState(
        () => _jobMessage =
            status == 'completed' ? 'Delivery completed.' : 'Job updated.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _jobMessage = 'Could not update this job. Try again.');
    }
  }

  Future<void> _markRiderArrivedAtPickup(
    FirebaseFirestore db,
    String requestId,
    String riderId,
  ) async {
    final now = DateTime.now();
    final deadline = now.add(const Duration(minutes: 3));
    final deliveryRef = db.collection('deliveryRequests').doc(requestId);
    var alreadyArrived = false;
    await db.runTransaction((transaction) async {
      final snap = await transaction.get(deliveryRef);
      final data = snap.data();
      if (data == null) throw StateError('Delivery not found.');
      if (data['riderArrivedAtPickupAt'] != null ||
          '${data['status'] ?? ''}' == 'rider_arrived_pickup') {
        alreadyArrived = true;
        return;
      }
      transaction.set(
          deliveryRef,
          {
            'status': 'rider_arrived_pickup',
            'dispatchStatus': 'rider_arrived_pickup',
            'riderArrivedAtPickupAt': FieldValue.serverTimestamp(),
            'pickupWaitStartedAt': FieldValue.serverTimestamp(),
            'pickupWaitDeadlineAt': Timestamp.fromDate(deadline),
            'senderContactEstablished': false,
            'updatedAt': FieldValue.serverTimestamp(),
            'auditTrail': FieldValue.arrayUnion([
              _deliveryAuditEvent(
                type: 'rider_arrived_pickup',
                label: 'Rider arrived at pickup',
                riderId: riderId,
                status: 'rider_arrived_pickup',
              ),
              _deliveryAuditEvent(
                type: 'pickup_wait_started',
                label: 'Waiting period started',
                riderId: riderId,
                status: 'rider_arrived_pickup',
              ),
            ]),
          },
          SetOptions(merge: true));
    });
    if (alreadyArrived) return;
    await _sendDeliverySystemMessage(
      requestId,
      'Your rider is waiting at the pickup address. Please meet them within 3 minutes.',
    );
  }

  Future<void> _updateSenderContactStatus(
    FirebaseFirestore db,
    String requestId,
    String riderId, {
    required bool established,
  }) async {
    await db.collection('deliveryRequests').doc(requestId).set({
      'senderContactEstablished': established,
      'senderContactEstablishedAt':
          established ? FieldValue.serverTimestamp() : FieldValue.delete(),
      'senderContactStatusUpdatedBy': riderId,
      'updatedAt': FieldValue.serverTimestamp(),
      'auditTrail': FieldValue.arrayUnion([
        _deliveryAuditEvent(
          type:
              established ? 'sender_contact_established' : 'sender_no_contact',
          label: established ? 'Contact established' : 'No contact',
          riderId: riderId,
          status: 'rider_arrived_pickup',
        ),
      ]),
    }, SetOptions(merge: true));
  }

  Future<void> _extendPickupWaiting(
    FirebaseFirestore db,
    Map<String, dynamic> job,
    String requestId,
    String riderId,
    int minutes,
  ) async {
    const charges = {5: 2.0, 10: 4.0, 15: 6.0};
    final charge = charges[minutes];
    if (charge == null) return;
    if (job['senderContactEstablished'] != true) {
      setState(() => _jobMessage =
          'Waiting can only be extended after contact is established.');
      return;
    }
    if (job['pickupWaitExtended'] == true) {
      setState(() => _jobMessage = 'Waiting has already been extended.');
      return;
    }
    final currentDeadline = _timestampDate(job['pickupWaitDeadlineAt']);
    final base =
        currentDeadline != null && currentDeadline.isAfter(DateTime.now())
            ? currentDeadline
            : DateTime.now();
    final newDeadline = base.add(Duration(minutes: minutes));
    await db.collection('deliveryRequests').doc(requestId).set({
      'pickupWaitExtended': true,
      'pickupWaitExtensionMinutes': minutes,
      'pickupWaitExtensionCharge': charge,
      'pickupWaitExtensionChargeGbp': charge,
      'pickupWaitExtensionReason': 'Contact established',
      'pickupWaitExtendedAt': FieldValue.serverTimestamp(),
      'pickupWaitDeadlineAt': Timestamp.fromDate(newDeadline),
      'waitingSurchargeTotalGbp': FieldValue.increment(charge),
      'currency': 'GBP',
      'updatedAt': FieldValue.serverTimestamp(),
      'auditTrail': FieldValue.arrayUnion([
        _deliveryAuditEvent(
          type: 'pickup_wait_extended',
          label: 'Waiting extended by $minutes minutes',
          riderId: riderId,
          status: 'rider_arrived_pickup',
          amountGbp: charge,
        ),
        _deliveryAuditEvent(
          type: 'waiting_charge_applied',
          label:
              'Additional waiting charge applied: £${charge.toStringAsFixed(2)}',
          riderId: riderId,
          status: 'rider_arrived_pickup',
          amountGbp: charge,
        ),
      ]),
    }, SetOptions(merge: true));
    await _sendDeliverySystemMessage(
      requestId,
      'Your rider is still waiting. Extra waiting time has been approved. Additional waiting charge: £${charge.toStringAsFixed(2)}.',
    );
  }

  Future<void> _markSenderNoShowAtPickup(
    FirebaseFirestore db,
    String requestId,
    String riderId,
  ) async {
    final deliveryRef = db.collection('deliveryRequests').doc(requestId);
    await db.runTransaction((transaction) async {
      final snap = await transaction.get(deliveryRef);
      final data = snap.data();
      if (data == null) {
        throw StateError('Delivery not found.');
      }
      if (data['senderContactEstablished'] == true) {
        throw StateError('Contact was established. Extend waiting instead.');
      }
      final deadline = _timestampDate(data['pickupWaitDeadlineAt']);
      if (deadline == null || DateTime.now().isBefore(deadline)) {
        throw StateError('The 3-minute waiting period is still active.');
      }
      if (data['pickupNoShowSurchargeApplied'] == true) {
        return;
      }
      transaction.set(
          deliveryRef,
          {
            'status': 'sender_no_show_pickup',
            'dispatchStatus': 'sender_no_show_pickup',
            'pickupNoShowAt': FieldValue.serverTimestamp(),
            'pickupNoShowReason': 'No contact after pickup waiting period',
            'pickupNoShowSurchargeApplied': true,
            'pickupNoShowSurchargeGbp': 5.0,
            'waitingSurchargeTotalGbp': FieldValue.increment(5.0),
            'currency': 'GBP',
            'updatedAt': FieldValue.serverTimestamp(),
            'auditTrail': FieldValue.arrayUnion([
              _deliveryAuditEvent(
                type: 'sender_no_show_pickup',
                label: 'Sender no-show marked',
                riderId: riderId,
                status: 'sender_no_show_pickup',
              ),
              _deliveryAuditEvent(
                type: 'no_show_surcharge_applied',
                label: 'No-show surcharge applied: £5.00',
                riderId: riderId,
                status: 'sender_no_show_pickup',
                amountGbp: 5.0,
              ),
            ]),
          },
          SetOptions(merge: true));
    });
    await _sendDeliverySystemMessage(
      requestId,
      'Pickup was marked as no-show after the waiting period. A £5.00 waiting/no-show surcharge has been applied because the rider could not make contact.',
    );
  }

  Map<String, dynamic> _deliveryAuditEvent({
    required String type,
    required String label,
    required String riderId,
    required String status,
    double? amountGbp,
  }) {
    return {
      'type': type,
      'label': label,
      'event': label,
      'actorType': 'rider',
      'actorId': riderId,
      'statusAfterEvent': status,
      'currency': 'GBP',
      if (amountGbp != null) 'amountGbp': amountGbp,
      'createdAt': Timestamp.now(),
    };
  }

  Future<void> _sendDeliverySystemMessage(
    String requestId,
    String message,
  ) async {
    await FirebaseFirestore.instance
        .collection('chats')
        .doc(requestId)
        .collection('messages')
        .add({
      'threadId': requestId,
      'bookingId': requestId,
      'requestId': requestId,
      'senderId': 'circum-system',
      'senderRole': 'system',
      'senderType': 'support',
      'messageText': message,
      'message': message,
      'system': true,
      'status': 'sent',
      'createdAt': FieldValue.serverTimestamp(),
      'timeStamp': DateTime.now().toIso8601String(),
    });
  }

  DateTime? _timestampDate(dynamic value) {
    if (value is Timestamp) return value.toDate();
    if (value is DateTime) return value;
    if (value is String) return DateTime.tryParse(value);
    return null;
  }

  Future<Map<String, dynamic>?> _collectVanguardPinVerification(
    Map<String, dynamic> job,
    String requestId,
    String riderId,
    String status,
  ) async {
    if (!_jobVanguardEnabled(job) ||
        (status != 'picked_up' && status != 'completed')) {
      return const <String, dynamic>{};
    }
    final stage = status == 'completed' ? 'delivery' : 'collection';
    final alreadyVerified = stage == 'delivery'
        ? job['deliveryPinVerified'] == true
        : job['collectionPinVerified'] == true;
    if (alreadyVerified) return const <String, dynamic>{};

    final summary =
        (job['driverJobSummary'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
    final collectionContact =
        (job['collectionContact'] as Map?)?.cast<String, dynamic>();
    final receiverDetails =
        (job['receiverDetails'] as Map?)?.cast<String, dynamic>();
    final collectionName =
        '${summary['collectionContactName'] ?? job['collectionContactName'] ?? collectionContact?['name'] ?? job['senderName'] ?? 'the sender or collection contact'}'
            .trim();
    final receiverName =
        '${summary['receiverName'] ?? job['receiverName'] ?? receiverDetails?['name'] ?? 'the receiver'}'
            .trim();
    final pinController = TextEditingController();
    String? errorText;
    final enteredPin = await showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: Text(
            stage == 'delivery' ? 'Enter delivery PIN' : 'Enter collection PIN',
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                stage == 'delivery'
                    ? 'This is a Vanguard protected delivery. Enter ${receiverName.isEmpty ? 'the receiver' : receiverName}’s delivery PIN to complete delivery.'
                    : 'This is a Vanguard protected delivery. Enter ${collectionName.isEmpty ? 'the sender or collection contact' : collectionName}’s collection PIN to confirm handover.',
                style: TextStyle(color: Theme.of(context).hintColor),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: pinController,
                keyboardType: TextInputType.number,
                maxLength: 6,
                decoration: const InputDecoration(
                  labelText: '6-digit PIN',
                  border: OutlineInputBorder(),
                  counterText: '',
                ),
              ),
              if (errorText != null) ...[
                const SizedBox(height: 8),
                Text(errorText!, style: const TextStyle(color: Colors.red)),
              ],
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                final value = pinController.text.trim();
                if (!RegExp(r'^\d{6}$').hasMatch(value)) {
                  setDialogState(
                    () => errorText = 'Enter the 6-digit Vanguard PIN.',
                  );
                  return;
                }
                Navigator.pop(context, value);
              },
              child: const Text('Verify PIN'),
            ),
          ],
        ),
      ),
    );
    pinController.dispose();
    if (enteredPin == null) {
      setState(
        () => _jobMessage = stage == 'delivery'
            ? 'Delivery PIN required before completion.'
            : 'Collection PIN required before pickup.',
      );
      return null;
    }

    final attemptField = stage == 'delivery'
        ? 'deliveryPinAttemptCount'
        : 'collectionPinAttemptCount';
    final attemptCount = _numberValue(job[attemptField])?.toInt() ?? 0;
    final expectedPin = stage == 'delivery'
        ? VanguardProtection.deliveryPin(job)
        : VanguardProtection.collectionPin(job);
    final check = VanguardProtection.verifyPin(
      enabled: true,
      expectedPin: expectedPin,
      enteredPin: enteredPin,
      attemptCount: attemptCount,
      stage: stage,
    );
    if (!check.passed) {
      await FirebaseFirestore.instance
          .collection('deliveryRequests')
          .doc(requestId)
          .set({
        attemptField: check.attemptCount,
        'vanguardReviewRequired': check.flagForReview,
        'vanguardLastFailedStage': stage,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      if (!mounted) return null;
      setState(() => _jobMessage = check.errorMessage);
      return null;
    }

    final protection =
        (job['vanguardProtection'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
    final nextProtection = {
      ...protection,
      stage == 'delivery' ? 'deliveryPin' : 'collectionPin': null,
    };
    final verifiedField =
        stage == 'delivery' ? 'deliveryPinVerified' : 'collectionPinVerified';
    final verifiedAtField = stage == 'delivery'
        ? 'deliveryPinVerifiedAt'
        : 'collectionPinVerifiedAt';
    final verifiedByField = stage == 'delivery'
        ? 'deliveryPinVerifiedBy'
        : 'collectionPinVerifiedBy';
    return {
      verifiedField: true,
      verifiedAtField: FieldValue.serverTimestamp(),
      verifiedByField: riderId,
      attemptField: check.attemptCount,
      'vanguardProtection': nextProtection,
      'vanguardVerification': {
        stage: {
          'status': 'passed',
          'riderId': riderId,
          'verifiedAt': FieldValue.serverTimestamp(),
          'attemptCount': check.attemptCount,
        },
      },
    };
  }

  bool _jobVanguardEnabled(Map<String, dynamic> job) {
    if (job['vanguardEnabled'] == true) return true;
    final protection =
        (job['vanguardProtection'] as Map?)?.cast<String, dynamic>();
    return protection?['enabled'] == true;
  }

  Future<Map<String, dynamic>?> _collectWeightVerification(
    Map<String, dynamic> job,
    String requestId,
    String riderId,
  ) async {
    final currentFinalWeight = _jobFinalWeight(job);
    final weightController = TextEditingController(
      text: currentFinalWeight.toStringAsFixed(1),
    );
    final noteController = TextEditingController();
    final irisEstimate =
        (job['irisDeliveryEstimate'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
    final rawIrisFlags =
        (irisEstimate['flags'] as List?) ?? (job['irisDeliveryFlags'] as List?);
    final irisFlags = (rawIrisFlags ?? const [])
        .map((flag) => '$flag')
        .where((flag) => flag.trim().isNotEmpty)
        .toList(growable: false);
    var option = 'accurate';
    var pickedPhotos = <XFile>[];
    String? errorText;
    final result = await showDialog<Map<String, dynamic>>(
      context: context,
      barrierDismissible: false,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: const Text('Verify parcel weight'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Before pickup, confirm whether the parcel matches the paid weight. Evidence is required for increases.',
                  style: TextStyle(color: Theme.of(context).hintColor),
                ),
                if (irisEstimate.isNotEmpty) ...[
                  const SizedBox(height: 12),
                  Text(
                    'IRIS estimate: ${irisEstimate['finalBillableWeightKg'] ?? irisEstimate['irisWeightKg'] ?? currentFinalWeight}kg'
                    ' · ${irisEstimate['confidenceBand'] ?? job['irisConfidenceBand'] ?? 'pending'} confidence'
                    ' · ${irisEstimate['suggestedVehicle'] ?? job['vehicleType'] ?? 'vehicle to verify'}',
                    style: const TextStyle(fontWeight: FontWeight.w800),
                  ),
                  if (irisFlags.isNotEmpty) ...[
                    const SizedBox(height: 6),
                    Wrap(
                      spacing: 6,
                      runSpacing: 6,
                      children: irisFlags
                          .map(
                            (flag) => Chip(
                              visualDensity: VisualDensity.compact,
                              label: Text(
                                flag.replaceAll('_', ' '),
                                style: const TextStyle(fontSize: 11),
                              ),
                            ),
                          )
                          .toList(),
                    ),
                  ],
                ],
                const SizedBox(height: 12),
                RadioListTile<String>(
                  value: 'accurate',
                  groupValue: option,
                  onChanged: (value) =>
                      setDialogState(() => option = value ?? option),
                  title: const Text('Looks correct'),
                  contentPadding: EdgeInsets.zero,
                ),
                RadioListTile<String>(
                  value: 'heavier',
                  groupValue: option,
                  onChanged: (value) =>
                      setDialogState(() => option = value ?? option),
                  title: const Text('Needs correction - weight is higher'),
                  contentPadding: EdgeInsets.zero,
                ),
                RadioListTile<String>(
                  value: 'significant',
                  groupValue: option,
                  onChanged: (value) =>
                      setDialogState(() => option = value ?? option),
                  title: const Text('Weight is significantly heavier'),
                  contentPadding: EdgeInsets.zero,
                ),
                const SizedBox(height: 8),
                TextField(
                  controller: weightController,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: const InputDecoration(
                    labelText: 'Verified weight in kg',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: noteController,
                  maxLines: 2,
                  decoration: const InputDecoration(
                    labelText: 'Optional note',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),
                OutlinedButton.icon(
                  onPressed: () async {
                    final picked = await ImagePicker().pickMultiImage(
                      imageQuality: 80,
                      maxWidth: 1800,
                    );
                    setDialogState(() => pickedPhotos = picked);
                  },
                  icon: const Icon(Icons.photo_camera),
                  label: Text(
                    pickedPhotos.isEmpty
                        ? 'Add evidence photo'
                        : '${pickedPhotos.length} photo(s) added',
                  ),
                ),
                if (errorText != null) ...[
                  const SizedBox(height: 8),
                  Text(errorText!, style: const TextStyle(color: Colors.red)),
                ],
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                final verifiedWeight =
                    double.tryParse(weightController.text.trim()) ?? 0;
                final requiresEvidence = option != 'accurate';
                if (verifiedWeight <= 0) {
                  setDialogState(() => errorText = 'Enter a valid weight.');
                  return;
                }
                if (requiresEvidence && verifiedWeight <= currentFinalWeight) {
                  setDialogState(
                    () => errorText =
                        'Corrected weight must be higher than the current paid weight.',
                  );
                  return;
                }
                if (requiresEvidence && pickedPhotos.isEmpty) {
                  setDialogState(
                    () => errorText = 'Add at least one evidence photo.',
                  );
                  return;
                }
                Navigator.pop(context, {
                  'option': option,
                  'verifiedWeightKg': verifiedWeight,
                  'note': noteController.text.trim(),
                  'photos': pickedPhotos,
                });
              },
              child: const Text('Save verification'),
            ),
          ],
        ),
      ),
    );
    weightController.dispose();
    noteController.dispose();
    if (result == null) return null;

    final optionValue = '${result['option']}';
    final verifiedWeight = result['verifiedWeightKg'] as double;
    final photos = (result['photos'] as List<XFile>? ?? const <XFile>[]);
    final evidenceUrls = <String>[];
    final storagePaths = <String>[];
    for (final photo in photos) {
      final bytes = await photo.readAsBytes();
      final safeName = photo.name.replaceAll(RegExp(r'[^A-Za-z0-9._-]'), '_');
      final path =
          'delivery_weight_evidence/$requestId/$riderId/${DateTime.now().millisecondsSinceEpoch}_$safeName';
      final ref = FirebaseStorage.instance.ref(path);
      await ref.putData(bytes);
      storagePaths.add(path);
      evidenceUrls.add(await ref.getDownloadURL());
    }

    final customerWeight = _jobCustomerWeight(job);
    final irisWeight = _jobIrisWeight(job);
    final finalWeightUsed = DeliveryPricing.finalVerifiedWeightKg(
      customerWeightKg: customerWeight,
      irisWeightKg: irisWeight,
      riderVerifiedWeightKg: verifiedWeight,
    );
    final distanceMiles = _jobDistanceMiles(job);
    final vehicle = DeliveryPricing.recommendedVehicleForWeight(
      finalWeightUsed,
    );
    DeliveryAccess accessValue(Object? value) {
      return switch ('$value') {
        'stairs' => DeliveryAccess.stairs,
        'liftAvailable' => DeliveryAccess.liftAvailable,
        _ => DeliveryAccess.groundFloor,
      };
    }

    final revisedHandling = SpecialHandlingEngine.evaluate(
      description: '${job['packageDescription'] ?? ''}',
      itemName: '${job['normalizedItemName'] ?? ''}',
      pickupAccess: accessValue(job['pickupAccess']),
      dropoffAccess: accessValue(job['dropoffAccess']),
    );
    final revisedQuote = revisedHandling.applyTo(DeliveryPricing.calculate(
      DeliveryPricingInput(
        distanceMiles: distanceMiles,
        weightKg: finalWeightUsed,
        vehicleType: vehicle,
      ),
    ));
    final revisedPayout = revisedQuote.totalRiderEarnings;
    final revisedPlatformRevenue = revisedQuote.totalCircumRevenue;
    final heavier = finalWeightUsed > currentFinalWeight + 0.01;
    final summary =
        (job['driverJobSummary'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};

    if (heavier) {
      await FirebaseFirestore.instance.collection('notifications').add({
        'recipientId': job['senderId'] ?? job['userId'],
        'requestId': requestId,
        'type': 'weight_adjusted',
        'title': 'Parcel weight updated',
        'message':
            'Parcel weight differs from original declaration. Pricing has been adjusted.',
        'createdAt': FieldValue.serverTimestamp(),
        'read': false,
        'source': 'circum-web',
      });
    }

    final correctionId =
        'IC-$requestId-${DateTime.now().millisecondsSinceEpoch}';
    final previousEstimateId =
        '${job['irisDeliveryEstimateId'] ?? requestId}'.trim();
    if (optionValue == 'accurate') {
      await FirebaseFirestore.instance
          .collection('irisDeliveryEstimates')
          .doc(previousEstimateId.isEmpty ? requestId : previousEstimateId)
          .set({
        'riderVerificationStatus': 'looks_correct',
        'riderVerifiedWeightKg': verifiedWeight,
        'riderVerifiedAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    } else {
      await FirebaseFirestore.instance
          .collection('irisCorrections')
          .doc(correctionId)
          .set({
        'correctionId': correctionId,
        'estimateId':
            previousEstimateId.isEmpty ? requestId : previousEstimateId,
        'bookingId': requestId,
        'correctedBy': 'rider',
        'previousWeightKg': currentFinalWeight,
        'correctedWeightKg': verifiedWeight,
        'correctionReason': optionValue,
        'correctionNotes': result['note'],
        'evidenceUrls': evidenceUrls,
        'storagePaths': storagePaths,
        'riderId': riderId,
        'createdAt': FieldValue.serverTimestamp(),
        'approvedByAdmin': false,
        'appliedToRepository': false,
      });
      await FirebaseFirestore.instance
          .collection('irisDeliveryEstimates')
          .doc(previousEstimateId.isEmpty ? requestId : previousEstimateId)
          .set({
        'latestCorrectionId': correctionId,
        'riderVerificationStatus': 'needs_correction',
        'riderVerifiedWeightKg': verifiedWeight,
        'adminReviewStatus': 'open',
        'requiresAdminReview': true,
        'flags': FieldValue.arrayUnion(['admin_review_required']),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }

    return {
      'riderVerifiedWeight': verifiedWeight,
      'riderVerifiedWeightKg': verifiedWeight,
      'finalVerifiedWeight': finalWeightUsed,
      'finalWeightUsed': finalWeightUsed,
      'finalChargeableWeight': finalWeightUsed,
      'confirmedWeightKg': finalWeightUsed,
      'confirmedWeightBand': DeliveryPricing.weightBandFor(
        finalWeightUsed,
      ).category,
      'weightCategory': DeliveryPricing.weightBandFor(finalWeightUsed).category,
      'vehicleType': vehicle,
      'vehicle': vehicle,
      'preferredVehicle': vehicle.toLowerCase(),
      'quote': revisedQuote.total,
      'price': revisedQuote.total,
      'fare': revisedQuote.total,
      'driverPayout': revisedPayout,
      'riderPayout': revisedPayout,
      'platformRevenue': revisedPlatformRevenue,
      'riderBaseShare': revisedQuote.riderBaseShare,
      'riderLabourShare': revisedQuote.riderLabourShare,
      'circumBaseShare': revisedQuote.circumBaseShare,
      'circumLabourShare': revisedQuote.circumLabourShare,
      'platformShare': DeliveryPricing.platformDeliveryFareShare,
      'driverShare': DeliveryPricing.riderDeliveryFareShare,
      'pricingBreakdown': revisedQuote.toJson(),
      'weightReviewRequired': optionValue != 'accurate',
      'weightDisputeStatus':
          optionValue == 'accurate' ? 'verified' : 'admin_review',
      'driverWeightDispute': {
        'reported': optionValue != 'accurate',
        'issueType': optionValue,
        'reportedBy': riderId,
        'reportedAt': FieldValue.serverTimestamp(),
        'status': optionValue == 'accurate' ? 'verified' : 'admin_review',
      },
      'weightVerification': {
        'customerWeight': customerWeight,
        'irisWeight': irisWeight,
        'riderVerifiedWeight': verifiedWeight,
        'finalWeightUsed': finalWeightUsed,
        'previousFinalWeight': currentFinalWeight,
        'option': optionValue,
        'riderId': riderId,
        'note': result['note'],
        'supportingImages': evidenceUrls,
        'storagePaths': storagePaths,
        'timestamp': FieldValue.serverTimestamp(),
      },
      'driverJobSummary': {
        ...summary,
        'finalWeightUsed': finalWeightUsed,
        'finalChargeableWeight': finalWeightUsed,
        'confirmedWeightKg': finalWeightUsed,
        'confirmedWeightBand': DeliveryPricing.weightBandFor(
          finalWeightUsed,
        ).category,
        'driverPayout': revisedPayout,
        'riderPayout': revisedPayout,
        'platformRevenue': revisedPlatformRevenue,
        'totalFare': revisedQuote.total,
        'vehicleType': vehicle,
      },
    };
  }

  double _jobPayout(Map<String, dynamic> job) {
    final summary = (job['driverJobSummary'] as Map?)?.cast<String, dynamic>();
    final value = summary?['driverPayout'] ?? job['driverPayout'];
    if (value is num) return value.toDouble();
    return double.tryParse('$value') ?? 0;
  }

  double _jobTip(Map<String, dynamic> job) {
    final value = job['tipAmount'] ?? job['riderTip'] ?? job['tip'];
    if (value is num) return value.toDouble();
    return double.tryParse('$value') ?? 0;
  }

  double _jobCustomerWeight(Map<String, dynamic> job) {
    return _jobNumber(job, [
      'customerWeight',
      'customerDeclaredWeight',
      'senderEnteredWeightKg',
      'declaredWeightKg',
    ]);
  }

  double _jobIrisWeight(Map<String, dynamic> job) {
    return _jobNumber(job, [
      'irisWeight',
      'irisEstimatedWeight',
      'irisEstimatedWeightKg',
    ]);
  }

  double _jobFinalWeight(Map<String, dynamic> job) {
    final summary = (job['driverJobSummary'] as Map?)?.cast<String, dynamic>();
    return _numberValue(job['finalWeightUsed']) ??
        _numberValue(job['finalChargeableWeight']) ??
        _numberValue(job['confirmedWeightKg']) ??
        _numberValue(summary?['finalWeightUsed']) ??
        _numberValue(summary?['confirmedWeightKg']) ??
        0;
  }

  double _jobDistanceMiles(Map<String, dynamic> job) {
    final summary = (job['driverJobSummary'] as Map?)?.cast<String, dynamic>();
    final pricing = (job['pricingBreakdown'] as Map?)?.cast<String, dynamic>();
    return _numberValue(summary?['estimatedDistanceMiles']) ??
        _numberValue(job['estimatedDistanceMiles']) ??
        _numberValue(pricing?['distanceMiles']) ??
        _webQuoteDistanceMiles;
  }

  double _jobNumber(Map<String, dynamic> job, List<String> keys) {
    final summary = (job['driverJobSummary'] as Map?)?.cast<String, dynamic>();
    for (final key in keys) {
      final direct = _numberValue(job[key]);
      if (direct != null) return direct;
      final nested = _numberValue(summary?[key]);
      if (nested != null) return nested;
    }
    return 0;
  }

  double? _numberValue(Object? value) {
    if (value is num) return value.toDouble();
    return double.tryParse('$value');
  }

  Future<void> _reportParcelIssue(
    Map<String, dynamic> job,
    String issueType,
  ) async {
    final user = _riderUser;
    if (user == null) {
      setState(() => _jobMessage = 'Sign in before reporting an issue.');
      return;
    }
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    if (requestId.isEmpty) return;
    final reason = await _showLoadDiscrepancyDialog(job);
    if (reason == null) return;
    setState(() => _jobMessage = 'Recalculating this booking...');
    try {
      await FirebaseFunctions.instance
          .httpsCallable('reportLoadDiscrepancy')
          .call(reason);
      if (!mounted) return;
      setState(() => _jobMessage =
          'Discrepancy reported. Collection is paused for the sender.');
    } on FirebaseFunctionsException catch (error) {
      if (!mounted) return;
      setState(() => _jobMessage =
          error.message ?? 'Could not report this discrepancy. Try again.');
    }
  }

  Future<Map<String, dynamic>?> _showLoadDiscrepancyDialog(
    Map<String, dynamic> job,
  ) async {
    final user = _riderUser;
    if (user == null) return null;
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    var reason = 'weight_exceeded';
    String? observedVehicleType;
    final weight = TextEditingController();
    final description = TextEditingController();
    final dimensions = TextEditingController();
    final notes = TextEditingController();
    final photos = <XFile>[];
    var uploading = false;
    String? error;
    final result = await showDialog<Map<String, dynamic>>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: const Text('Report Load Discrepancy'),
          content: SizedBox(
            width: 460,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  DropdownButtonFormField<String>(
                    initialValue: reason,
                    decoration: const InputDecoration(labelText: 'Reason'),
                    items: const [
                      DropdownMenuItem(
                          value: 'weight_exceeded',
                          child: Text('Weight exceeded')),
                      DropdownMenuItem(
                          value: 'dimensions_exceeded',
                          child: Text('Dimensions exceeded')),
                      DropdownMenuItem(
                          value: 'additional_undeclared_items',
                          child: Text('Additional undeclared items')),
                      DropdownMenuItem(
                          value: 'item_differs_from_booking',
                          child: Text('Item differs from booking')),
                    ],
                    onChanged: (value) =>
                        setDialogState(() => reason = value ?? reason),
                  ),
                  const SizedBox(height: 12),
                  if (reason == 'weight_exceeded')
                    TextField(
                      controller: weight,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                          labelText: 'Observed weight (kg)'),
                    ),
                  if (reason == 'dimensions_exceeded')
                    TextField(
                      controller: dimensions,
                      decoration: const InputDecoration(
                          labelText: 'Observed dimensions'),
                    ),
                  if (reason == 'dimensions_exceeded' ||
                      reason == 'item_differs_from_booking') ...[
                    const SizedBox(height: 12),
                    DropdownButtonFormField<String>(
                      initialValue: observedVehicleType,
                      decoration: const InputDecoration(
                          labelText: 'Vehicle now required'),
                      items: const [
                        DropdownMenuItem(value: 'bike', child: Text('Bike')),
                        DropdownMenuItem(value: 'car', child: Text('Car')),
                        DropdownMenuItem(value: 'van', child: Text('Van')),
                      ],
                      onChanged: (value) =>
                          setDialogState(() => observedVehicleType = value),
                    ),
                  ],
                  if (reason == 'item_differs_from_booking' ||
                      reason == 'additional_undeclared_items')
                    TextField(
                      controller: description,
                      decoration: const InputDecoration(
                          labelText: 'What is actually present?'),
                    ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: notes,
                    maxLines: 2,
                    decoration:
                        const InputDecoration(labelText: 'Optional note'),
                  ),
                  const SizedBox(height: 12),
                  OutlinedButton.icon(
                    onPressed: uploading
                        ? null
                        : () async {
                            final selected = await ImagePicker().pickMultiImage(
                              imageQuality: 75,
                              limit: 4,
                            );
                            setDialogState(() => photos
                              ..clear()
                              ..addAll(selected));
                          },
                    icon: const Icon(Icons.add_a_photo_outlined),
                    label: Text(photos.isEmpty
                        ? 'Add evidence photo'
                        : '${photos.length} photo(s) selected'),
                  ),
                  if (error != null) ...[
                    const SizedBox(height: 8),
                    Text(error!,
                        style: const TextStyle(color: Colors.redAccent)),
                  ],
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed:
                  uploading ? null : () => Navigator.of(dialogContext).pop(),
              child: const Text('Back'),
            ),
            FilledButton(
              onPressed: uploading
                  ? null
                  : () async {
                      final observedWeight =
                          double.tryParse(weight.text.trim());
                      if (photos.isEmpty) {
                        setDialogState(
                            () => error = 'Add at least one evidence photo.');
                        return;
                      }
                      if (reason == 'weight_exceeded' &&
                          (observedWeight == null || observedWeight <= 0)) {
                        setDialogState(
                            () => error = 'Enter the observed weight.');
                        return;
                      }
                      if (reason == 'dimensions_exceeded' &&
                          observedVehicleType == null) {
                        setDialogState(() => error =
                            'Select the vehicle now required for this load.');
                        return;
                      }
                      setDialogState(() {
                        uploading = true;
                        error = null;
                      });
                      try {
                        final urls = <String>[];
                        for (var index = 0; index < photos.length; index++) {
                          final photo = photos[index];
                          final ref = FirebaseStorage.instance.ref(
                            'delivery-discrepancies/$requestId/${user.uid}/${DateTime.now().millisecondsSinceEpoch}-$index.jpg',
                          );
                          await ref.putData(await photo.readAsBytes(),
                              SettableMetadata(contentType: photo.mimeType));
                          urls.add(await ref.getDownloadURL());
                        }
                        if (!dialogContext.mounted) return;
                        Navigator.of(dialogContext).pop({
                          'requestId': requestId,
                          'reason': reason,
                          'evidencePhotos': urls,
                          if (observedWeight != null)
                            'observedWeightKg': observedWeight,
                          if (description.text.trim().isNotEmpty)
                            'observedDescription': description.text.trim(),
                          if (dimensions.text.trim().isNotEmpty)
                            'dimensions': dimensions.text.trim(),
                          if (observedVehicleType != null)
                            'observedVehicleType': observedVehicleType,
                          if (notes.text.trim().isNotEmpty)
                            'riderNotes': notes.text.trim(),
                        });
                      } catch (_) {
                        setDialogState(() {
                          uploading = false;
                          error = 'Evidence upload failed. Try again.';
                        });
                      }
                    },
              child: Text(uploading ? 'Uploading...' : 'Submit report'),
            ),
          ],
        ),
      ),
    );
    weight.dispose();
    description.dispose();
    dimensions.dispose();
    notes.dispose();
    return result;
  }

  void _openRiderChat(Map<String, dynamic> job) {
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    if (requestId.isEmpty) return;
    _riderChatSub?.cancel();
    _riderChatSub = FirebaseFirestore.instance
        .collection('chats')
        .doc(requestId)
        .collection('messages')
        .orderBy('createdAt')
        .limit(80)
        .snapshots()
        .listen(
      (snapshot) {
        if (!mounted) return;
        setState(() {
          _riderChatMessages
            ..clear()
            ..addAll(
              snapshot.docs.map((doc) {
                final data = doc.data();
                final role =
                    '${data['senderRole'] ?? data['senderType'] ?? ''}';
                return _ChatMessage(
                  fromMe: data['senderId'] == _riderUser?.uid,
                  text: '${data['messageText'] ?? data['message'] ?? ''}',
                  time: _formatMessageTime(
                    data['createdAt'],
                    data['timeStamp'],
                  ),
                  label: role == 'admin' || role == 'support'
                      ? 'CIRCUM Support'
                      : role == 'sender' || role == 'user'
                          ? 'Sender'
                          : 'Rider',
                );
              }).where((message) => message.text.trim().isNotEmpty),
            );
        });
      },
      onError: (_) {
        if (!mounted) return;
        setState(() => _jobMessage = 'Could not open this chat.');
      },
    );
    setState(() {
      _activeRiderChatJob = job;
      _riderChatOpen = true;
    });
  }

  Future<void> _sendRiderChatMessage() async {
    final user = _riderUser;
    final job = _activeRiderChatJob;
    final text = _riderChatInput.text.trim();
    if (user == null || job == null || text.isEmpty) return;
    final requestId = '${job['requestId'] ?? job['id'] ?? ''}'.trim();
    if (requestId.isEmpty) return;
    _riderChatInput.clear();
    try {
      await _ensureCircumFirebaseReady();
      final chatRef =
          FirebaseFirestore.instance.collection('chats').doc(requestId);
      await chatRef.collection('messages').add({
        'threadId': requestId,
        'bookingId': requestId,
        'requestId': requestId,
        'senderId': user.uid,
        'senderRole': 'rider',
        'senderType': 'rider',
        'messageText': text,
        'message': text,
        'readBy': [user.uid],
        'createdAt': FieldValue.serverTimestamp(),
        'timeStamp': DateTime.now().toIso8601String(),
      });
      await chatRef.set({
        'threadId': requestId,
        'bookingId': requestId,
        'requestId': requestId,
        'participants': FieldValue.arrayUnion([user.uid, 'circum-support']),
        'lastMessage': text,
        'lastMessageTimestamp': FieldValue.serverTimestamp(),
        'unreadBy': FieldValue.arrayUnion(['sender', 'admin']),
        'updatedAt': FieldValue.serverTimestamp(),
        'source': 'circum-web',
      }, SetOptions(merge: true));
    } catch (_) {
      if (!mounted) return;
      setState(() => _jobMessage = 'Message could not be sent.');
    }
  }

  String _formatMessageTime(dynamic timestamp, dynamic fallback) {
    DateTime? date;
    if (timestamp is Timestamp) date = timestamp.toDate();
    if (date == null && fallback is String) {
      date = DateTime.tryParse(fallback);
    }
    if (date == null) return 'Now';
    final hour = date.hour.toString().padLeft(2, '0');
    final minute = date.minute.toString().padLeft(2, '0');
    return '$hour:$minute';
  }

  Future<void> _signOutRider() async {
    await _earningsSub?.cancel();
    await _rothWalletSub?.cancel();
    await _performanceSub?.cancel();
    await _ratingSub?.cancel();
    await _availableJobsSub?.cancel();
    await _acceptedJobsSub?.cancel();
    await _completedJobsSub?.cancel();
    await _riderChatSub?.cancel();
    await FirebaseAuth.instance.signOut();
    if (!mounted) return;
    setState(() {
      _riderUser = null;
      _riderProfile = null;
      _earnings = _RiderEarningsSnapshot.empty();
      _performance = DriverPerformanceMetric.empty('web-rider');
      _recentRatings = const [];
      _availableJobs = const [];
      _acceptedJobs = const [];
      _completedJobs = const [];
      _availableRoles = const {};
      _roleChoiceConfirmed = false;
      _authMessage = 'Signed out.';
      _riderChatOpen = false;
      _activeRiderChatJob = null;
      _riderChatMessages.clear();
    });
  }

  bool get _isRiderStripeReturnRoute => Uri.base.path == '/rider/stripe/return';

  bool get _isRiderStripeRefreshRoute =>
      Uri.base.path == '/rider/stripe/refresh';

  Future<void> _handleRiderStripeRedirect() async {
    if (_isRiderStripeRefreshRoute) {
      await _startStripePayoutSetup();
      return;
    }
    if (!_isRiderStripeReturnRoute) return;
    setState(() {
      _riderTab = _RiderPortalTab.earnings;
      _withdrawMessage = 'Checking your Stripe payout setup...';
    });
    await _syncStripePayoutStatus();
  }

  bool get _riderStripePayoutReady {
    final profile = _riderProfile;
    if (profile == null) return false;
    return '${profile['stripeAccountId'] ?? profile['stripeConnectAccountId'] ?? ''}'
            .trim()
            .isNotEmpty &&
        (profile['stripeStatus'] == 'payouts_enabled' ||
            (profile['stripePayoutsEnabled'] == true &&
                (profile['stripeDetailsSubmitted'] == true ||
                    profile['stripeOnboardingStatus'] == 'complete' ||
                    profile['onboardingComplete'] == true))) &&
        profile['payoutPaused'] != true;
  }

  String? _riderPayoutBlockedReason({double? requestedAmount}) {
    final user = _riderUser;
    final profile = _riderProfile;
    if (user == null) return 'Sign in before requesting a payout.';
    if (profile?['isFrozen'] == true ||
        profile?['payoutPaused'] == true ||
        '${profile?['riderStatus'] ?? profile?['driverStatus'] ?? ''}' ==
            'frozen') {
      return 'Account frozen.';
    }
    final stripeStatus = '${profile?['stripeStatus'] ?? ''}';
    final accountId =
        '${profile?['stripeAccountId'] ?? profile?['stripeConnectAccountId'] ?? ''}'
            .trim();
    if (accountId.isEmpty || stripeStatus == 'not_started') {
      return 'Set up Stripe payouts first.';
    }
    if (stripeStatus == 'action_required' ||
        stripeStatus == 'restricted' ||
        stripeStatus == 'disabled') {
      return 'Stripe action required.';
    }
    if (!_riderStripePayoutReady) {
      return 'Stripe action required.';
    }
    if (!RiderOnboardingPolicy.isApproved(
      email: user.email,
      profile: profile,
      verifiedSuperAdmin: _superAdminRiderBypass,
    )) {
      return 'Admin approval required.';
    }
    if (_earnings.availableBalance <= 0) return 'No available balance.';
    if (requestedAmount != null &&
        requestedAmount > _earnings.availableBalance) {
      return 'The withdrawal amount is higher than your available balance.';
    }
    return null;
  }

  Future<void> _startStripePayoutSetup() async {
    final user = _riderUser;
    if (user == null) {
      setState(() => _withdrawMessage = 'Sign in before setting up payouts.');
      return;
    }
    setState(() => _withdrawMessage = 'Opening Stripe payout setup...');
    try {
      await _ensureCircumFirebaseReady();
      final result = await FirebaseFunctions.instanceFor(region: 'us-central1')
          .httpsCallable('createStripeOnboardingLink')
          .call({
        'riderId': user.uid,
        'returnUrl': '${Uri.base.origin}/rider/stripe/return',
        'refreshUrl': '${Uri.base.origin}/rider/stripe/refresh',
      });
      final data = (result.data as Map?)?.cast<String, dynamic>() ??
          const <String, dynamic>{};
      final url = Uri.tryParse('${data['url'] ?? ''}');
      if (url == null) {
        throw StateError('Stripe onboarding URL missing.');
      }
      await launchUrl(url, webOnlyWindowName: '_self');
    } on FirebaseFunctionsException catch (error) {
      if (!mounted) return;
      setState(
        () => _withdrawMessage =
            error.message ?? 'Stripe payout setup could not be started.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(
        () => _withdrawMessage =
            'Stripe payout setup could not be started. Please try again.',
      );
    }
  }

  Future<void> _syncStripePayoutStatus() async {
    final user = _riderUser;
    if (user == null) return;
    setState(() => _withdrawMessage = 'Checking Stripe payout status...');
    try {
      await _ensureCircumFirebaseReady();
      await FirebaseFunctions.instanceFor(region: 'us-central1')
          .httpsCallable('syncStripeConnectStatus')
          .call({'riderId': user.uid});
      final refreshed = await _loadRiderProfile(user.uid);
      if (!mounted) return;
      setState(
        () {
          _riderProfile = refreshed;
          _withdrawMessage =
              'Payout status refreshed. Stripe fees may apply to withdrawals.';
        },
      );
    } on FirebaseFunctionsException catch (error) {
      if (!mounted) return;
      setState(
        () => _withdrawMessage =
            error.message ?? 'We could not refresh your payout status.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(
        () => _withdrawMessage =
            'We could not refresh your payout status. Please try again.',
      );
    }
  }

  Future<void> _requestWithdrawal() async {
    final user = _riderUser;
    if (_withdrawSubmitting || user == null) {
      setState(() => _withdrawMessage = 'Sign in before requesting a payout.');
      return;
    }
    final amount = double.tryParse(_withdrawAmount.text.trim()) ?? 0;
    if (amount <= 0) {
      setState(
        () => _withdrawMessage = 'Enter a payout amount first.',
      );
      return;
    }
    final blockedReason = _riderPayoutBlockedReason(requestedAmount: amount);
    if (blockedReason != null) {
      setState(() => _withdrawMessage = blockedReason);
      return;
    }

    setState(() {
      _withdrawSubmitting = true;
      _withdrawMessage = 'Sending withdrawal request...';
    });

    try {
      await _ensureCircumFirebaseReady();
      final db = FirebaseFirestore.instance;
      final pending = await db
          .collection('payoutRequests')
          .where('riderId', isEqualTo: user.uid)
          .where('status', whereIn: ['requested', 'approved', 'pending'])
          .limit(1)
          .get();
      if (pending.docs.isNotEmpty) {
        if (!mounted) return;
        setState(
          () => _withdrawMessage = 'Payout already pending.',
        );
        return;
      }
      final requestRef = db.collection('payoutRequests').doc();
      final batch = db.batch();
      batch.set(requestRef, {
        'requestId': requestRef.id,
        'riderId': user.uid,
        'riderEmail': user.email,
        'amount': amount,
        'stripeAccountId': _riderProfile?['stripeAccountId'] ??
            _riderProfile?['stripeConnectAccountId'],
        'paymentProvider': 'stripe_connect_express',
        'feePayer': 'rider',
        'payoutFeePayer': 'rider',
        'status': 'requested',
        'notes': '',
        'auditTrail': [
          {
            'type': 'withdrawal_requested',
            'riderId': user.uid,
            'amount': amount,
            'status': 'requested',
            'source': 'circum-web',
            'paymentProvider': 'stripe_connect_express',
            'payoutFeePayer': 'rider',
            'createdAt': Timestamp.now(),
          },
        ],
        'source': 'circum-web',
        'requestedAt': FieldValue.serverTimestamp(),
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      batch.set(
          db.collection('riderEarnings').doc(user.uid),
          {
            'pendingWithdrawal': FieldValue.increment(amount),
            'updatedAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true));
      await batch.commit();
      if (!mounted) return;
      setState(
        () => _withdrawMessage =
            'Payout request sent. Circum will release it through Stripe Connect.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(
        () => _withdrawMessage = 'We could not send the request. Try again.',
      );
    } finally {
      if (mounted) setState(() => _withdrawSubmitting = false);
    }
  }

  Future<void> _uploadRiderDocument() async {
    final user = _riderUser;
    if (_documentSubmitting || user == null) {
      setState(() => _documentMessage = 'Sign in before uploading documents.');
      return;
    }

    try {
      final picked = await ImagePicker().pickImage(source: ImageSource.gallery);
      if (picked == null) return;

      setState(() {
        _documentSubmitting = true;
        _documentMessage = 'Uploading document...';
      });

      await _ensureCircumFirebaseReady();
      final bytes = await picked.readAsBytes();
      final safeName = picked.name.replaceAll(RegExp(r'[^A-Za-z0-9._-]'), '_');
      final path =
          'rider_documents/${user.uid}/${DateTime.now().millisecondsSinceEpoch}_$safeName';
      final storageRef = FirebaseStorage.instance.ref(path);
      await storageRef.putData(bytes);
      final downloadUrl = await storageRef.getDownloadURL();

      final documentRef =
          FirebaseFirestore.instance.collection('riderDocuments').doc();
      final documentType = _riderDocumentType(_documentType.text);
      await documentRef.set({
        'documentId': documentRef.id,
        'riderId': user.uid,
        'riderEmail': user.email,
        'type': documentType,
        'notes': _documentNotes.text.trim(),
        'fileName': picked.name,
        'storagePath': path,
        'downloadUrl': downloadUrl,
        'fileUrl': downloadUrl,
        'uploadedAt': FieldValue.serverTimestamp(),
        'status': 'pending',
        'verificationStatus': 'pending',
        'source': 'circum-web',
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      await FirebaseFirestore.instance
          .collection('riderProfiles')
          .doc(user.uid)
          .update({
        'verificationStatus': 'pending',
        'verificationDocuments.$documentType': {
          'type': documentType,
          'fileUrl': downloadUrl,
          'uploadedAt': FieldValue.serverTimestamp(),
          'status': 'pending',
        },
        'lastDocumentUploadedAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      _riderProfile = await _loadRiderProfile(user.uid);
      if (!mounted) return;
      setState(
        () => _documentMessage =
            'Document uploaded. Circum will review it before approval.',
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _documentMessage = 'Upload failed. Please try again.');
    } finally {
      if (mounted) setState(() => _documentSubmitting = false);
    }
  }

  String _riderDocumentType(String input) {
    final normalized = input.trim().toLowerCase();
    if (normalized.contains('licence') || normalized.contains('license')) {
      return 'driving_licence';
    }
    if (normalized.contains('address')) return 'proof_of_address';
    if (normalized.contains('insurance')) return 'vehicle_insurance';
    if (normalized.contains('right') && normalized.contains('work')) {
      return 'right_to_work';
    }
    return normalized.replaceAll(RegExp(r'[^a-z0-9]+'), '_');
  }

  String _friendlyAuthMessage(FirebaseAuthException error) {
    return switch (error.code) {
      'email-already-in-use' => 'That email already has a rider account.',
      'user-not-found' => 'No rider account found for that email.',
      'wrong-password' ||
      'invalid-credential' =>
        'The sign-in details are not right.',
      'weak-password' => 'Use a stronger password.',
      _ => 'We could not sign you in. Please check the details.',
    };
  }

  Future<void> _submit() async {
    if (_submitting) return;
    if (_fullName.text.trim().isEmpty ||
        _phone.text.trim().isEmpty ||
        _vehicle.text.trim().isEmpty ||
        _plateNumber.text.trim().isEmpty) {
      setState(() {
        _message = 'Add your name, phone, vehicle type, and registration.';
      });
      return;
    }
    if (!_rightToWork || !_sealedPackageConsent) {
      setState(() {
        _message =
            'Accept the rider terms and confirm your details are accurate.';
      });
      return;
    }

    final now = DateTime.now();
    final id = 'RWEB-${now.millisecondsSinceEpoch.toString().substring(6)}';
    setState(() {
      _submitting = true;
      _message = 'Sending your rider application...';
    });

    try {
      await _ensureCircumFirebaseReady();
      final db = FirebaseFirestore.instance;
      final batch = db.batch();
      final application = {
        'id': id,
        'riderId': _riderUser?.uid,
        'fullName': _fullName.text.trim(),
        'phoneNumber': _phone.text.trim(),
        'email': _email.text.trim(),
        'postcode': _postcode.text.trim(),
        'vehicleType': _vehicle.text.trim(),
        'vehicleMakeModel': _vehicleMakeModel.text.trim(),
        'vehicleColour': _vehicleColour.text.trim(),
        'vehicleRegistration': _plateNumber.text.trim(),
        'plateNumber': _plateNumber.text.trim(),
        'vehicle': DriverVehicle(
          type: _vehicle.text.trim(),
          makeModel: _vehicleMakeModel.text.trim(),
          colour: _vehicleColour.text.trim(),
          plateNumber: _plateNumber.text.trim(),
        ).toJson(),
        'availability': _availability.text.trim(),
        'notes': _notes.text.trim(),
        'rightToWorkConfirmed': _rightToWork,
        'sealedPackageConsent': _sealedPackageConsent,
        'status': 'submitted',
        'source': 'circum-web',
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      };
      batch.set(db.collection('riderApplications').doc(id), application);
      if (_riderUser != null) {
        batch.set(
          db.collection('riderProfiles').doc(_riderUser!.uid),
          {
            'fullName': _fullName.text.trim(),
            'email': _riderUser!.email ?? _email.text.trim(),
            'phoneNumber': _phone.text.trim(),
            'vehicleType': _vehicle.text.trim(),
            'vehicleMakeModel': _vehicleMakeModel.text.trim(),
            'vehicleColour': _vehicleColour.text.trim(),
            'vehicleRegistration': _plateNumber.text.trim(),
            'plateNumber': _plateNumber.text.trim(),
            'vehicle': DriverVehicle(
              type: _vehicle.text.trim(),
              makeModel: _vehicleMakeModel.text.trim(),
              colour: _vehicleColour.text.trim(),
              plateNumber: _plateNumber.text.trim(),
            ).toJson(),
            'onboardingStatus': 'submitted',
            'approvalStatus': 'pending',
            'verificationStatus': 'pending',
            'driverStatus': 'pending',
            'riderRank': 'agent',
            'role': 'rider',
            'roles': ['rider'],
            'onboardingSubmittedAt': FieldValue.serverTimestamp(),
            'termsAcceptedAt': FieldValue.serverTimestamp(),
            'updatedAt': FieldValue.serverTimestamp(),
          },
          SetOptions(merge: true),
        );
      }
      batch.set(db.collection('riderOnboardingEvents').doc(), {
        'applicationId': id,
        'riderId': _riderUser?.uid,
        'type': 'rider_application_submitted',
        'status': 'submitted',
        'source': 'circum-web',
        'createdAt': FieldValue.serverTimestamp(),
      });
      await batch.commit();
      if (_riderUser != null) {
        _riderProfile = await _loadRiderProfile(_riderUser!.uid);
      }
      if (!mounted) return;
      setState(() {
        _applicationId = id;
        _message =
            'Thanks. Your rider application has been sent to the Circum team.';
      });
    } catch (error) {
      _logRiderFirestoreError(
        error,
        path:
            'riderApplications/$id + riderProfiles/${_riderUser?.uid ?? 'unknown'} + riderOnboardingEvents',
        riderDocumentId: _riderUser?.uid,
      );
      if (!mounted) return;
      setState(() {
        _message =
            'We could not send the application just now. Please try again.';
      });
    } finally {
      if (mounted) setState(() => _submitting = false);
    }
  }

