          ),
          const SizedBox(height: 10),
          _InputBox(
            colors: colors,
            controller: _documentType,
            hint: 'Document type',
          ),
          const SizedBox(height: 10),
          _InputBox(
            colors: colors,
            controller: _documentNotes,
            hint: 'Notes for review',
            maxLines: 2,
          ),
          if (_documentMessage != null) ...[
            const SizedBox(height: 8),
            Text(_documentMessage!, style: TextStyle(color: colors.text)),
          ],
