class _RiderApprovalStatusPanel extends StatelessWidget {
  final _CircumColors colors;
  final String status;
  final Map<String, dynamic> profile;

  const _RiderApprovalStatusPanel({
    required this.colors,
    required this.status,
    required this.profile,
  });

  @override
  Widget build(BuildContext context) {
    final normalized = status.toLowerCase();
    final title = switch (normalized) {
      'rejected' => 'Application needs attention',
      'suspended' => 'Rider account suspended',
      _ => 'Application submitted',
    };
    final body = switch (normalized) {
      'rejected' =>
        'Circum could not approve this rider profile yet. Check the note below and contact support if you need help.',
      'suspended' =>
        'This rider account cannot accept jobs right now. Contact Circum support for the next step.',
      _ =>
        'Your rider application has been received and is awaiting review. We’ll notify you once you’re approved.',
    };
    final note = [
      profile['adminMessage'],
      profile['approvalNote'],
      profile['rejectionReason'],
      profile['accountNote'],
    ]
        .where((value) => '${value ?? ''}'.trim().isNotEmpty)
        .map((value) => '$value'.trim())
        .join('\n');

    return _GlassPanel(
      colors: colors,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                normalized == 'suspended'
                    ? Icons.block
                    : normalized == 'rejected'
                        ? Icons.report_problem_outlined
                        : Icons.pending_actions,
                color: colors.text,
              ),
              const SizedBox(width: 10),
              Expanded(
                child: _SectionTitle(colors: colors, title: title),
              ),
              _HealthChip(
                label: normalized == 'pending' || normalized == 'submitted'
                    ? 'Pending approval'
                    : _displayStatusLabel(normalized),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Text(
            body,
            style: TextStyle(
              color: colors.mutedText,
              fontWeight: FontWeight.w700,
              height: 1.4,
            ),
          ),
          const SizedBox(height: 14),
          _RiderChecklistRow(
            colors: colors,
            icon: Icons.person_outline,
            label: 'Rider',
            value: '${profile['fullName'] ?? profile['email'] ?? 'Signed in'}',
          ),
          _RiderChecklistRow(
            colors: colors,
            icon: Icons.directions_bike,
            label: 'Vehicle',
            value:
                '${profile['vehicleType'] ?? 'Vehicle'} ${profile['vehicleRegistration'] ?? profile['plateNumber'] ?? ''}'
                    .trim(),
          ),
          _RiderChecklistRow(
            colors: colors,
            icon: Icons.verified_user_outlined,
            label: 'Approval status',
            value: normalized == 'pending' || normalized == 'submitted'
                ? 'Pending approval'
                : _displayStatusLabel(normalized),
          ),
          if (note.isNotEmpty) ...[
            const SizedBox(height: 12),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: const Color(0xff0f172a),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: const Color(0xff26334d)),
