  static String _money(double value) => '£${value.toStringAsFixed(2)}';

  static double _estimatedStripePayoutFee(double gross) {
    if (gross <= 0) return 0;
    final grossPence = (gross * 100).round();
    final percentagePence = (grossPence * 0.015).ceil();
    final feePence = percentagePence + 20;
    return feePence / 100;
  }

  static double _estimatedNetPayout(double gross) {
    final fee = _estimatedStripePayoutFee(gross);
    final net = gross - fee;
    return net > 0 ? double.parse(net.toStringAsFixed(2)) : 0;
  }

  static bool _canRequestWithdrawal({
    required String amountText,
    required double availableBalance,
    required Map<String, dynamic>? riderProfile,
  }) {
    final amount = double.tryParse(amountText.trim()) ?? 0;
    return amount > 0 &&
        amount <= availableBalance &&
        availableBalance > 0 &&
        _stripePayoutReady(riderProfile) &&
        RiderOnboardingPolicy.isApproved(email: null, profile: riderProfile) &&
        riderProfile?['payoutPaused'] != true &&
        riderProfile?['isFrozen'] != true &&
        '${riderProfile?['riderStatus'] ?? riderProfile?['driverStatus'] ?? ''}' !=
            'frozen';
  }

  static bool _stripePayoutReady(Map<String, dynamic>? profile) {
    if (profile == null) return false;
    return '${profile['stripeAccountId'] ?? profile['stripeConnectAccountId'] ?? ''}'
            .trim()
            .isNotEmpty &&
        (profile['stripeStatus'] == 'payouts_enabled' ||
            (profile['stripePayoutsEnabled'] == true &&
                (profile['stripeDetailsSubmitted'] == true ||
                    profile['stripeOnboardingStatus'] == 'complete' ||
                    profile['onboardingComplete'] == true))) &&
        profile['payoutPaused'] != true;
  }
}

class _RiderPayoutStatusPanel extends StatelessWidget {
  final _CircumColors colors;
  final Map<String, dynamic>? profile;
  final VoidCallback onSetupPayouts;
  final VoidCallback onSyncPayouts;

  const _RiderPayoutStatusPanel({
    required this.colors,
    required this.profile,
    required this.onSetupPayouts,
    required this.onSyncPayouts,
  });

  @override
  Widget build(BuildContext context) {
    final accountId =
        '${profile?['stripeAccountId'] ?? profile?['stripeConnectAccountId'] ?? ''}'
            .trim();
    final hasAccount = accountId.isNotEmpty;
    final stripeStatus = '${profile?['stripeStatus'] ?? ''}';
    final onboardingComplete = stripeStatus == 'payouts_enabled' ||
        stripeStatus == 'connected' ||
        profile?['stripeOnboardingStatus'] == 'complete' ||
        profile?['stripeDetailsSubmitted'] == true ||
        profile?['onboardingComplete'] == true;
    final payoutsEnabled = stripeStatus == 'payouts_enabled' ||
        profile?['stripePayoutsEnabled'] == true ||
        profile?['payoutsEnabled'] == true;
    final payoutPaused = profile?['payoutPaused'] == true;
    final requirements = (profile?['stripeRequirementsDue'] as List?) ??
        (profile?['stripeRequirementsPastDue'] as List?) ??
        const [];
    final ready = _RiderWorkspace._stripePayoutReady(profile);
    final needsAction = stripeStatus == 'action_required' ||
        stripeStatus == 'restricted' ||
        stripeStatus == 'disabled';
    final onboarding = stripeStatus == 'onboarding';
    final title = ready || (hasAccount && onboardingComplete && payoutsEnabled)
        ? 'Stripe Connected'
        : payoutPaused
            ? 'Payouts paused'
            : !hasAccount
                ? 'Set up payouts with Stripe'
                : needsAction
                    ? 'Action Required'
                    : onboarding
                        ? 'Continue Stripe Verification'
                        : 'Action Required';
    final subtitle = ready ||
            (hasAccount && onboardingComplete && payoutsEnabled)
        ? 'Payouts Enabled. Bank account linked. You can request payouts after Circum approval and available earnings checks.'
        : !hasAccount
            ? 'Stripe securely collects your bank and identity details. Circum does not store bank account numbers or sort codes.'
            : needsAction || requirements.isNotEmpty
                ? 'Stripe needs more information before payouts can be enabled.'
                : 'Continue Stripe onboarding, then refresh your payout status.';
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: colors.panel.withValues(alpha: 0.9),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: colors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                ready || (hasAccount && onboardingComplete && payoutsEnabled)
                    ? Icons.verified_rounded
                    : Icons.account_balance_wallet,
                color: colors.text,
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  title,
                  style: TextStyle(
                    color: colors.text,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          if (ready ||
              (hasAccount && onboardingComplete && payoutsEnabled)) ...[
            _RiderChecklistRow(
              colors: colors,
              icon: Icons.check_circle,
              label: 'Payouts Enabled',
              value: 'Your Stripe Express payout account is connected.',
            ),
            const SizedBox(height: 8),
            _RiderChecklistRow(
              colors: colors,
              icon: Icons.account_balance,
              label: 'Bank account linked',
              value:
                  'Stripe stores and manages your bank details securely. Circum does not store them.',
            ),
            const SizedBox(height: 8),
          ],
          Text(
            subtitle,
            style: TextStyle(
              color: colors.mutedText,
              height: 1.35,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            'Admin setup: Stripe Dashboard > Connect settings > set payout/fee payer to connected account/rider where available.',
            style: TextStyle(
              color: colors.mutedText.withValues(alpha: 0.88),
              height: 1.35,
              fontSize: 12,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 10,
            runSpacing: 10,
            children: [
              OutlinedButton.icon(
                onPressed: onSetupPayouts,
                icon: const Icon(Icons.open_in_new),
                label: Text(!hasAccount
                    ? 'Set up payouts with Stripe'
                    : ready || (onboardingComplete && payoutsEnabled)
                        ? 'Manage Stripe Account'
                        : 'Continue Stripe Verification'),
              ),
              OutlinedButton.icon(
                onPressed: onSyncPayouts,
                icon: const Icon(Icons.sync),
                label: const Text('Refresh status'),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

class _RiderDocumentProgress extends StatelessWidget {
  final _CircumColors colors;
  final Map<String, dynamic>? profile;

  const _RiderDocumentProgress({required this.colors, required this.profile});

  @override
  Widget build(BuildContext context) {
    final documents =
        (profile?['verificationDocuments'] as Map?)?.cast<String, dynamic>() ??
            (profile?['documents'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
    var uploaded = 0;
    for (final type in _RiderDocumentStatusList.documentTypes) {
      final key = type.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_');
      final value =
          documents[key] ?? documents[type] ?? documents[type.toLowerCase()];
      if (value == true || value is Map) uploaded++;
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          '$uploaded of ${_RiderDocumentStatusList.documentTypes.length} documents uploaded',
          style: TextStyle(color: colors.text, fontWeight: FontWeight.w900),
        ),
        const SizedBox(height: 8),
        LinearProgressIndicator(
          value: uploaded / _RiderDocumentStatusList.documentTypes.length,
          minHeight: 8,
          borderRadius: BorderRadius.circular(999),
          backgroundColor: colors.field,
          color: colors.adminAccent,
        ),
      ],
    );
  }
}

