class _DriverJobCard extends StatelessWidget {
  final _CircumColors colors;
  final Map<String, dynamic> job;
  final VoidCallback onAccept;
  final void Function(String status)? onUpdateStatus;
  final VoidCallback onReportDiscrepancy;
  final VoidCallback onOpenChat;
  final bool completed;
  final bool showContactDetails;

  const _DriverJobCard({
    required this.colors,
    required this.job,
    required this.onAccept,
    this.onUpdateStatus,
    required this.onReportDiscrepancy,
    required this.onOpenChat,
    this.completed = false,
    this.showContactDetails = true,
  });

  @override
  Widget build(BuildContext context) {
    final summary =
        (job['driverJobSummary'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
    final pricing =
        (job['pricingBreakdown'] as Map?)?.cast<String, dynamic>() ??
            const <String, dynamic>{};
    final customerWeight = _num(
      job['customerDeclaredWeight'] ?? job['senderEnteredWeightKg'],
    );
    final irisWeight = _num(
      job['irisEstimatedWeight'] ?? job['irisEstimatedWeightKg'],
    );
    final chargeableWeight = _num(
      job['finalWeightUsed'] ??
          job['finalChargeableWeight'] ??
          job['confirmedWeightKg'],
    );
    final category =
        '${job['weightCategory'] ?? job['confirmedWeightBand'] ?? summary['confirmedWeightBand'] ?? 'Parcel'}';
    final confidence =
        '${job['irisConfidenceScore'] ?? job['irisWeightConfidence'] ?? 'unknown'}';
    final weightSource =
        '${job['irisWeightSource'] ?? summary['irisWeightSource'] ?? 'unknown'}';
    final distance = _num(summary['estimatedDistanceMiles']);
    final fare = _num(summary['totalFare'] ?? job['fare'] ?? job['price']);
    final payout = _num(summary['driverPayout'] ?? job['driverPayout']);
    final riderBaseShare = _num(
      summary['riderBaseShare'] ??
          job['riderBaseShare'] ??
          pricing['riderBaseShare'],
    );
    final riderLabourShare = _num(
      summary['riderLabourShare'] ??
          job['riderLabourShare'] ??
          pricing['riderLabourShare'],
    );
    final assistedFee = _num(
      summary['assistedFee'] ?? job['assistedFee'] ?? pricing['assistedFee'],
    );
    final heavyDutyFee = _num(
      summary['heavyDutyFee'] ?? job['heavyDutyFee'] ?? pricing['heavyDutyFee'],
    );
    final twoPersonFee = _num(
      summary['twoPersonFee'] ?? job['twoPersonFee'] ?? pricing['twoPersonFee'],
    );
    final tip = _num(
      job['tipAmount'] ?? job['riderTip'] ?? summary['tipAmount'],
    );
    final vehicle =
        '${summary['vehicleType'] ?? job['vehicleType'] ?? 'Vehicle'}';
    final serviceLevel =
        '${job['selectedServiceLevel'] ?? job['serviceLevel'] ?? summary['serviceLevel'] ?? 'standard'}';
    final movementService = _riderMovementLabel(job);
    final vanguardEnabled = job['vanguardEnabled'] == true ||
        summary['vanguardEnabled'] == true ||
        ((job['vanguardProtection'] as Map?)?['enabled'] == true);
    final duration = _num(
      summary['estimatedDurationMinutes'] ??
          job['estimatedDurationMinutes'] ??
          job['etaMinutes'],
    );
    final dimensions =
        '${summary['packageDimensions'] ?? job['packageDimensions'] ?? job['dimensions'] ?? ''}'
            .trim();
    final warnings = _warnings(chargeableWeight, category, job);
    final senderName = _contactValue(
      job,
      summary,
      'senderName',
      nestedKey: 'senderDetails',
      nestedName: 'name',
    );
    final senderPhone = _contactValue(
      job,
      summary,
      'senderPhone',
      nestedKey: 'senderDetails',
      nestedName: 'phone',
    );
    final receiverName = _contactValue(
      job,
      summary,
      'receiverName',
      nestedKey: 'receiverDetails',
      nestedName: 'name',
    );
    final receiverPhone = _contactValue(
      job,
      summary,
      'receiverPhone',
      nestedKey: 'receiverDetails',
      nestedName: 'phone',
    );
    final collectionName = _contactValue(
      job,
      summary,
      'collectionContactName',
      nestedKey: 'collectionContact',
      nestedName: 'name',
    );
    final collectionPhone = _contactValue(
      job,
      summary,
      'collectionContactPhone',
      nestedKey: 'collectionContact',
      nestedName: 'phone',
    );
    final collectionDifferent = (job['collectionContactDifferent'] == true ||
        summary['collectionContactDifferent'] == true ||
        ((job['collectionContact'] as Map?)?['differentFromSender'] == true));
    final jobStatus = '${job['status'] ?? ''}'.toLowerCase();
    final canReportDiscrepancy = const {
      'accepted',
      'rider_assigned',
      'en_route_to_pickup',
      'arrived_at_pickup',
      'rider_arrived_pickup',
    }.contains(jobStatus);

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: colors.panel,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: colors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  '${job['requestId'] ?? job['id'] ?? 'Delivery request'}',
                  style: TextStyle(
                    color: colors.text,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              if ('${job['selectedServiceLevel'] ?? job['serviceLevel'] ?? ''}'
                      .toLowerCase() ==
                  'express') ...[
                _HealthChip(label: 'Express'),
                const SizedBox(width: 8),
              ],
              if (vanguardEnabled) ...[
                _HealthChip(label: 'Vanguard'),
                const SizedBox(width: 8),
              ],
              if (assistedFee > 0) ...[
                _HealthChip(label: 'Assisted Delivery'),
                const SizedBox(width: 8),
              ],
              if (heavyDutyFee > 0) ...[
                _HealthChip(label: 'Heavy Duty'),
                const SizedBox(width: 8),
              ],
              if (twoPersonFee > 0) ...[
                _HealthChip(label: 'Two Person Required'),
                const SizedBox(width: 8),
              ],
              _HealthChip(label: vehicle),
            ],
          ),
          const SizedBox(height: 10),
          _JobInfoLine(
            colors: colors,
            icon: Icons.bolt,
            label: 'Service type',
            value: serviceLevel.toLowerCase() == 'express'
                ? '$movementService • Express priority'
                : movementService,
          ),
          if (assistedFee > 0 || heavyDutyFee > 0 || twoPersonFee > 0)
            _JobInfoLine(
              colors: colors,
              icon: Icons.handyman,
              label: 'Special handling earnings',
              value:
                  'Base ${_money(riderBaseShare)}${assistedFee > 0 ? ' • Assisted bonus ${_money(assistedFee * 0.80)}' : ''}${heavyDutyFee > 0 ? ' • Heavy Duty bonus ${_money(heavyDutyFee * 0.80)}' : ''}${twoPersonFee > 0 ? ' • Two Person bonus ${_money(twoPersonFee * 0.80)}' : ''} • Total ${_money(riderBaseShare + riderLabourShare)}',
            ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.schedule,
            label: 'Received',
            value: _jobReceivedText(job),
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.trip_origin,
            label: 'Pickup',
            value: '${summary['pickupDisplay'] ?? job['pickupAddress'] ?? ''}',
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.place,
            label: 'Drop-off',
            value:
                '${summary['dropoffDisplay'] ?? job['dropoffAddress'] ?? ''}',
          ),
          if (showContactDetails) ...[
            _JobInfoLine(
              colors: colors,
              icon: Icons.person,
              label: 'Sender',
              value:
                  '${senderName.isEmpty ? 'Not set' : senderName}${senderPhone.isEmpty ? '' : ' • $senderPhone'}',
            ),
            if (collectionDifferent)
              _JobInfoLine(
                colors: colors,
                icon: Icons.handshake_outlined,
                label: 'Collection contact',
                value:
                    '${collectionName.isEmpty ? 'Not set' : collectionName}${collectionPhone.isEmpty ? '' : ' • $collectionPhone'}',
              ),
            _JobInfoLine(
              colors: colors,
              icon: Icons.person_pin_circle,
              label: 'Receiver',
              value: receiverName.isEmpty
                  ? 'Receiver not provided'
                  : '$receiverName${receiverPhone.isEmpty ? '' : ' • $receiverPhone'}',
            ),
          ],
          _JobInfoLine(
            colors: colors,
            icon: Icons.route,
            label: 'Distance',
            value: distance > 0
                ? '${distance.toStringAsFixed(1)} miles'
                : 'Not set',
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.timer,
            label: 'ETA',
            value:
                duration > 0 ? '${duration.toStringAsFixed(0)} min' : 'Not set',
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.schedule,
            label: 'Delivery timing',
            value: _deliveryTimingLabel(summary, job),
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.inventory_2,
            label: 'Parcel',
            value:
                '${summary['packageType'] ?? job['packageType'] ?? 'Parcel'} - ${summary['packageDescription'] ?? job['packageDescription'] ?? ''}',
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.straighten,
            label: 'Dimensions',
            value: dimensions.isEmpty ? 'Not provided' : dimensions,
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.scale,
            label: 'Weight',
            value:
                'Customer ${_weight(customerWeight)} kg, Iris ${_weight(irisWeight)} kg, chargeable ${_weight(chargeableWeight)} kg',
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.fact_check,
            label: 'Checks',
            value:
                '$category, Iris confidence $confidence, source $weightSource',
          ),
          _JobInfoLine(
            colors: colors,
            icon: Icons.payments,
            label: 'Price',
            value:
                'Total ${_money(fare)} • distance ${_money(_num(pricing['distanceFare']))} • weight ${_money(_num(pricing['weightSurcharge']))} • payout ${_money(payout)}${tip > 0 ? ' • tip ${_money(tip)}' : ''}',
          ),
          if (warnings.isNotEmpty) ...[
            const SizedBox(height: 8),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: warnings
                  .map((warning) => _HealthChip(label: warning))
                  .toList(),
            ),
          ],
          if (vanguardEnabled) ...[
            const SizedBox(height: 8),
            _JobInfoLine(
              colors: colors,
              icon: Icons.security,
              label: 'Vanguard',
              value:
                  'PIN verification required at collection and final delivery.',
            ),
          ],
          if (_pickupWaitingVisible(job)) ...[
            const SizedBox(height: 12),
            _PickupWaitingPanel(
              colors: colors,
              job: job,
              onContactEstablished: () =>
                  onUpdateStatus?.call('sender_contact_established'),
              onNoContact: () => onUpdateStatus?.call('sender_no_contact'),
              onExtend: (minutes) =>
                  onUpdateStatus?.call('extend_wait_$minutes'),
              onNoShow: () => onUpdateStatus?.call('sender_no_show_pickup'),
              onContactSender: onOpenChat,
            ),
          ],
          const SizedBox(height: 12),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              if (completed)
                _HealthChip(label: 'Completed')
              else
                FilledButton.icon(
                  onPressed: onAccept,
                  icon: const Icon(Icons.check_circle),
                  label: const Text('Accept job'),
                ),
              OutlinedButton.icon(
                onPressed: onOpenChat,
                icon: const Icon(Icons.chat_bubble_outline),
                label: const Text('Messages'),
              ),
              if (onUpdateStatus != null && !completed) ...[
                if (!_pickupWaitingVisible(job))
                  OutlinedButton.icon(
                    onPressed: () => onUpdateStatus!('rider_arrived_pickup'),
                    icon: const Icon(Icons.pin_drop_outlined),
                    label: const Text("I've Arrived"),
                  ),
                OutlinedButton.icon(
                  onPressed: () => onUpdateStatus!('picked_up'),
                  icon: const Icon(Icons.inventory),
                  label: const Text('Verify pickup'),
                ),
                OutlinedButton.icon(
                  onPressed: () => onUpdateStatus!('in_transit'),
                  icon: const Icon(Icons.delivery_dining),
                  label: const Text('In transit'),
                ),
                OutlinedButton.icon(
                  onPressed: () => onUpdateStatus!('completed'),
                  icon: const Icon(Icons.flag_circle),
                  label: const Text('Complete'),
                ),
              ],
              if (!completed && canReportDiscrepancy) ...[
                OutlinedButton.icon(
                  onPressed: onReportDiscrepancy,
                  icon: const Icon(Icons.report_problem),
                  label: const Text('Report Load Discrepancy'),
                ),
              ],
            ],
          ),
        ],
      ),
    );
  }

  static String _deliveryTimingLabel(
    Map<String, dynamic> summary,
    Map<String, dynamic> job,
  ) {
    final type =
        '${summary['deliveryTimingType'] ?? job['deliveryTimingType'] ?? ''}'
            .toLowerCase();
    if (type == 'asap') return 'Immediate Delivery';
    if (type == 'today') {
      return 'Today Delivery · ${summary['scheduledPickupWindow'] ?? job['scheduledPickupWindow'] ?? 'Flexible'}';
    }
    return '${summary['scheduledPickupDate'] ?? job['scheduledPickupDate'] ?? 'Scheduled'} · ${summary['scheduledPickupWindow'] ?? job['scheduledPickupWindow'] ?? 'Flexible'}';
  }

  static double _num(Object? value) {
    if (value is num) return value.toDouble();
    return double.tryParse('$value') ?? 0;
  }

  static String _money(double value) => '£${value.toStringAsFixed(2)}';

  static String _weight(double value) => value <= 0
      ? 'not set'
      : value.toStringAsFixed(value == value.roundToDouble() ? 0 : 1);

  static bool _pickupWaitingVisible(Map<String, dynamic> job) {
    final status = '${job['status'] ?? ''}'.toLowerCase();
    return status == 'rider_arrived_pickup' ||
        status == 'arrived_at_pickup' ||
        job['pickupWaitStartedAt'] != null ||
        status == 'sender_no_show_pickup';
  }

  static String _contactValue(
    Map<String, dynamic> job,
    Map<String, dynamic> summary,
    String key, {
    required String nestedKey,
    required String nestedName,
  }) {
    final nested = (job[nestedKey] as Map?)?.cast<String, dynamic>();
    return '${summary[key] ?? job[key] ?? nested?[nestedName] ?? ''}'.trim();
  }

  static List<String> _warnings(
    double weightKg,
    String category,
    Map<String, dynamic> job,
  ) {
    final warnings = <String>[];
    if (weightKg > 20) {
      warnings.add('Two-person handling may be required');
    } else if (weightKg > 10) {
      warnings.add('Heavy parcel');
    }
    final lowerCategory = category.toLowerCase();
    final description =
        '${job['packageDescription'] ?? ''} ${job['packageType'] ?? ''}'
            .toLowerCase();
    if (lowerCategory.contains('large') ||
        description.contains('furniture') ||
        description.contains('piano') ||
        description.contains('tv')) {
      warnings.add('Large item');
    }
    if (job['weightReviewRequired'] == true ||
        job['weightVerificationRequired'] == true) {
      warnings.add('Check weight at pickup');
    }
    return warnings;
  }
}

class _PickupWaitingPanel extends StatefulWidget {
  final _CircumColors colors;
  final Map<String, dynamic> job;
  final VoidCallback? onContactEstablished;
  final VoidCallback? onNoContact;
  final ValueChanged<int>? onExtend;
  final VoidCallback? onNoShow;
  final VoidCallback? onContactSender;

  const _PickupWaitingPanel({
    required this.colors,
    required this.job,
    required this.onContactEstablished,
    required this.onNoContact,
    required this.onExtend,
    required this.onNoShow,
    required this.onContactSender,
  });

  @override
  State<_PickupWaitingPanel> createState() => _PickupWaitingPanelState();
}

class _PickupWaitingPanelState extends State<_PickupWaitingPanel> {
  late Timer _timer;

  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _timer.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final colors = widget.colors;
    final deadline = _date(widget.job['pickupWaitDeadlineAt']);
    final remaining =
        deadline == null ? Duration.zero : deadline.difference(DateTime.now());
    final remainingSeconds = remaining.inSeconds.clamp(0, 9999);
    final minutes = (remainingSeconds ~/ 60).toString().padLeft(2, '0');
    final seconds = (remainingSeconds % 60).toString().padLeft(2, '0');
    final contactEstablished = widget.job['senderContactEstablished'] == true;
    final noShow = '${widget.job['status'] ?? ''}' == 'sender_no_show_pickup';
    final canNoShow = !noShow && !contactEstablished && remainingSeconds == 0;
    final extended = widget.job['pickupWaitExtended'] == true;
    final extensionCharge =
        (widget.job['pickupWaitExtensionChargeGbp'] as num?)?.toDouble() ??
            (widget.job['pickupWaitExtensionCharge'] as num?)?.toDouble() ??
            0;
    final noShowCharge =
        (widget.job['pickupNoShowSurchargeGbp'] as num?)?.toDouble() ?? 0;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: colors.field,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: colors.adminAccent.withValues(alpha: 0.35)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.timer_outlined, color: colors.adminAccent, size: 20),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  noShow ? 'Sender no-show recorded' : 'Pickup waiting time',
                  style: TextStyle(
                    color: colors.text,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Text(
                noShow
                    ? '£${noShowCharge.toStringAsFixed(2)}'
                    : '$minutes:$seconds',
                style: TextStyle(
                  color: canNoShow ? colors.warning : colors.text,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            contactEstablished
                ? 'Contact established. You may extend waiting if needed.'
                : canNoShow
                    ? 'Free waiting has ended. You may mark Sender No Show if no contact was established.'
                    : 'Free waiting is active. Contact the sender and wait for the timer to finish before no-show.',
            style: TextStyle(
              color: colors.mutedText,
              fontWeight: FontWeight.w700,
              height: 1.35,
            ),
          ),
          if (extended && extensionCharge > 0) ...[
            const SizedBox(height: 6),
            Text(
              'Waiting extended by ${widget.job['pickupWaitExtensionMinutes'] ?? ''} minutes · £${extensionCharge.toStringAsFixed(2)} GBP',
              style: TextStyle(
                color: colors.text,
                fontWeight: FontWeight.w800,
              ),
            ),
          ],
          const SizedBox(height: 10),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              FilledButton.icon(
                onPressed: widget.onContactSender,
                icon: const Icon(Icons.chat_bubble_outline),
                label: const Text('Contact Sender'),
              ),
              OutlinedButton.icon(
                onPressed: widget.onContactEstablished,
                icon: const Icon(Icons.call),
                label: const Text('Contact established'),
              ),
              OutlinedButton.icon(
                onPressed: widget.onNoContact,
                icon: const Icon(Icons.phone_disabled_outlined),
                label: const Text('No contact'),
              ),
              for (final option in const [
                (5, 2),
                (10, 4),
                (15, 6),
              ])
                OutlinedButton(
                  onPressed: contactEstablished && !extended
                      ? () => widget.onExtend?.call(option.$1)
                      : null,
                  child: Text('+${option.$1} min · £${option.$2}.00'),
                ),
              FilledButton.icon(
                onPressed: canNoShow ? widget.onNoShow : null,
                icon: const Icon(Icons.person_off_outlined),
                label: const Text('Mark Sender No Show'),
              ),
            ],
          ),
        ],
      ),
    );
  }

  DateTime? _date(dynamic value) {
    if (value is Timestamp) return value.toDate();
    if (value is DateTime) return value;
    if (value is String) return DateTime.tryParse(value);
    return null;
  }
}

class _JobInfoLine extends StatelessWidget {
