  Future<void> _signInSenderWithProvider({
    required AuthProvider provider,
    required String method,
    required String startingMessage,
  }) async {
    if (_senderAuthBusy) return;
    setState(() {
      _senderAuthBusy = true;
      _senderProfileMessage = startingMessage;
    });
    try {
      await _ensureFirebaseReady();
      final credential = await FirebaseAuth.instance.signInWithPopup(provider);
      final user = credential.user;
      if (user == null) {
        throw FirebaseAuthException(code: 'provider-no-user');
      }
      if (!await _allowSenderUser(user)) {
        await FirebaseAuth.instance.signOut();
        if (!mounted) return;
        setState(
          () => _senderProfileMessage =
              'This account is not a sender account. Use the rider or admin sign-in instead.',
        );
        return;
      }
      await _mergeProviderSenderProfile(user, method);
      await _attachIncomingReferralIfPresent();
      _availableRoles = {CircumRole.sender};
      _attachSender(user);
      await _loadSenderDeliveries(user.uid);
      await _loadSenderBusinessAccounts(user.uid);
      _rememberLastLoginMethod(method, user.email ?? user.phoneNumber);
      if (!mounted) return;
      setState(() => _senderProfileMessage = 'Profile ready.');
    } on FirebaseAuthException catch (error) {
      if (!mounted) return;
      setState(
        () => _senderProfileMessage = _friendlyProviderAuthMessage(error),
      );
    } catch (_) {
      if (!mounted) return;
      setState(
        () => _senderProfileMessage =
            'Sign-in could not be completed. Please try again.',
      );
    } finally {
      if (mounted) setState(() => _senderAuthBusy = false);
    }
  }

  Future<void> _mergeProviderSenderProfile(User user, String method) async {
    final displayName = user.displayName?.trim() ?? '';
    final userRef =
        FirebaseFirestore.instance.collection('users').doc(user.uid);
    final existing = await userRef.get();
    await userRef.set({
      if (displayName.isNotEmpty) 'fullName': displayName,
      if (displayName.isNotEmpty) 'fullname': displayName,
      'email': user.email,
      'phoneNumber': user.phoneNumber,
      'photoURL': user.photoURL,
      'role': 'user',
      'roles': ['sender'],
      'userType': 'sender',
      'status': 'active',
      'authProvider': method,
      'verificationStatus': user.emailVerified ? 'verified' : 'unverified',
      'updatedAt': FieldValue.serverTimestamp(),
      'lastLoginAt': FieldValue.serverTimestamp(),
      'lastLoginMethod': method,
      if (!existing.exists) 'createdAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
  }

  void _rememberLastLoginMethod(String method, String? rawHint) {
    final hint = _maskedLoginHint(rawHint);
    html.window.localStorage['lastLoginMethod'] = method;
    if (hint != null) {
      html.window.localStorage['lastLoginHint'] = hint;
    }
  }

  static String? _maskedLoginHint(String? rawHint) {
    final value = rawHint?.trim();
    if (value == null || value.isEmpty) return null;
    if (value.contains('@')) {
      final parts = value.split('@');
      final local = parts.first;
      final domain = parts.length > 1 ? parts.sublist(1).join('@') : '';
      final visible = local.isEmpty ? 'a' : local.characters.first;
      return '$visible***@$domain';
    }
    final digits = value.replaceAll(RegExp(r'\D'), '');
    if (digits.length <= 4) return '••••';
    return '+${digits.substring(0, math.min(2, digits.length))}••••${digits.substring(digits.length - 4)}';
  }

  String _friendlyProviderAuthMessage(FirebaseAuthException error) {
    return switch (error.code) {
      'popup-closed-by-user' ||
      'cancelled-popup-request' =>
        'Sign-in was cancelled before it completed.',
      'popup-blocked' =>
        'Your browser blocked the sign-in window. Allow pop-ups for Circum and try again.',
      'operation-not-supported-in-this-environment' =>
        'This sign-in method is not supported in this browser.',
      'account-exists-with-different-credential' =>
        'This email already uses another sign-in method. Continue with your original method.',
      _ => _friendlySenderAuthMessage(error),
    };
  }

  Future<void> _sendSenderPasswordReset() async {
    final email = _senderEmail.text.trim();
    if (email.isEmpty) {
      setState(() => _senderProfileMessage = 'Enter your email address first.');
      return;
    }
    setState(() {
      _senderAuthBusy = true;
      _senderProfileMessage = 'Sending password reset email...';
    });
    try {
      await _ensureFirebaseReady();
      await FirebaseAuth.instance.sendPasswordResetEmail(email: email);
      if (!mounted) return;
      setState(
        () => _senderProfileMessage =
            'Password reset sent. Check your email and follow the secure link.',
      );
    } on FirebaseAuthException catch (error) {
      if (!mounted) return;
      setState(
        () => _senderProfileMessage = switch (error.code) {
          'invalid-email' => 'Enter a valid email address.',
          'user-not-found' => 'No Circum sender profile found for that email.',
          _ =>
            'We could not send the reset email. Check the address and try again.',
        },
      );
    } finally {
      if (mounted) setState(() => _senderAuthBusy = false);
    }
  }

  Future<UserCredential> _reauthenticateSender(String password) async {
    final user = _senderUser ?? FirebaseAuth.instance.currentUser;
    final email = user?.email;
    if (user == null || email == null || email.trim().isEmpty) {
      throw FirebaseAuthException(
        code: 'requires-recent-login',
        message: 'Sign in again before changing account security settings.',
      );
    }
    return user.reauthenticateWithCredential(
      EmailAuthProvider.credential(email: email, password: password),
    );
  }

  Future<void> _changeSenderPassword() async {
    if (_senderSecurityBusy) return;
    final current = _senderCurrentPassword.text.trim();
    final next = _senderNewPassword.text.trim();
    final confirm = _senderConfirmNewPassword.text.trim();
    if (current.isEmpty || next.length < 6 || next != confirm) {
      setState(
        () => _senderSecurityMessage =
            'Enter your current password and make sure the new passwords match.',
      );
      return;
    }
    setState(() {
      _senderSecurityBusy = true;
      _senderSecurityMessage = 'Updating password...';
    });
    try {
      await _ensureFirebaseReady();
      await _reauthenticateSender(current);
      await (_senderUser ?? FirebaseAuth.instance.currentUser)?.updatePassword(
        next,
      );
      _senderCurrentPassword.clear();
      _senderNewPassword.clear();
      _senderConfirmNewPassword.clear();
      if (!mounted) return;
      setState(() => _senderSecurityMessage = 'Password updated.');
    } on FirebaseAuthException catch (error) {
      if (!mounted) return;
      setState(
        () => _senderSecurityMessage = _friendlySenderAuthMessage(error),
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _senderSecurityMessage = 'Could not update password.');
    } finally {
      if (mounted) setState(() => _senderSecurityBusy = false);
    }
  }

  Future<void> _changeSenderEmail() async {
    if (_senderSecurityBusy) return;
    final nextEmail = _senderNewEmail.text.trim();
    final password = _senderEmailChangePassword.text.trim();
    if (nextEmail.isEmpty || !nextEmail.contains('@') || password.isEmpty) {
      setState(
        () => _senderSecurityMessage =
            'Enter the new email and your current password.',
      );
      return;
    }
    setState(() {
      _senderSecurityBusy = true;
      _senderSecurityMessage = 'Updating email...';
    });
    try {
      await _ensureFirebaseReady();
      await _reauthenticateSender(password);
      final user = _senderUser ?? FirebaseAuth.instance.currentUser;
      if (user == null) {
        throw FirebaseAuthException(code: 'requires-recent-login');
      }
      await user.verifyBeforeUpdateEmail(nextEmail);
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'pendingEmail': nextEmail,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      _senderNewEmail.clear();
      _senderEmailChangePassword.clear();
      if (!mounted) return;
      setState(
        () => _senderSecurityMessage =
            'Verification sent. Open the email link to confirm the new address.',
      );
    } on FirebaseAuthException catch (error) {
      if (!mounted) return;
      setState(
        () => _senderSecurityMessage = _friendlySenderAuthMessage(error),
      );
    } catch (_) {
      if (!mounted) return;
      setState(() => _senderSecurityMessage = 'Could not update email.');
    } finally {
      if (mounted) setState(() => _senderSecurityBusy = false);
    }
  }

  Future<bool> _allowSenderUser(User user) async {
    final roles = await _rolesForSenderUser(user);
    if (!mounted) return false;
    setState(() => _availableRoles = roles);
    if (RoleAccessPolicy.rolesCanAccessSender(roles)) return true;
    final db = FirebaseFirestore.instance;
    final riderDoc = await db.collection('riderProfiles').doc(user.uid).get();
    final adminDoc = await db.collection('adminUsers').doc(user.uid).get();
    if (!roles.contains(CircumRole.rider) &&
        !roles.contains(CircumRole.admin) &&
        !riderDoc.exists &&
        !adminDoc.exists) {
      await db.collection('users').doc(user.uid).set({
        'email': user.email,
        'role': 'user',
        'roles': ['sender'],
        'userType': 'sender',
        'status': 'active',
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      setState(() => _availableRoles = {CircumRole.sender});
      return true;
    }
    return false;
  }

  Future<Set<CircumRole>> _rolesForSenderUser(User user) async {
    final token = await user.getIdTokenResult(true);
    final claims = token.claims ?? const <String, dynamic>{};
    final db = FirebaseFirestore.instance;
    final userDoc = await db.collection('users').doc(user.uid).get();
    final riderDoc = await db.collection('riderProfiles').doc(user.uid).get();
    final adminDoc = await db.collection('adminUsers').doc(user.uid).get();
    return RoleAccessPolicy.resolveRoles(
      claims: claims,
      user: userDoc.data() ?? const {},
      rider: riderDoc.data() ?? const {},
      adminUser: adminDoc.data() ?? const {},
    );
  }

  Future<void> _signOutSender() async {
    await FirebaseAuth.instance.signOut();
    await _senderSub?.cancel();
    await _senderRothWalletSub?.cancel();
    await _deliveryAdjustmentSub?.cancel();
    if (!mounted) return;
    setState(() {
      _senderUser = null;
      _senderProfile = null;
      _senderRothBalance = 0;
      _senderDeliveries = const [];
      _senderBusinessAccounts = const [];
      _activeBusinessId = null;
      _activeBusinessName = null;
      _activeBusinessRole = null;
      _selectedSenderDelivery = null;
      _senderDeliveryLoadError = null;
      _availableRoles = const {};
      _roleChoiceConfirmed = false;
      _step = _SenderStep.dashboard;
      _senderProfileMessage = 'Signed out.';
    });
  }

  Future<void> _saveSenderProfile() async {
    final user = _senderUser;
    if (user == null) return;
    setState(() => _senderProfileSaving = true);
    try {
      final profile = _senderProfile ??
          SenderProfile.fromMap(user.uid, {
            'email': user.email,
            'fullName': _senderName.text.trim(),
            'phoneNumber': _senderPhone.text.trim(),
          });
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set(
            profile.safeUpdatePatch(
              fullName: _senderName.text.trim(),
              phoneNumber: _senderPhone.text.trim(),
              savedAddresses: profile.savedAddresses,
              communicationPreferences: profile.communicationPreferences.isEmpty
                  ? const {'email': true, 'sms': true}
                  : profile.communicationPreferences,
            ),
            SetOptions(merge: true),
          );
      setState(() => _senderProfileMessage = 'Profile saved.');
    } catch (_) {
      setState(() => _senderProfileMessage = 'Could not save the profile.');
    } finally {
      if (mounted) setState(() => _senderProfileSaving = false);
    }
  }

  Future<void> _uploadSenderProfilePhoto() async {
    final user = _senderUser;
    if (user == null || _senderProfileSaving) return;
    setState(() {
      _senderProfileSaving = true;
      _senderProfileMessage = 'Uploading profile photo...';
    });
    try {
      final picked = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        imageQuality: 84,
      );
      if (picked == null) {
        if (mounted) {
          setState(() => _senderProfileMessage = 'No photo selected.');
        }
        return;
      }
      if (!await _parcelPhotoIsSafe(picked)) {
        if (mounted) {
          setState(
            () => _senderProfileMessage =
                'Choose a JPG, PNG, WebP, or HEIC image under 10MB.',
          );
        }
        return;
      }
      final bytes = await picked.readAsBytes();
      final safeName = picked.name.replaceAll(RegExp(r'[^A-Za-z0-9._-]'), '_');
      final storagePath =
          'sender_profile_photos/${user.uid}/${DateTime.now().millisecondsSinceEpoch}_$safeName';
      final ref = FirebaseStorage.instance.ref(storagePath);
      await ref.putData(bytes);
      final url = await ref.getDownloadURL();
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'photoUrl': url,
        'photoURL': url,
        'profilePhotoUpdatedAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      if (mounted) {
        setState(() => _senderProfileMessage = 'Profile photo updated.');
      }
    } catch (_) {
      if (mounted) {
        setState(() => _senderProfileMessage = 'Could not update photo.');
      }
    } finally {
      if (mounted) setState(() => _senderProfileSaving = false);
    }
  }

  Future<void> _addSenderAddress() async {
    final user = _senderUser;
    final address = _savedAddress.text.trim();
    final validated = _validatedSavedAddress;
    if (user == null || address.isEmpty || validated == null) {
      setState(
        () => _senderProfileMessage =
            'Choose a verified address suggestion before saving.',
      );
      return;
    }
    final next = [
      ...?_senderProfile?.savedAddresses,
      SavedSenderAddress(
        label: _savedAddressLabel.text.trim().isEmpty
            ? 'Saved address'
            : _savedAddressLabel.text.trim(),
        address: address,
        addressType: _savedAddressType,
        postcode: validated.postcode,
        lat: validated.lat,
        lng: validated.lng,
        placeId: validated.placeId,
        provider: validated.provider,
        locationId: validated.locationId,
      ),
    ];
    setState(() => _senderProfileSaving = true);
    try {
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'savedAddresses':
            next.map((senderAddress) => senderAddress.toJson()).toList(),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      _savedAddress.clear();
      _validatedSavedAddress = null;
      setState(() => _senderProfileMessage = 'Saved address added.');
    } finally {
      if (mounted) setState(() => _senderProfileSaving = false);
    }
  }

  Future<void> _loadSenderDeliveries(String uid) async {
    try {
      final db = FirebaseFirestore.instance;
      final snapshots = await Future.wait([
        db
            .collection('deliveryRequests')
            .where('senderId', isEqualTo: uid)
            .get(),
        db.collection('deliveryRequests').where('userId', isEqualTo: uid).get(),
        db.collection('history').where('userId', isEqualTo: uid).get(),
      ]);
      final byId = <String, SenderDeliveryRecord>{};
      for (final snapshot in snapshots) {
        for (final doc in snapshot.docs) {
          final record = SenderDeliveryRecord.fromMap(doc.id, doc.data());
          byId[record.requestId] = record;
        }
      }
      final records = SenderProfileService.ownDeliveries(
        uid,
        byId.values,
      ).toList(growable: false)
        ..sort((a, b) {
          final left = a.createdAt ?? DateTime.fromMillisecondsSinceEpoch(0);
          final right = b.createdAt ?? DateTime.fromMillisecondsSinceEpoch(0);
          return right.compareTo(left);
        });
      if (!mounted) return;
      setState(() {
        _senderDeliveries = records;
        _senderDeliveryLoadError = null;
      });
      await _syncSenderTrustBaseline(uid, records);
    } catch (error) {
      debugPrint('Could not load sender deliveries: $error');
      if (!mounted) return;
      setState(() {
        _senderDeliveries = const [];
        _senderDeliveryLoadError =
            'We could not load your delivery status. Please refresh or contact support.';
      });
    }
  }

  Future<void> _loadSenderBusinessAccounts(String uid) async {
    try {
      final email = (_senderUser?.email ?? '').trim().toLowerCase();
      final db = FirebaseFirestore.instance;
      final snapshots = await Future.wait([
        db
            .collection('businessAccounts')
            .where('createdByUserId', isEqualTo: uid)
            .limit(20)
            .get(),
        db
            .collection('businessAccounts')
            .where('teamMemberIds', arrayContains: uid)
            .limit(20)
            .get(),
        if (email.isNotEmpty)
          db
              .collection('businessAccounts')
              .where('teamMemberIds', arrayContains: email)
              .limit(20)
              .get(),
      ]);
      final byId = <String, Map<String, dynamic>>{};
      for (final snapshot in snapshots) {
        for (final doc in snapshot.docs) {
          byId[doc.id] = <String, dynamic>{'id': doc.id, ...doc.data()};
        }
      }
      final records = byId.values.toList(growable: false)
        ..sort((a, b) => '${a['businessName'] ?? ''}'
            .compareTo('${b['businessName'] ?? ''}'));
      if (!mounted) return;
      setState(() => _senderBusinessAccounts = records);
    } catch (error) {
      debugPrint('Could not load business accounts: $error');
      if (!mounted) return;
      setState(() => _senderBusinessAccounts = const []);
    }
  }

  Future<void> _createBusinessAccount() async {
    final user = _senderUser ?? FirebaseAuth.instance.currentUser;
    if (user == null) {
      setState(
          () => _businessMessage = 'Sign in to create a business account.');
      return;
    }
    final name = _businessName.text.trim();
    final contactName = _businessContactName.text.trim();
    final contactEmail = _businessContactEmail.text.trim().toLowerCase();
    if (name.isEmpty || contactName.isEmpty || contactEmail.isEmpty) {
      setState(() =>
          _businessMessage = 'Add business name, contact name, and email.');
      return;
    }
    final doc = FirebaseFirestore.instance.collection('businessAccounts').doc();
    final owner = {
      'userId': user.uid,
      'email': (user.email ?? contactEmail).toLowerCase(),
      'name': contactName,
      'role': 'owner',
      'joinedAt': Timestamp.now(),
      'status': 'active',
    };
    await doc.set({
      'businessId': doc.id,
      'businessName': name,
      'companyNumber': _businessCompanyNumber.text.trim(),
      'contactName': contactName,
      'contactEmail': contactEmail,
      'phone': _businessPhone.text.trim(),
      'billingEmail': _businessBillingEmail.text.trim().isEmpty
          ? contactEmail
          : _businessBillingEmail.text.trim().toLowerCase(),
      'businessAddress': _businessAddress.text.trim(),
      'createdByUserId': user.uid,
      'createdAt': FieldValue.serverTimestamp(),
      'updatedAt': FieldValue.serverTimestamp(),
      'status': 'pending',
      'teamMemberIds': [user.uid],
      'managerIds': [user.uid],
      'teamMembers': [owner],
      'defaultPickupAddresses': [
        if (_businessAddress.text.trim().isNotEmpty)
          _businessAddress.text.trim(),
      ],
      'monthlySpendLimit': null,
      'notes': '',
    });
    _businessName.clear();
    _businessCompanyNumber.clear();
    _businessContactName.clear();
    _businessContactEmail.clear();
    _businessPhone.clear();
    _businessBillingEmail.clear();
    _businessAddress.clear();
    await _loadSenderBusinessAccounts(user.uid);
    if (!mounted) return;
    setState(() =>
        _businessMessage = 'Business account created and pending approval.');
  }

  Future<void> _addBusinessTeamMember(Map<String, dynamic> account) async {
    final user = _senderUser ?? FirebaseAuth.instance.currentUser;
    if (user == null) return;
    if (!_canManageBusinessAccount(account, user.uid)) {
      setState(() => _businessMessage =
          'Only business owners and admins can manage team members.');
      return;
    }
    final id = '${account['id'] ?? account['businessId'] ?? ''}';
    final email = _businessTeamEmail.text.trim().toLowerCase();
    if (id.isEmpty || email.isEmpty) return;
    final member = {
      'userId': email,
      'email': email,
      'name': _businessTeamName.text.trim(),
      'role': _businessTeamRole,
      'joinedAt': Timestamp.now(),
      'status': 'invited',
    };
    await FirebaseFirestore.instance
        .collection('businessAccounts')
        .doc(id)
        .set({
      'teamMemberIds': FieldValue.arrayUnion([email]),
      if (_businessTeamRole == 'owner' || _businessTeamRole == 'admin')
        'managerIds': FieldValue.arrayUnion([email]),
      'teamMembers': FieldValue.arrayUnion([member]),
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    _businessTeamEmail.clear();
    _businessTeamName.clear();
    await _loadSenderBusinessAccounts(user.uid);
    if (!mounted) return;
    setState(() => _businessMessage = 'Team member invited.');
  }

  Future<void> _removeBusinessTeamMember(
    Map<String, dynamic> account,
    Map<String, dynamic> member,
  ) async {
    final user = _senderUser ?? FirebaseAuth.instance.currentUser;
    if (user == null) return;
    if (!_canManageBusinessAccount(account, user.uid)) return;
    final id = '${account['id'] ?? account['businessId'] ?? ''}';
    final memberId = '${member['userId'] ?? member['email'] ?? ''}';
    if (id.isEmpty || memberId.isEmpty || memberId == user.uid) return;
    final members = ((account['teamMembers'] as List?) ?? const [])
        .whereType<Map>()
        .map((item) => Map<String, dynamic>.from(item))
        .where((item) => '${item['userId'] ?? item['email'] ?? ''}' != memberId)
        .toList(growable: false);
    final memberIds = ((account['teamMemberIds'] as List?) ?? const [])
        .map((item) => '$item')
        .where((item) => item != memberId)
        .toList(growable: false);
    final managerIds = ((account['managerIds'] as List?) ?? const [])
        .map((item) => '$item')
        .where((item) => item != memberId)
        .toList(growable: false);
    await FirebaseFirestore.instance
        .collection('businessAccounts')
        .doc(id)
        .set({
      'teamMembers': members,
      'teamMemberIds': memberIds,
      'managerIds': managerIds,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await _loadSenderBusinessAccounts(user.uid);
    if (!mounted) return;
    setState(() => _businessMessage = 'Team member removed.');
  }

  void _startBusinessDelivery(Map<String, dynamic> account) {
    final status = '${account['status'] ?? 'pending'}';
    if (status != 'approved') {
      setState(() =>
          _businessMessage = 'This business account must be approved first.');
      return;
    }
    setState(() {
      _activeBusinessId = '${account['id'] ?? account['businessId'] ?? ''}';
      _activeBusinessName = '${account['businessName'] ?? 'Business'}';
      final user = _senderUser ?? FirebaseAuth.instance.currentUser;
      _activeBusinessRole =
          user == null ? 'member' : _businessRole(account, user);
      _step = _SenderStep.details;
      _businessMessage = null;
    });
  }

  bool _canManageBusinessAccount(Map<String, dynamic> account, String uid) {
    if ('${account['createdByUserId'] ?? ''}' == uid) return true;
    if (((account['managerIds'] as List?) ?? const [])
        .map((item) => '$item')
        .contains(uid)) {
      return true;
    }
    final members = (account['teamMembers'] as List?) ?? const [];
    return members.whereType<Map>().any((member) {
      final memberId = '${member['userId'] ?? member['email'] ?? ''}';
      final role = '${member['role'] ?? ''}';
      return memberId == uid && (role == 'owner' || role == 'admin');
    });
  }

  Future<void> _syncSenderTrustBaseline(
    String uid,
    List<SenderDeliveryRecord> records,
  ) async {
    if (records.isEmpty || _senderUser?.uid != uid) return;
    try {
      await FirebaseFunctions.instance
          .httpsCallable('syncSenderTrustBaseline')
          .call();
    } catch (error) {
      debugPrint('Could not sync sender trust baseline: $error');
    }
  }

  Future<void> _cancelSenderBooking(SenderDeliveryRecord delivery) async {
    final user = _senderUser;
    if (user == null ||
        !BookingCancellationPolicy.canSenderCancel(delivery.status)) {
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Cancel this booking?'),
        content: const Text(
          'The booking will remain in your history and Circum admin records.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Keep booking'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Cancel Booking'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;

    try {
      final reference = FirebaseFirestore.instance
          .collection('deliveryRequests')
          .doc(delivery.id);
      await FirebaseFirestore.instance.runTransaction((transaction) async {
        final snapshot = await transaction.get(reference);
        final data = snapshot.data();
        if (data == null) throw StateError('Booking no longer exists.');
        final ownerId = '${data['senderId'] ?? data['userId'] ?? ''}';
        if (ownerId != user.uid) {
          throw StateError('You cannot cancel this booking.');
        }
        final currentStatus = '${data['status'] ?? ''}';
        if (!BookingCancellationPolicy.canSenderCancel(currentStatus)) {
          throw StateError(
              'This booking has already started and cannot be cancelled.');
        }
        transaction.update(reference, {
          'status': 'cancelled_by_sender',
          'matchingStatus': 'cancelled',
          'cancelledAt': FieldValue.serverTimestamp(),
          'cancelledBy': user.uid,
          'cancelledByEmail': user.email,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      });
      await _loadSenderDeliveries(user.uid);
      if (!mounted) return;
      setState(() {
        _selectedSenderDelivery = null;
        _senderProfileMessage = 'Booking cancelled.';
      });
    } catch (error) {
      if (!mounted) return;
      setState(() =>
          _senderProfileMessage = '$error'.replaceFirst('Bad state: ', ''));
    }
  }

  String _friendlySenderAuthMessage(FirebaseAuthException error) {
    return switch (error.code) {
      'email-already-in-use' => 'That email already has a Circum profile.',
      'user-not-found' => 'No Circum profile found for that email.',
      'wrong-password' ||
      'invalid-credential' =>
        'Those sign-in details are not right.',
      'weak-password' => 'Use a stronger password.',
      _ => 'We could not sign you in. Please check the details.',
    };
  }

  Future<void> _analyseRequest() async {
    final pickupPhone = _effectiveCollectionContactPhone;
    final dropoffName = _receiverName.text.trim();
    final dropoffPhone = _receiverPhone.text.trim();
    if (pickupPhone.isEmpty) {
      _showBookingReviewMessage('Please add a pick-up phone number');
      return;
    }
    if (dropoffName.length < 2) {
      _showBookingReviewMessage('Please add a drop-off contact name');
      return;
    }
    if (dropoffPhone.isEmpty) {
      _showBookingReviewMessage('Please add a drop-off phone number');
      return;
    }
    if (!_hasValidatedRoute) {
      setState(() {
        _checkoutState = _CheckoutState.failed;
        _firebaseError = _locationValidationMessage;
      });
      return;
    }
    if (!_hasRequiredContactDetails) {
      setState(() {
        _checkoutState = _CheckoutState.failed;
        _firebaseError = _contactValidationMessage;
      });
      return;
    }
    setState(() {
      _checkoutState = _CheckoutState.validating;
      _analyzing = true;
      _broadcasting = false;
      if (_parcelPhoto != null) {
        _parcelPhotoMessage = 'IRIS is reviewing your item...';
      }
    });
    await Future<void>.delayed(const Duration(milliseconds: 900));
    if (!mounted) return;
    final senderWeight = DeliveryPricing.parseWeightKg(
      _weight.text,
      fallbackKg: 0,
    );
    final estimate = await _estimateWeightWithIris(_irisImageInsight);
    final decision = _resolvePricingWeight(
      estimate: estimate,
      senderWeightKg: senderWeight > 0 ? senderWeight : null,
    );
    setState(() {
      _confirmedDeliveryDecision = null;
      _senderEnteredWeightKg = senderWeight > 0 ? senderWeight : null;
      _irisEstimatedWeightKg =
          decision.source == 'repository_match' && decision.weightKg != null
              ? math.max(estimate.weightKg, decision.weightKg!)
              : estimate.weightKg;
      _irisWeightBand = estimate.weightBand;
      _irisWeightConfidence = estimate.confidence;
      _irisWeightExplanation = estimate.explanation;
      _irisWeightSource = estimate.weightSource;
      _irisMatchedItemName = estimate.matchedItemName;
      _irisQuantity = estimate.quantity;
      _irisSingleItemWeightKg = estimate.singleItemWeightKg;
      _irisWeightConfidenceScore = estimate.confidenceScore;
      _irisHistoricalVerifiedWeightKg = estimate.historicalVerifiedWeightKg;
      _irisLearningReason = estimate.learningReason;
      _irisTypicalDimensions = estimate.typicalDimensions;
      _irisVehicleSuitability = estimate.vehicleSuitability;
      _irisFragile = estimate.fragile;
      _irisValueSensitive = estimate.valueSensitive;
      _irisVanguardRecommended = estimate.vanguardRecommended;
      _irisStackable = estimate.stackable;
      _irisHandlingNotes = estimate.handlingNotes;
      _weightVerificationRequired = decision.verificationRequired;
      _weightPricingReason = decision.reason;
      _analyzing = false;
      if (_parcelPhoto != null) {
        _parcelPhotoMessage = estimate.weightSource == 'photo_match'
            ? 'IRIS reviewed the photo and item details.'
            : 'IRIS used the photo with your item details.';
      }
      _checkoutState = decision.weightKg == null
          ? _CheckoutState.draft
          : _CheckoutState.optionsReady;
      if (estimate.confidence == 'high' && senderWeight <= 0) {
        _weight.text = _formatWeight(estimate.weightKg);
      }
      _weightMessage = decision.message;
    });
    if (decision.weightKg != null) {
      _confirmWeight(
        decision.weightKg!,
        source: decision.source,
        reason: decision.reason,
        verificationRequired: decision.verificationRequired,
      );
      _logCheckoutPricing();
    }
  }

  void _showBookingReviewMessage(String message) {
    setState(() {
      _checkoutState = _CheckoutState.draft;
      _firebaseError = message;
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

