  Future<void> _pickParcelPhoto() async {
    setState(() {
      _parcelPhotoBusy = true;
      _parcelPhotoMessage = null;
    });
    try {
      final picked = await ImagePicker().pickImage(
        source: kIsWeb ? ImageSource.gallery : ImageSource.camera,
        imageQuality: 82,
      );
      if (!mounted) return;
      if (picked != null && !await _parcelPhotoIsSafe(picked)) {
        setState(() {
          _parcelPhoto = null;
          _parcelPhotoCapturedAt = null;
          _irisImageInsight = null;
          _parcelPhotoMessage =
              'Choose a JPG, PNG, WebP, or HEIC image under 10MB.';
        });
        return;
      }
      final insight =
          picked == null ? null : await _analyseParcelPhotoForIris(picked);
      if (!mounted) return;
      setState(() {
        _parcelPhoto = picked;
        _parcelPhotoCapturedAt = picked == null ? null : DateTime.now();
        _irisImageInsight = insight;
        _parcelPhotoMessage = picked == null
            ? 'No parcel photo selected.'
            : 'Parcel photo added. IRIS will use it with your item details.';
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _parcelPhotoMessage =
            'Parcel photo could not be added. You can continue safely.';
      });
    } finally {
      if (mounted) setState(() => _parcelPhotoBusy = false);
    }
  }

  Future<bool> _parcelPhotoIsSafe(XFile photo) async {
    final name = photo.name.toLowerCase();
    final allowedExtension = name.endsWith('.jpg') ||
        name.endsWith('.jpeg') ||
        name.endsWith('.png') ||
        name.endsWith('.webp') ||
        name.endsWith('.heic') ||
        name.endsWith('.heif');
    final mime = (photo.mimeType ?? '').toLowerCase();
    final allowedMime = mime.isEmpty ||
        mime.startsWith('image/') ||
        mime == 'application/octet-stream';
    final length = await photo.length();
    return allowedExtension && allowedMime && length <= 10 * 1024 * 1024;
  }

  Future<_IrisImageInsight> _analyseParcelPhotoForIris(XFile photo) async {
    try {
      final sizeBytes = await photo.length();
      final name = photo.name.toLowerCase();
      final details = '${_description.text} $name'.toLowerCase();
      var inferredItem = 'Parcel photo';
      var category = 'Parcel';
      var weightKg = 2.0;
      var confidence = 0.45;
      var fragilityRisk = 'medium';
      var valueRisk = 'low';
      var handlingNotes = 'Photo attached for rider handling context.';
      var riderGuidance = 'Check parcel size and condition at pickup.';
      var needsReview = false;

      final repository = _knownProductWeightEstimate(details);
      if (repository != null) {
        inferredItem = repository.matchedItemName ?? repository.packageType;
        category = repository.packageType;
        weightKg = repository.weightKg;
        confidence = (repository.confidenceScore ?? 0.7).clamp(0.0, 1.0);
        fragilityRisk = repository.fragile ? 'high' : 'medium';
        valueRisk = _looksHighValue(details, repository.packageType)
            ? 'high'
            : 'medium';
        handlingNotes =
            repository.handlingNotes ?? 'Handle according to item type.';
        riderGuidance =
            'Photo and item details suggest $inferredItem. Verify condition and weight at pickup.';
      } else if (_containsAny(details, const [
        'phone',
        'iphone',
        'ipad',
        'laptop',
        'macbook',
        'camera',
        'watch',
        'console',
      ])) {
        inferredItem = 'Consumer electronics';
        category = 'Electronics';
        weightKg = 2.5;
        confidence = 0.58;
        fragilityRisk = 'high';
        valueRisk = 'high';
        handlingNotes = 'Likely fragile or high-value electronics.';
        riderGuidance = 'Keep sealed, avoid stacking, and verify handover.';
        needsReview = true;
      } else if (_containsAny(details, const [
        'sofa',
        'chair',
        'table',
        'tv',
        'furniture',
        'mattress',
        'bike',
      ])) {
        inferredItem = 'Large item';
        category = 'Large item';
        weightKg = 15;
        confidence = 0.55;
        fragilityRisk = details.contains('tv') ? 'high' : 'medium';
        valueRisk = 'medium';
        handlingNotes = 'Bulky item; check vehicle suitability.';
        riderGuidance = 'Confirm dimensions and safe loading before pickup.';
        needsReview = true;
      } else if (sizeBytes > 7 * 1024 * 1024) {
        inferredItem = 'Detailed parcel photo';
        category = 'Parcel';
        weightKg = 5;
        confidence = 0.42;
        fragilityRisk = 'medium';
        valueRisk = 'low';
        handlingNotes = 'Photo quality is high, but item type is unclear.';
        riderGuidance = 'Use the photo to confirm parcel condition at pickup.';
        needsReview = true;
      }

      final band = DeliveryPricing.weightBandFor(weightKg).category;
      return _IrisImageInsight(
        inferredItemName: inferredItem,
        inferredCategory: category,
        estimatedWeightKg: weightKg,
        weightClass: band,
        confidenceScore: confidence,
        fragilityRisk: fragilityRisk,
        valueRisk: valueRisk,
        handlingNotes: handlingNotes,
        riderGuidance: riderGuidance,
        needsHumanReview: needsReview || confidence < 0.5,
        fileName: photo.name,
        fileSizeBytes: sizeBytes,
      );
    } catch (_) {
      return _IrisImageInsight.fallback(photo.name);
    }
  }

  Future<Map<String, dynamic>> _uploadParcelPhoto(String requestId) async {
    final photo = _parcelPhoto;
    if (photo == null) {
      return {'hasPhoto': false, 'analysisStatus': 'not_provided'};
    }
    try {
      final bytes = await photo.readAsBytes();
      final safeName = photo.name.replaceAll(RegExp(r'[^A-Za-z0-9._-]'), '_');
      final storagePath =
          'parcel_photos/$requestId/${DateTime.now().millisecondsSinceEpoch}_$safeName';
      final ref = FirebaseStorage.instance.ref(storagePath);
      await ref.putData(bytes);
      final url = await ref.getDownloadURL();
      return {
        'hasPhoto': true,
        'imageUrl': url,
        'photoUrl': url,
        'storagePath': storagePath,
        'capturedAt': _parcelPhotoCapturedAt == null
            ? null
            : Timestamp.fromDate(_parcelPhotoCapturedAt!),
        'uploadedAt': FieldValue.serverTimestamp(),
        'analysisStatus': 'attached_for_iris_review',
      };
    } catch (_) {
      return {
        'hasPhoto': true,
        'imageUrl': null,
        'photoUrl': null,
        'storagePath': null,
        'capturedAt': _parcelPhotoCapturedAt == null
            ? null
            : Timestamp.fromDate(_parcelPhotoCapturedAt!),
        'uploadedAt': null,
        'analysisStatus': 'upload_failed',
        'requiresIRISReview': true,
      };
    }
  }

  void _confirmIrisWeight() {
    final estimateWeight = _irisEstimatedWeightKg;
    if (estimateWeight == null || estimateWeight <= 0) return;
    final senderWeight = DeliveryPricing.parseWeightKg(
      _weight.text,
      fallbackKg: 0,
    );
    final estimate = _IrisWeightEstimate(
      weightKg: estimateWeight,
      weightBand: _irisWeightBand ??
          DeliveryPricing.weightBandFor(estimateWeight).category,
      confidence: _irisWeightConfidence ?? 'low',
      explanation:
          _irisWeightExplanation ?? 'Iris estimate confirmed by sender.',
      packageType: _inferPackageType(),
      requiresVehicleReview: false,
      weightSource: _irisWeightSource ?? 'category_fallback',
      matchedItemName: _irisMatchedItemName,
      confidenceScore: _irisWeightConfidenceScore,
    );
    final decision = _resolvePricingWeight(
      estimate: estimate,
      senderWeightKg: senderWeight > 0 ? senderWeight : null,
    );
    if (decision.weightKg == null) {
      setState(() => _weightMessage = decision.message);
      return;
    }
    if (senderWeight <= 0) {
      _settingWeightFromConfirmation = true;
      _weight.text = _formatWeight(decision.weightKg!);
      _settingWeightFromConfirmation = false;
    }
    _confirmWeight(
      decision.weightKg!,
      source: decision.source,
      reason: decision.reason,
      verificationRequired: decision.verificationRequired,
    );
    setState(() {
      _weightMessage =
          'Confirmed parcel weight: ${_formatWeight(decision.weightKg!)} kg.';
      _checkoutState = _CheckoutState.awaitingPayment;
      _step = _SenderStep.vehicle;
    });
  }

  void _confirmWeight(
    double weightKg, {
    required String source,
    String? reason,
    bool verificationRequired = false,
  }) {
    final band = DeliveryPricing.weightBandFor(weightKg).category;
    setState(() {
      _confirmedWeightKg = weightKg;
      _confirmedWeightBand = band;
      _weightSource = source;
      _weightConfirmedAt = DateTime.now();
      _weightPricingReason = reason;
      _weightVerificationRequired = verificationRequired;
      if (!_matchingHasStarted) {
        _checkoutState = _CheckoutState.optionsReady;
      }
      final recommendedVehicleName = _vehicleSuitability.recommendedVehicle;
      final recommendedVehicle = _vehicles.firstWhere(
        (vehicle) => vehicle.name == recommendedVehicleName,
        orElse: () => _vehicles.last,
      );
      if (!DeliveryPricing.vehicleCanCarryDelivery(
        _selectedVehicle.name,
        _vehicleSuitability,
      )) {
        _selectedVehicle = recommendedVehicle;
      }
      _confirmedDeliveryDecision = _buildCanonicalDeliveryDecision();
      _weightMessage =
          'Confirmed parcel weight: ${_formatWeight(weightKg)} kg.';
    });
  }

  void _handleWeightChanged() {
    if (_settingWeightFromConfirmation || _confirmedWeightKg == null) return;
    final typedWeight = DeliveryPricing.parseWeightKg(
      _weight.text,
      fallbackKg: 0,
    );
    if ((typedWeight - _confirmedWeightKg!).abs() < 0.01) return;
    if (!mounted) return;
    setState(() {
      _confirmedDeliveryDecision = null;
      _confirmedWeightKg = null;
      _confirmedWeightBand = null;
      _weightSource = null;
      _weightConfirmedAt = null;
      _weightPricingReason = null;
      _checkoutState = _CheckoutState.draft;
      _broadcasting = false;
      _weightMessage = 'Confirm parcel weight before payment.';
    });
  }

  _WeightPricingDecision _resolvePricingWeight({
    required _IrisWeightEstimate estimate,
    required double? senderWeightKg,
  }) {
    final trustedKnownItem = estimate.confidence == 'high' &&
        (estimate.weightSource == 'known_product_lookup' ||
            estimate.weightSource == 'repository_match');
    if (trustedKnownItem) {
      final trustedDecision =
          IrisWeightEstimator.resolveTrustedKnownItemPricing(
        description: _description.text,
        quantity: estimate.quantity,
        userWeightKg: senderWeightKg ?? 0,
        trustedItemWeightKg: estimate.weightKg,
        historicalMatches: estimate.historicalVerifiedWeightKg == null
            ? const []
            : [estimate.historicalVerifiedWeightKg!],
      );
      final pricingWeight = trustedDecision.pricingWeightKg;
      return _WeightPricingDecision(
        weightKg: pricingWeight,
        weightBand: DeliveryPricing.weightBandFor(pricingWeight).category,
        source: 'repository_match',
        message: trustedDecision.explanation ??
            'IRIS used the verified item weight with a packaging allowance.',
        reason: trustedDecision.explanation ??
            'Verified catalogue weight used for pricing.',
        verificationRequired: true,
      );
    }
    final knownItemDecision = senderWeightKg != null && senderWeightKg > 0
        ? IrisWeightEstimator.resolveKnownItemWeight(
            description: _description.text,
            senderWeightKg: senderWeightKg,
          )
        : null;
    if (knownItemDecision?.unusual == true && estimate.confidence == 'high') {
      final pricingWeight = knownItemDecision!.pricingWeightKg;
      return _WeightPricingDecision(
        weightKg: pricingWeight,
        weightBand: DeliveryPricing.weightBandFor(pricingWeight).category,
        source: 'repository_match',
        message: knownItemDecision.warning!,
        reason: knownItemDecision.warning!,
        verificationRequired: true,
      );
    }
    final classification = DeliveryPricing.resolveClassification(
      description: _description.text,
      userEnteredWeightKg: senderWeightKg,
      irisEstimateKg: estimate.weightKg,
      historicalVerifiedMaxKg: estimate.historicalVerifiedWeightKg,
      confidence: estimate.confidence,
    );
    final hasSenderWeight = senderWeightKg != null && senderWeightKg > 0;
    final irisBand = DeliveryPricing.weightBandFor(estimate.weightKg);
    final senderBand =
        hasSenderWeight ? DeliveryPricing.weightBandFor(senderWeightKg) : null;
    final bandChanged =
        senderBand != null && senderBand.category != irisBand.category;
    final significantDifference = bandChanged ||
        classification.selectedWeightSource == 'keyword_override';
    final mismatchReview = _hasIrisMismatchReview(
      senderWeightKg: senderWeightKg,
      estimateWeightKg: estimate.weightKg,
    );
    final higherWeight = classification.finalWeightKg;
    final higherBand = DeliveryPricing.weightBandFor(higherWeight);

    if (!hasSenderWeight &&
        estimate.confidence == 'low' &&
        classification.selectedWeightSource != 'keyword_override') {
      return const _WeightPricingDecision(
        message: 'Confirm parcel weight before payment.',
        reason: 'Iris confidence is low, so sender weight is required.',
        verificationRequired: true,
      );
    }

    if (estimate.confidence == 'low') {
      return _WeightPricingDecision(
        weightKg: higherWeight,
        weightBand: higherBand.category,
        source: classification.selectedWeightSource,
        message: significantDifference
            ? 'Iris is not confident and the details may indicate a different weight band. Confirm your weight to continue; the rider will verify at pickup.'
            : 'IRIS has analysed this item and selected the most reliable weight available.',
        reason: classification.resolutionReason,
        verificationRequired: true,
      );
    }

    final source = classification.selectedWeightSource == 'keyword_override'
        ? 'keyword_override'
        : estimate.weightSource == 'known_product_lookup'
            ? 'repository_match'
            : estimate.weightSource == 'category_estimate'
                ? 'category_estimate'
                : estimate.weightKg >= (senderWeightKg ?? 0)
                    ? 'photo_match'
                    : 'customer_declared';

    return _WeightPricingDecision(
      weightKg: higherWeight,
      weightBand: higherBand.category,
      source: source,
      message: mismatchReview
          ? 'Potential mismatch detected — manual review required.'
          : significantDifference
              ? 'Iris and your entered weight fall into different pricing checks. Confirm the pricing weight before continuing.'
              : 'IRIS has analysed this item and selected the most reliable weight available.',
      reason: classification.resolutionReason,
      verificationRequired: mismatchReview ||
          significantDifference ||
          classification.requiresManualReview,
    );
  }

  bool _hasIrisMismatchReview({
    required double? senderWeightKg,
    required double estimateWeightKg,
  }) {
    return IrisWeightEstimator.potentialMismatchDetected(
      description: _description.text,
      customerDeclaredWeightKg: senderWeightKg,
      irisEstimatedWeightKg: estimateWeightKg,
    );
  }

  Future<_IrisWeightEstimate> _estimateWeightWithIris(
    _IrisImageInsight? imageInsight,
  ) async {
    final text = '${_description.text} ${_pickup.text} ${_dropoff.text}'
        .trim()
        .toLowerCase();
    final knownProduct = _knownProductWeightEstimate(text);
    if (knownProduct != null) {
      return _applyVerifiedParcelLearning(knownProduct, text);
    }

    double estimate = 2;
    final quantity = IrisWeightEstimator.extractQuantity(_description.text);
    var confidence = 'low';
    var packageType = 'Parcel';
    var vehicleReview = false;
    var explanation =
        'Iris could not estimate weight safely from the details provided.';

    if (_irisBundleDetected(text)) {
      estimate = 20;
      confidence = 'low';
      packageType = 'Grouped items';
      vehicleReview = true;
      explanation = _irisBundlePrompt;
    } else if (text.contains('document') ||
        text.contains('letter') ||
        text.contains('passport')) {
      estimate = 0.5;
      confidence = 'high';
      packageType = 'Documents';
      explanation = 'The item sounds like documents or a small envelope.';
    } else if (text.contains('phone') ||
        text.contains('book') ||
        text.contains('clothes') ||
        text.contains('shoe')) {
      estimate = 2;
      confidence = 'medium';
      packageType = 'Small parcel';
      explanation = 'The item sounds like a small parcel.';
    } else if (text.contains('laptop') ||
        text.contains('computer') ||
        text.contains('console')) {
      estimate = 3;
      confidence = 'medium';
      packageType = 'Electronics';
      explanation = 'The item sounds like consumer electronics.';
    } else if (text.contains('box') ||
        text.contains('parcel') ||
        text.contains('package')) {
      estimate = 5;
      confidence = 'medium';
      packageType = 'Boxed parcel';
      explanation =
          'The description suggests a parcel, but exact contents are unclear.';
    } else if (text.contains('chair') ||
        text.contains('tv') ||
        text.contains('furniture') ||
        text.contains('bike')) {
      estimate = 15;
      confidence = 'low';
      packageType = 'Large item';
      vehicleReview = true;
      explanation =
          'The item may be oversized or heavy, so sender confirmation is required.';
    }

    final totalEstimate = estimate * quantity;
    final estimateResult = _IrisWeightEstimate(
      weightKg: totalEstimate,
      weightBand: DeliveryPricing.weightBandFor(totalEstimate).category,
      confidence: confidence,
      explanation: explanation,
      packageType: packageType,
      requiresVehicleReview: vehicleReview,
      weightSource: 'category_fallback',
      confidenceScore: _scoreForIrisConfidence(confidence),
      quantity: quantity,
      singleItemWeightKg: estimate,
    );
    return _applyVerifiedParcelLearning(
      _mergeImageInsightWithTextEstimate(estimateResult, imageInsight),
      text,
    );
  }

  _IrisWeightEstimate _mergeImageInsightWithTextEstimate(
    _IrisWeightEstimate textEstimate,
    _IrisImageInsight? imageInsight,
  ) {
    if (imageInsight == null) return textEstimate;
    final imageTotalWeight =
        imageInsight.estimatedWeightKg * textEstimate.quantity;
    final imageBand = DeliveryPricing.weightBandFor(
      imageTotalWeight,
    ).category;
    final textBand = DeliveryPricing.weightBandFor(textEstimate.weightKg);
    final imageBandRank =
        DeliveryPricing.weightBandFor(imageTotalWeight).maxKg ??
            double.infinity;
    final textBandRank = textBand.maxKg ?? double.infinity;
    final strongImage = imageInsight.confidenceScore >= 0.55;
    final shouldUseImage = strongImage &&
        (imageBandRank > textBandRank || textEstimate.confidence == 'low');
    if (!shouldUseImage) {
      return textEstimate.copyWith(
        explanation:
            '${textEstimate.explanation} IRIS also reviewed the photo for handling context.',
        handlingNotes: textEstimate.handlingNotes ?? imageInsight.handlingNotes,
        fragile: textEstimate.fragile || imageInsight.fragilityRisk == 'high',
        requiresVehicleReview:
            textEstimate.requiresVehicleReview || imageInsight.needsHumanReview,
      );
    }
    return textEstimate.copyWith(
      weightKg: math.max(textEstimate.weightKg, imageTotalWeight),
      weightBand: imageBand,
      confidence: imageInsight.confidenceScore >= 0.75 ? 'high' : 'medium',
      explanation:
          'IRIS reviewed the parcel photo and item details, then selected the safest visible weight class.',
      packageType: imageInsight.inferredCategory,
      requiresVehicleReview:
          imageInsight.needsHumanReview || imageTotalWeight > 10,
      weightSource: 'photo_match',
      truthBand: 'Photo Match',
      matchedItemName: imageInsight.inferredItemName,
      confidenceScore: imageInsight.confidenceScore,
      fragile: imageInsight.fragilityRisk == 'high',
      stackable: imageInsight.fragilityRisk != 'high',
      handlingNotes: imageInsight.handlingNotes,
    );
  }

  Future<_IrisWeightEstimate> _applyVerifiedParcelLearning(
    _IrisWeightEstimate base,
    String text,
  ) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return base;
    try {
      final snapshot = await FirebaseFirestore.instance
          .collection('deliveryRequests')
          .where('senderId', isEqualTo: user.uid)
          .where('status', isEqualTo: 'completed')
          .limit(40)
          .get();
      final matches = <double>[];
      for (final doc in snapshot.docs) {
        final data = doc.data();
        final description =
            '${data['packageDescription'] ?? data['description'] ?? ''}'
                .toLowerCase();
        if (!_looksLikeSimilarParcel(text, description)) continue;
        final verified = _readWeightKg(data['finalVerifiedWeight']) ??
            _readWeightKg(data['riderVerifiedWeight']) ??
            _readWeightKg(data['driverReportedWeightKg']) ??
            _readWeightKg(data['finalWeightUsed']) ??
            _readWeightKg(data['finalChargeableWeight']);
        if (verified != null && verified > 0) matches.add(verified);
      }
      if (matches.isEmpty) return base;
      matches.sort();
      final high = matches.last;
      final low = matches.first;
      final trustedKnownItem = base.confidence == 'high' &&
          (base.weightSource == 'known_product_lookup' ||
              base.weightSource == 'repository_match');
      if (trustedKnownItem) {
        final outliers = matches
            .where((weight) => weight > base.weightKg * 5)
            .toList(growable: false);
        if (outliers.isNotEmpty) {
          await FirebaseFirestore.instance
              .collection('irisLearningOutliers')
              .add({
            'senderId': user.uid,
            'description': _description.text.trim(),
            'matchedItemName': base.matchedItemName,
            'trustedWeightKg': base.weightKg,
            'outlierWeightsKg': outliers,
            'reason': 'historical_weight_above_5x_catalogue_weight',
            'status': 'pending_review',
            'createdAt': FieldValue.serverTimestamp(),
          });
        }
        return base.copyWith(
          historicalVerifiedWeightKg: high,
          learningReason: outliers.isNotEmpty
              ? 'IRIS ignored unusually high historical matches because this item has a verified catalogue weight.'
              : 'Historical matches support the verified catalogue estimate.',
          explanation: outliers.isNotEmpty
              ? '${base.explanation} IRIS ignored unusually high historical matches because this item has a verified catalogue weight.'
              : base.explanation,
        );
      }
      final baseBand = DeliveryPricing.weightBandFor(base.weightKg).category;
      final learnedBand = DeliveryPricing.weightBandFor(high).category;
      if (high <= base.weightKg || learnedBand == baseBand) {
        return base.copyWith(
          historicalVerifiedWeightKg: high,
          learningReason:
              'Similar completed parcels were verified at ${_formatWeight(low)}–${_formatWeight(high)}kg.',
        );
      }
      return base.copyWith(
        confidence: base.confidence == 'low' ? 'medium' : base.confidence,
        confidenceScore: base.confidenceScore == null
            ? 0.7
            : base.confidenceScore!.clamp(0.7, 0.9).toDouble(),
        explanation:
            '${base.explanation} Similar completed parcels were verified at ${_formatWeight(low)}–${_formatWeight(high)}kg.',
        truthBand: 'High Confidence',
        historicalVerifiedWeightKg: high,
        learningReason:
            'Similar completed parcels were verified at ${_formatWeight(low)}–${_formatWeight(high)}kg.',
      );
    } catch (_) {
      return base;
    }
  }

  bool _looksLikeSimilarParcel(String current, String previous) {
    final currentTokens = _parcelTokens(current);
    final previousTokens = _parcelTokens(previous);
    if (currentTokens.isEmpty || previousTokens.isEmpty) return false;
    return currentTokens.intersection(previousTokens).length >= 2 ||
        currentTokens.any(previousTokens.contains);
  }

  Set<String> _parcelTokens(String value) {
    const ignored = {
      'the',
      'and',
      'for',
      'with',
      'parcel',
      'package',
      'delivery',
      'send',
      'box',
    };
    return value
        .toLowerCase()
        .split(RegExp(r'[^a-z0-9]+'))
        .where((token) => token.length > 2 && !ignored.contains(token))
        .toSet();
  }

  double? _readWeightKg(Object? value) {
    if (value is num) return value.toDouble();
    if (value is String) {
      final parsed = DeliveryPricing.parseWeightKg(value, fallbackKg: 0);
      return parsed > 0 ? parsed : null;
    }
    return null;
  }

  _IrisWeightEstimate? _knownProductWeightEstimate(String text) {
    final product = IrisWeightEstimator.knownProductEstimate(text);
    if (product == null) return null;
    return _IrisWeightEstimate(
      weightKg: product.weightKg,
      weightBand: product.weightBand,
      confidence: product.confidence,
      explanation: product.explanation,
      packageType: product.packageType,
      requiresVehicleReview: product.requiresVehicleReview,
      weightSource: product.weightSource,
      truthBand: product.truthBand,
      matchedItemName: product.matchedItemName,
      confidenceScore: product.confidenceScore,
      typicalDimensions: product.typicalDimensions,
      vehicleSuitability: product.vehicleSuitability,
      fragile: product.fragile,
      valueSensitive: product.valueSensitive,
      vanguardRecommended: product.vanguardRecommended,
      stackable: product.stackable,
      handlingNotes: product.handlingNotes,
      quantity: product.quantity,
      singleItemWeightKg: product.singleItemWeightKg,
    );
  }

  String _inferPackageType() {
    final description = _description.text.toLowerCase();
    if (description.contains('document') || description.contains('letter')) {
      return 'Documents';
    }
    if (description.contains('laptop') ||
        description.contains('phone') ||
        description.contains('computer')) {
      return 'Electronics';
    }
    if (description.contains('chair') ||
        description.contains('furniture') ||
        description.contains('bike') ||
        description.contains('tv')) {
      return 'Large item';
    }
    if (description.contains('box')) return 'Boxed parcel';
    return 'Parcel';
  }

  double _irisConfidenceScore() {
    return _irisWeightConfidenceScore ??
        _scoreForIrisConfidence(_irisWeightConfidence);
  }

  String _irisTruthBand() {
    if (_irisWeightSource == 'known_product_lookup') return 'Exact Match';
    if (_irisWeightSource == 'verified_parcel_history') {
      return 'High Confidence';
    }
    return switch ((_irisWeightConfidence ?? '').toLowerCase()) {
      'high' => 'High Confidence',
      'medium' => 'Medium Confidence',
      'low' => 'Low Confidence',
      _ => 'Low Confidence',
    };
  }

  Map<String, dynamic>? _irisLearningData() {
    if (_irisHistoricalVerifiedWeightKg == null &&
        (_irisLearningReason == null || _irisLearningReason!.trim().isEmpty)) {
      return null;
    }
    return {
      'source': 'completed_sender_delivery_history',
      'historicalVerifiedWeightKg': _irisHistoricalVerifiedWeightKg,
      'reason': _irisLearningReason,
      'matchedDescription': _description.text.trim(),
      'adminReviewStatus': 'open',
      'canAdminOverride': true,
    };
  }

  double _scoreForIrisConfidence(String? confidence) {
    return switch ((confidence ?? '').toLowerCase()) {
      'high' => 0.9,
      'medium' => 0.65,
      'low' => 0.3,
      _ => 0,
    };
  }

  int _irisConfidencePoints() {
    var score = 50;
    final source = (_irisWeightSource ?? '').toLowerCase();
    final text = _description.text.trim().toLowerCase();
    final hasRepositoryMatch = source == 'known_product_lookup' ||
        source == 'repository_match' ||
        _irisMatchedItemName != null;
    final hasPhoto = _parcelPhoto != null || _irisImageInsight != null;
    final bundle = _irisBundleDetected(text);
    final flags = _irisDeliveryFlags();
    final risk = flags.any(const {
      'fragile',
      'high_value',
      'medical',
      'regulated',
      'vanguard_required',
      'admin_review_required',
    }.contains);
    final conflict = _irisWeightConflict();

    if (source == 'known_product_lookup') {
      score += 25;
    } else if (hasRepositoryMatch) {
      score += 15;
    }
    if (text.isNotEmpty) score += 5;
    if (text.length >= 8) score += 5;
    if (_irisTypicalDimensions != null) score += 10;
    if ((_senderEnteredWeightKg ?? 0) > 0) score += 5;
    if (hasPhoto) score += 10;
    if (_irisHistoricalVerifiedWeightKg != null) score += 15;
    if (_irisVagueDescription(text)) score -= 20;
    if (bundle) score -= 15;
    if (conflict) score -= 20;
    if (!hasRepositoryMatch && source != 'photo_match') score -= 25;
    if (risk) score -= 10;
    if (bundle && _irisTypicalDimensions == null && !hasPhoto) {
      score = math.min(score, 70);
    }
    return score.clamp(0, 100).toInt();
  }

  String _irisConfidenceBandFromPoints(int score) {
    if (score >= 80) return 'high';
    if (score >= 50) return 'medium';
    return 'low';
  }

  bool _irisBundleDetected(String value) {
    final text = value.toLowerCase();
    return _containsAny(text, const [
      'gaming setup',
      'office move',
      'bedroom set',
      'kitchen appliances',
      'home gym',
      'wardrobe contents',
      'multiple boxes',
      'bags of clothes',
      'assorted items',
      'electronics bundle',
      'several boxes',
      'lots of boxes',
      'mixed items',
    ]);
  }

  static const String _irisBundlePrompt =
      'This sounds like multiple items. Please add what is inside so IRIS can price it fairly.';

  bool _irisVagueDescription(String text) {
    final compact = text.trim();
    if (compact.length < 4) return true;
    return const {
      'item',
      'items',
      'parcel',
      'package',
      'box',
      'stuff',
      'things',
    }.contains(compact);
  }

  bool _irisWeightConflict() {
    final sender = _senderEnteredWeightKg;
    final iris = _irisEstimatedWeightKg;
    if (sender == null || sender <= 0 || iris == null || iris <= 0) {
      return false;
    }
    final ratio =
        math.max(sender, iris) / math.max(0.1, math.min(sender, iris));
    return ratio >= 2.0 ||
        DeliveryPricing.weightBandFor(sender).category !=
            DeliveryPricing.weightBandFor(iris).category;
  }

  String _irisSuggestedVehicle() {
    final override =
        '${_activeRequestData?['adminVehicleOverride'] ?? ''}'.trim();
    if (override.isNotEmpty) return override;
    final canonical = _vehicleSuitability.recommendedVehicle.trim();
    if (canonical.isNotEmpty) return canonical;
    final weight = _deliveryClassification.finalWeightKg > 0
        ? _deliveryClassification.finalWeightKg
        : (_irisEstimatedWeightKg ?? _senderEnteredWeightKg ?? 0);
    return DeliveryPricing.recommendedVehicleForWeight(weight);
  }

  Map<String, dynamic> _irisVehicleDecision() {
    final suitability = _vehicleSuitability;
    final activeVehicle = _irisSuggestedVehicle();
    final disqualifiers = <String>[];
    final text = _description.text.toLowerCase();
    if (activeVehicle.toLowerCase() != 'bike') {
      if (_irisValueSensitive ||
          _containsAny(text, const [
            'iphone',
            'phone',
            'smartphone',
            'mobile',
            'laptop',
            'macbook',
            'tablet',
            'ipad',
          ])) {
        disqualifiers.add('bike_disallowed_high_value_electronics');
      }
      if (_irisFragile) {
        disqualifiers.add('bike_disallowed_fragile_item');
      }
      if (_irisBundleDetected(text)) {
        disqualifiers.add('bike_disallowed_bundle');
      }
      if ((_irisEstimatedWeightKg ?? _deliveryClassification.finalWeightKg) >
          10) {
        disqualifiers.add('bike_disallowed_weight');
      }
    }
    if (activeVehicle.toLowerCase() == 'van') {
      disqualifiers.add('car_disallowed_size_or_weight');
    }
    return {
      'recommendedVehicle': activeVehicle.toLowerCase(),
      'minimumVehicle': suitability.recommendedVehicle.toLowerCase(),
      'vehicleReason': suitability.explanation,
      'vehicleConfidence': suitability.score,
      'vehicleDisqualifiers': disqualifiers,
      'vehicleFlags': _irisDeliveryFlags(),
      'vehicleDecisionSource': 'delivery_pricing_vehicle_suitability',
      'adminVehicleOverride': _activeRequestData?['adminVehicleOverride'],
      'overrideReason': _activeRequestData?['overrideReason'],
      'overrideBy': _activeRequestData?['overrideBy'],
      'overrideAt': _activeRequestData?['overrideAt'],
    };
  }

  List<String> _irisDeliveryFlags() {
    final text = _description.text.toLowerCase();
    final packageType = _inferPackageType().toLowerCase();
    final finalWeight = _deliveryClassification.finalWeightKg > 0
        ? _deliveryClassification.finalWeightKg
        : (_irisEstimatedWeightKg ?? _senderEnteredWeightKg ?? 0);
    final vehicle = _irisSuggestedVehicle().toLowerCase();
    final flags = <String>{};

    if (_irisFragile ||
        _containsAny(text, const [
          'fragile',
          'glass',
          'mirror',
          'artwork',
          'painting',
          'ceramic',
          'tv',
          'television',
          'wedding dress',
          'flowers',
        ])) {
      flags.add('fragile');
    }
    if (_irisValueSensitive || _looksHighValue(text, packageType)) {
      flags.add('high_value');
    }
    if (_containsAny(text, const [
      'medicine',
      'medical',
      'medication',
      'prescription',
      'health+',
      'health plus',
    ])) {
      flags.add('medical');
    }
    if (_containsAny(text, const [
      'refrigerated',
      'chilled',
      'frozen',
      'cold chain',
    ])) {
      flags.add('refrigerated');
    }
    if (_containsAny(text, const [
      'passport',
      'controlled',
      'alcohol',
      'tobacco',
      'regulated',
    ])) {
      flags.add('regulated');
    }
    if (packageType.contains('document') ||
        _containsAny(text, const [
          'document',
          'documents',
          'paperwork',
          'letter',
          'passport',
        ])) {
      flags.add('document');
    }
    final dims = _irisTypicalDimensions;
    final oversizedByDimensions = dims != null &&
        (dims.length > 120 || dims.width > 80 || dims.height > 80);
    if (oversizedByDimensions ||
        _containsAny(text, const [
          'mattress',
          'sofa',
          'wardrobe',
          'dining table',
          'table',
          'furniture',
          '65 inch',
          'large tv',
          'office move',
        ])) {
      flags.add('oversized');
    }
    if (finalWeight > 50) flags.add('heavy');
    if (vehicle == 'van' || flags.contains('oversized') || finalWeight > 25) {
      flags.add('van_required');
    }
    if (finalWeight > 50 ||
        _containsAny(text, const [
          'piano',
          'mattress',
          'wardrobe',
          'sofa',
          'dining table',
          'home gym',
        ])) {
      flags.add('two_person_required');
    }
    if ((flags.contains('document') || finalWeight <= 5) &&
        !flags.contains('oversized') &&
        !flags.contains('heavy')) {
      flags.add('bike_eligible');
    }
    if (flags.contains('fragile') ||
        flags.contains('high_value') ||
        flags.contains('medical') ||
        _irisVanguardRecommended ||
        _vanguardAddonSelected) {
      flags.add('vanguard_required');
    }
    if (flags.contains('heavy') ||
        flags.contains('regulated') ||
        flags.contains('two_person_required') ||
        _deliveryClassification.requiresManualReview ||
        _irisBundleDetected(text) ||
        _irisConfidenceBandFromPoints(_irisConfidencePointsWithoutRisk()) ==
            'low') {
      flags.add('admin_review_required');
    }
    return flags.toList(growable: false)..sort();
  }

  int _irisConfidencePointsWithoutRisk() {
    var score = 50;
    final source = (_irisWeightSource ?? '').toLowerCase();
    final text = _description.text.trim().toLowerCase();
    final hasRepositoryMatch = source == 'known_product_lookup' ||
        source == 'repository_match' ||
        _irisMatchedItemName != null;
    if (source == 'known_product_lookup') {
      score += 25;
    } else if (hasRepositoryMatch) {
      score += 15;
    }
    if (text.isNotEmpty) score += 5;
    if (text.length >= 8) score += 5;
    if (_irisTypicalDimensions != null) score += 10;
    if ((_senderEnteredWeightKg ?? 0) > 0) score += 5;
    if (_parcelPhoto != null || _irisImageInsight != null) score += 10;
    if (_irisHistoricalVerifiedWeightKg != null) score += 15;
    if (_irisVagueDescription(text)) score -= 20;
    if (_irisBundleDetected(text)) score -= 15;
    if (_irisWeightConflict()) score -= 20;
    if (!hasRepositoryMatch && source != 'photo_match') score -= 25;
    return score.clamp(0, 100).toInt();
  }

  List<String> _irisReasoningFactors() {
    final factors = <String>[];
    final matched = _irisMatchedItemName?.trim();
    if (matched != null && matched.isNotEmpty) {
      factors.add('Matched known item: $matched.');
    } else {
      factors.add('No exact repository item was found.');
    }
    if (_irisQuantity > 1) {
      factors.add('Quantity multiplier applied: $_irisQuantity items.');
    }
    if (_irisTypicalDimensions != null) {
      final dims = _irisTypicalDimensions!;
      factors.add(
        'Typical dimensions considered: ${dims.length.toStringAsFixed(0)} x ${dims.width.toStringAsFixed(0)} x ${dims.height.toStringAsFixed(0)} cm.',
      );
    }
    if (_senderEnteredWeightKg != null && _senderEnteredWeightKg! > 0) {
      factors.add(
        'Sender-entered weight considered: ${_formatWeight(_senderEnteredWeightKg!)}kg.',
      );
    }
    if (_irisImageInsight != null) {
      factors.add('Parcel photo reviewed for handling and weight context.');
    }
    if (_irisHistoricalVerifiedWeightKg != null) {
      factors.add(
        'Similar completed deliveries were previously verified around ${_formatWeight(_irisHistoricalVerifiedWeightKg!)}kg.',
      );
    }
    if (_irisWeightConflict()) {
      factors.add('Entered weight and IRIS estimate differ enough for review.');
    }
    if (_irisBundleDetected(_description.text)) {
      factors.add(_irisBundlePrompt);
    }
    final vehicleDecision = _irisVehicleDecision();
    factors.add(
      'Recommended vehicle: ${vehicleDecision['recommendedVehicle']}. ${vehicleDecision['vehicleReason']}',
    );
    final flags = _irisDeliveryFlags();
    if (flags.contains('vanguard_required')) {
      factors.add(
          'Vanguard is recommended because this delivery has trust-sensitive flags.');
    }
    if (flags.contains('admin_review_required')) {
      factors.add(
          'Admin review is recommended before final authority is applied.');
    }
    return factors.toList(growable: false);
  }

  String _irisReasoningSummary() {
    final weight = _deliveryClassification.finalWeightKg > 0
        ? _deliveryClassification.finalWeightKg
        : (_irisEstimatedWeightKg ?? 0);
    return 'IRIS estimated this delivery at ${_formatWeight(weight)}kg because ${_irisReasoningFactors().take(3).join(' ')}';
  }

  Map<String, dynamic> _irisDeliveryEstimateDocument({
    required String estimateId,
    required String bookingId,
    required Map<String, dynamic> parcelPhotoData,
  }) {
    final user = _senderUser ?? FirebaseAuth.instance.currentUser;
    final canonicalDecision = _canonicalDeliveryDecision;
    final flags = _irisDeliveryFlags();
    final vehicleDecision = _irisVehicleDecision();
    final requiresVanguard = flags.contains('vanguard_required');
    final requiresAdminReview = flags.contains('admin_review_required');
    final hasPhoto = parcelPhotoData['hasPhoto'] == true ||
        _parcelPhoto != null ||
        _irisImageInsight != null;
    return {
      'estimateId': estimateId,
      'bookingId': bookingId,
      'userId': user?.uid ?? 'web-sender',
      'itemName': _irisMatchedItemName ?? _description.text.trim(),
      'itemHint': _irisMatchedItemName,
      'description': _description.text.trim(),
      'quantity': _irisQuantity < 1 ? 1 : _irisQuantity,
      'userWeightKg': _senderEnteredWeightKg,
      'userDimensions': _irisTypicalDimensions == null
          ? null
          : {
              'lengthCm': _irisTypicalDimensions!.length,
              'widthCm': _irisTypicalDimensions!.width,
              'heightCm': _irisTypicalDimensions!.height,
            },
      'irisWeightKg': _irisEstimatedWeightKg,
      'finalBillableWeightKg': canonicalDecision.finalPricingWeightKg,
      'confidenceScore': canonicalDecision.confidenceScore,
      'confidenceBand': canonicalDecision.confidenceBand,
      'reasoningSummary': canonicalDecision.explanation,
      'reasoningFactors': _irisReasoningFactors(),
      'canonicalDeliveryDecision': canonicalDecision.toJson(),
      'matchedRepositoryItems': [
        if ((_irisMatchedItemName ?? '').trim().isNotEmpty)
          {
            'name': _irisMatchedItemName,
            'weightKg': _irisEstimatedWeightKg,
            'source': _irisWeightSource,
            'truthBand': _irisTruthBand(),
          },
      ],
      'suggestedVehicle': canonicalDecision.recommendedVehicle.toLowerCase(),
      'recommendedVehicle': canonicalDecision.recommendedVehicle.toLowerCase(),
      'minimumVehicle': vehicleDecision['minimumVehicle'],
      'vehicleReason': canonicalDecision.vehicleReason,
      'vehicleConfidence': canonicalDecision.confidenceScore,
      'vehicleDisqualifiers': vehicleDecision['vehicleDisqualifiers'],
      'vehicleFlags': vehicleDecision['vehicleFlags'],
      'vehicleDecisionSource': vehicleDecision['vehicleDecisionSource'],
      'adminVehicleOverride': vehicleDecision['adminVehicleOverride'],
      'overrideReason': vehicleDecision['overrideReason'],
      'overrideBy': vehicleDecision['overrideBy'],
      'overrideAt': vehicleDecision['overrideAt'],
      'flags': flags,
      'requiresVanguard': requiresVanguard,
      'requiresAdminReview': requiresAdminReview,
      'bundleDetected': _irisBundleDetected(_description.text),
      'itemBreakdownPrompt':
          _irisBundleDetected(_description.text) ? _irisBundlePrompt : null,
      'photoSupplied': hasPhoto,
      'photoAnalysis': _irisImageInsight?.toJson(),
      'riderVerificationStatus': 'pending_pickup',
      'adminReviewStatus': requiresAdminReview ? 'open' : 'not_required',
      'createdAt': FieldValue.serverTimestamp(),
      'updatedAt': FieldValue.serverTimestamp(),
    };
  }

  bool _containsAny(String text, Iterable<String> needles) {
    return needles.any(text.contains);
  }

  bool _looksHighValue(String text, String category) {
    final combined = '$text $category'.toLowerCase();
    return _containsAny(combined, const [
      'iphone',
      'phone',
      'macbook',
      'laptop',
      'camera',
      'watch',
      'jewellery',
      'jewelry',
      'console',
      'playstation',
      'xbox',
      'designer',
      'gold',
      'diamond',
    ]);
  }

  String _formatWeight(double weightKg) {
    return weightKg.truncateToDouble() == weightKg
        ? weightKg.toStringAsFixed(0)
        : weightKg.toStringAsFixed(1);
  }

  Future<void> _confirmPayment() async {
    if (!_hasValidatedRoute) {
      setState(() {
        _checkoutState = _CheckoutState.failed;
        _firebaseError = _locationValidationMessage;
        _step = _SenderStep.details;
      });
      return;
    }
    if (!_hasConfirmedWeight) {
      setState(() {
        _checkoutState = _CheckoutState.failed;
        _weightMessage = 'Confirm parcel weight before payment.';
        _step = _SenderStep.details;
      });
      return;
    }
    if (!_hasConsistentDispatchClassification) {
      final classification = _deliveryClassification;
      _confirmWeight(
        classification.finalWeightKg,
        source: classification.selectedWeightSource,
        reason: classification.resolutionReason,
        verificationRequired: true,
      );
      if (!_hasConsistentDispatchClassification) {
        setState(() {
          _checkoutState = _CheckoutState.failed;
          _firebaseError =
              'This delivery needs recalculation because weight, vehicle, and pricing do not match.';
          _step = _SenderStep.details;
        });
        return;
      }
    }
    final id =
        'CIR-${DateTime.now().millisecondsSinceEpoch.toString().substring(7)}';
    setState(() {
      _checkoutState = _CheckoutState.processingPayment;
      _activeOrderId = id;
      _activeRequestDocId = id;
      _broadcasting = false;
      _statusIndex = 0;
      _firebaseError = null;
    });

    try {
      await _ensureFirebaseReady();
      final db = FirebaseFirestore.instance;
      final parcelPhotoData = await _uploadParcelPhoto(id);
      final request = _requestPayload(id, parcelPhotoData);
      final irisEstimate = _irisDeliveryEstimateDocument(
        estimateId: id,
        bookingId: id,
        parcelPhotoData: parcelPhotoData,
      );
      request['irisDeliveryEstimateId'] = id;
      request['irisDeliveryEstimate'] = irisEstimate;
      request['irisDeliveryFlags'] = irisEstimate['flags'];
      request['irisReasoningFactors'] = irisEstimate['reasoningFactors'];
      request['irisConfidenceBand'] = irisEstimate['confidenceBand'];
      request['irisRequiresAdminReview'] = irisEstimate['requiresAdminReview'];
      request['irisRequiresVanguard'] = irisEstimate['requiresVanguard'];
      final paymentResult = await _collectDeliveryPayment(id, _quoteTotal);
      request.addAll(paymentResult);
      _activeVanguardData = request['vanguardEnabled'] == true
          ? Map<String, dynamic>.from(request)
          : null;
      _activeRequestData = Map<String, dynamic>.from(request);
      final senderId = '${request['senderId']}';
      final batch = db.batch();
      batch.set(db.collection('webSenderRequests').doc(id), request);
      batch.set(db.collection('deliveryRequests').doc(id), request);
      batch.set(
        db.collection('irisDeliveryEstimates').doc(id),
        irisEstimate,
        SetOptions(merge: true),
      );
      batch.set(
          db.collection('chats').doc(id),
          {
            'threadId': id,
            'bookingId': id,
            'requestId': id,
            'participants': [senderId, 'circum-support'],
            'participantRoles': {senderId: 'sender', 'circum-support': 'admin'},
            'lastMessage':
                'Your request is live. Iris is checking nearby riders now.',
            'lastMessageTimestamp': FieldValue.serverTimestamp(),
            'unreadBy': ['admin'],
            'updatedAt': FieldValue.serverTimestamp(),
            'source': 'circum-web',
          },
          SetOptions(merge: true));
      batch.set(db.collection('chats').doc(id).collection('messages').doc(), {
        'threadId': id,
        'bookingId': id,
        'requestId': id,
        'senderId': senderId,
        'senderRole': 'system',
        'senderType': 'support',
        'recipientId': senderId,
        'recipientType': 'sender',
        'messageText':
            'Your request is live. Iris is checking nearby riders now.',
        'message': 'Your request is live. Iris is checking nearby riders now.',
        'readBy': [senderId],
        'system': true,
        'status': 'sent',
        'createdAt': FieldValue.serverTimestamp(),
        'timeStamp': DateTime.now().toIso8601String(),
      });
      await batch.commit();
      _listenToRequest(id);
      _listenToChat(id);
      if (!mounted) return;
      setState(() {
        _checkoutState = _CheckoutState.matchingRiders;
        _broadcasting = true;
        _firebaseOnline = true;
        _step = _SenderStep.tracking;
      });
    } on StateError catch (error) {
      debugPrint('Delivery checkout/payment error: $error');
      if (!mounted) return;
      final message = error.message.isNotEmpty
          ? error.message
          : 'We could not start payment just now. Please try again.';
      setState(() {
        _checkoutState = _CheckoutState.failed;
        _broadcasting = false;
        _firebaseOnline = true;
        _firebaseError = message;
      });
    } catch (error) {
      debugPrint('Delivery checkout/save error: $error');
      if (!mounted) return;
      setState(() {
        _checkoutState = _CheckoutState.failed;
        _broadcasting = false;
        _firebaseOnline = false;
        _firebaseError =
            'We could not save this delivery just now. Please try again.';
      });
    }
  }

  Future<Map<String, dynamic>> _collectDeliveryPayment(
    String requestId,
    double total,
  ) async {
    final user = _senderUser ?? FirebaseAuth.instance.currentUser;
    if (user == null) throw StateError('Sign in to pay for this delivery.');
    final rothApplied = math.min(math.max(0, _senderRothBalance), total);
    final cardRemaining = double.parse(
      math.max(0, total - rothApplied).toStringAsFixed(2),
    );
    if (rothApplied >= total && total > 0) {
      await FirebaseFunctions.instance.httpsCallable('applyCheckoutRoth').call({
        'amount': rothApplied,
        'referenceId': requestId,
        'service': 'delivery',
      });
      return {
        'paymentStatus': 'paid',
        'paidByRoth': true,
        'rothApplied': rothApplied,
        'walletContributionGbp': rothApplied,
        'cardRemaining': 0,
        'stripeAmount': 0,
      };
    }
    var cardPaymentCompleted = false;
    var rothDebited = false;
    if (cardRemaining > 0) {
      try {
        Stripe.publishableKey = Env.publishableLiveKey;
        await Stripe.instance.applySettings();
        final response = await http.post(
          Uri.parse(
            'https://us-central1-circum-2797c.cloudfunctions.net/createPaymentIntent',
          ),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'currency': 'gbp',
            'amount': (cardRemaining * 100).round(),
            'pushToken': '',
            'email': user.email,
            'name': _senderName.text.trim(),
            'userId': user.uid,
            'saveCard': false,
            'useWallet': false,
            'referenceId': requestId,
          }),
        );
        final data = jsonDecode(response.body) as Map<String, dynamic>;
        final clientSecret = '${data['clientSecret'] ?? ''}';
        if (clientSecret.isEmpty || data['error'] != null) {
          throw StateError(
              '${data['error'] ?? 'Could not start card payment.'}');
        }
        await Stripe.instance.initPaymentSheet(
          paymentSheetParameters: SetupPaymentSheetParameters(
            paymentIntentClientSecret: clientSecret,
            merchantDisplayName: 'Circum',
            style: ThemeMode.dark,
          ),
        );
        await Stripe.instance.presentPaymentSheet();
        cardPaymentCompleted = true;
        if (rothApplied > 0) {
          await FirebaseFunctions.instance
              .httpsCallable('applyCheckoutRoth')
              .call({
            'amount': rothApplied,
            'referenceId': requestId,
            'service': 'delivery',
          });
          rothDebited = true;
        }
      } catch (error) {
        debugPrint('Delivery card payment setup failed: $error');
        throw StateError(
            'We could not start card payment just now. Please try again.');
      }
    }
    return {
      'paymentStatus': cardRemaining <= 0 || cardPaymentCompleted
          ? 'paid'
          : 'payment_pending',
      'paidByRoth': cardRemaining <= 0,
      'rothApplied': rothDebited ? rothApplied : 0,
      'walletContributionGbp': rothDebited ? rothApplied : 0,
      'cardRemaining': cardRemaining,
      'stripeAmount': cardRemaining,
    };
  }

  Future<void> _bookHealthPlus() async {
    String? validationMessage;
    if (_healthName.text.trim().isEmpty) {
      validationMessage = 'Add your full name to continue.';
    } else if (_healthPhone.text.trim().isEmpty) {
      validationMessage = 'Add a phone number for pickup updates.';
    } else if (_healthEmail.text.trim().isEmpty) {
      validationMessage = 'Add an email address for your receipt.';
    } else if (_healthPharmacy.text.trim().isEmpty) {
      validationMessage = 'Add the pharmacy pickup address.';
    } else if (_healthDelivery.text.trim().isEmpty) {
      validationMessage = 'Add the delivery address.';
    } else if (_healthPrescriptionType.trim().isEmpty) {
      validationMessage = 'Choose the prescription type.';
    } else if (_healthFrequency == HealthPlusFrequency.custom &&
        _healthCustomSchedule.text.trim().isEmpty) {
      validationMessage = 'Add the custom pickup date or repeat pattern.';
    } else if (!_healthConsent) {
      validationMessage =
          'Please confirm the consent box before booking Health+.';
    }

    if (_healthSubmitting) return;
    if (validationMessage != null) {
      setState(() => _healthMessage = validationMessage);
      return;
    }

    final now = DateTime.now();
    final senderId = _senderUser?.uid ?? FirebaseAuth.instance.currentUser?.uid;
    final id = 'HP-${now.millisecondsSinceEpoch.toString().substring(6)}';
    final scheduleId = _healthFrequency == HealthPlusFrequency.oneOff
        ? null
        : 'HPS-${now.millisecondsSinceEpoch.toString().substring(6)}';
    final pickupId =
        'HPP-${now.millisecondsSinceEpoch.toString().substring(6)}';
    final quote = _healthQuote;

    setState(() {
      _healthSubmitting = true;
      _healthMessage = 'Saving your Health+ pickup and preparing payment...';
      _firebaseError = null;
    });

    try {
      await _ensureFirebaseReady();
      final db = FirebaseFirestore.instance;
      final batch = db.batch();
      final profileRef = db.collection('healthPlusProfiles').doc(id);
      final pickupRef = db.collection('prescriptionPickups').doc(pickupId);
      final planDefinition = switch (_healthSubscriptionPlan) {
        'priority' => (25.0, 4, 6.25),
        'family' => (40.0, null, null),
        'custom' => (60.0, 0, null),
        _ => (15.0, 2, 7.5),
      };

      final profile = {
        'id': id,
        'senderId': senderId,
        'userId': senderId,
        'fullName': _healthName.text.trim(),
        'phoneNumber': _healthPhone.text.trim(),
        'email': _healthEmail.text.trim(),
        'pharmacyName': _healthPharmacyName.text.trim(),
        'pharmacyAddress': _healthPharmacy.text.trim(),
        'deliveryAddress': _healthDelivery.text.trim(),
        'notes': _healthNotes.text.trim(),
        'prescriptionNotes': _healthNotes.text.trim(),
        'prescriptionType': _healthPrescriptionType,
        'subscriptionPlan': _healthSubscriptionPlan,
        'healthPlusPlan': _healthSubscriptionPlan,
        'planType': _healthSubscriptionPlan,
        'monthlyPrice': planDefinition.$1,
        'includedDeliveries': planDefinition.$2,
        'usedDeliveriesThisCycle': 0,
        'remainingDeliveriesThisCycle': planDefinition.$2,
        'subscriptionStatus': scheduleId == null ? 'one_off' : 'active',
        'preferredRiderId': null,
        'preferredRiderName': null,
        'customIncludedDeliveries':
            _healthSubscriptionPlan == 'custom' ? 0 : null,
        'customOverageRate': null,
        'overageRate': planDefinition.$3,
        'isVanguard': true,
        'trustPoints': 6,
        'preferredDay': _healthPreferredDay.text.trim(),
        'preferredTime': _healthPreferredTime.text.trim(),
        'preferredPickupDay': _healthPreferredDay.text.trim(),
        'preferredPickupTime': _healthPreferredTime.text.trim(),
        'frequency': _healthFrequency.value,
        'recurring': scheduleId != null,
        'customSchedule': _healthCustomSchedule.text.trim(),
        'priorityRiderMatching': _healthSubscriptionPlan == 'priority',
        'consentConfirmed': _healthConsent,
        'consentAccepted': _healthConsent,
        'status': scheduleId == null ? 'one_off' : 'active',
        'source': 'circum-web',
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      };
      final pickup = {
        'id': pickupId,
        'senderId': senderId,
        'userId': senderId,
        'profileId': id,
        'scheduleId': scheduleId,
        'fullName': _healthName.text.trim(),
        'phoneNumber': _healthPhone.text.trim(),
        'pharmacyName': _healthPharmacyName.text.trim(),
        'pharmacyAddress': _healthPharmacy.text.trim(),
        'deliveryAddress': _healthDelivery.text.trim(),
        'notes': _healthNotes.text.trim(),
        'prescriptionNotes': _healthNotes.text.trim(),
        'prescriptionType': _healthPrescriptionType,
        'subscriptionPlan': _healthSubscriptionPlan,
        'healthPlusPlan': _healthSubscriptionPlan,
        'planType': _healthSubscriptionPlan,
        'isVanguard': true,
        'trustPoints': 6,
        'riskStatus': 'scheduled',
        'preferredDay': _healthPreferredDay.text.trim(),
        'preferredTime': _healthPreferredTime.text.trim(),
        'consentAccepted': _healthConsent,
        'preferredPickupTime': _healthPreferredTime.text.trim(),
        'preferredPickupDay': _healthPreferredDay.text.trim(),
        'scheduledPickupDate': _healthPreferredDay.text.trim(),
        'scheduledPickupWindow': _healthPreferredTime.text.trim(),
        'scheduledDropoffDate': _healthPreferredDay.text.trim(),
        'scheduledDropoffWindow': _healthPreferredTime.text.trim(),
        'frequency': _healthFrequency.value,
        'recurring': scheduleId != null,
        'customSchedule': _healthCustomSchedule.text.trim(),
        'priorityRiderMatching': _healthSubscriptionPlan == 'priority',
        'status': PickupStatus.scheduled.value,
        'price': quote.total,
        'currency': 'GBP',
        'pricingBreakdown': quote.toJson(),
        'type': 'health_plus_prescription_pickup',
        'source': 'circum-web',
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
