        const SizedBox(height: 18),
        _LuxuryGlassSurface(
          colors: colors,
          glow: hasDriver ? const Color(0xff22c55e) : colors.adminAccent,
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              hasDriver
                  ? _RiderAvatar(
                      colors: colors,
                      name: delivery.assignedDriverName,
                      photoUrl: delivery.assignedDriverPhotoUrl,
                      size: 46,
