class _SenderAccessGate extends StatefulWidget {
  final _CircumColors colors;
  final bool signupMode;
  final bool busy;
  final String? message;
  final TextEditingController email;
  final TextEditingController password;
  final TextEditingController fullName;
  final TextEditingController phone;
  final VoidCallback onToggleMode;
  final VoidCallback onSignIn;
  final VoidCallback onSignUp;
  final VoidCallback onGoogleSignIn;
  final VoidCallback onAppleSignIn;
  final VoidCallback onForgotPassword;

  const _SenderAccessGate({
    required this.colors,
    required this.signupMode,
    required this.busy,
    required this.message,
    required this.email,
    required this.password,
    required this.fullName,
    required this.phone,
    required this.onToggleMode,
    required this.onSignIn,
    required this.onSignUp,
    required this.onGoogleSignIn,
    required this.onAppleSignIn,
    required this.onForgotPassword,
  });

  @override
  State<_SenderAccessGate> createState() => _SenderAccessGateState();
}

class _SenderAccessGateState extends State<_SenderAccessGate> {
  final _identifier = TextEditingController();
  bool _detailsVisible = false;
  bool _checkingAccount = false;
  bool _passwordVisible = false;
  String? _localMessage;
  String? _lastLoginMethod;
  String? _lastLoginHint;

  @override
  void initState() {
    super.initState();
    _lastLoginMethod = html.window.localStorage['lastLoginMethod'];
    _lastLoginHint = html.window.localStorage['lastLoginHint'];
    _identifier.addListener(_handleIdentifierChanged);
  }

  @override
  void dispose() {
    _identifier.removeListener(_handleIdentifierChanged);
    _identifier.dispose();
    super.dispose();
  }

  void _handleIdentifierChanged() {
    if (mounted) setState(() {});
  }

  bool get _identifierValid {
    final value = _identifier.text.trim();
    return value.contains('@')
        ? RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$').hasMatch(value)
        : RegExp(r'^\+?[0-9\s()\-]{8,}$').hasMatch(value);
  }

  bool get _identifierIsEmail => _identifier.text.trim().contains('@');

  Future<void> _continue() async {
    final value = _identifier.text.trim();
    if (!_identifierValid) {
      setState(
          () => _localMessage = 'Enter a valid email address or phone number.');
      return;
    }
    setState(() {
      _checkingAccount = true;
      _localMessage = 'Checking your account...';
    });
    if (_identifierIsEmail) {
      widget.email.text = value;
      var existingAccount = false;
      try {
        final auth = FirebaseAuth.instance;
        // ignore: deprecated_member_use
        final methods = await auth.fetchSignInMethodsForEmail(value);
        if (!mounted) return;
        existingAccount = methods.isNotEmpty;
      } catch (_) {
        if (!mounted) return;
      }
      if (existingAccount && widget.signupMode) {
        widget.onToggleMode();
      } else if (!existingAccount && !widget.signupMode) {
        widget.onToggleMode();
      }
      setState(() {
        _checkingAccount = false;
        _detailsVisible = true;
        _localMessage = existingAccount ? 'Welcome back 👋' : null;
      });
      return;
    }
    widget.phone.text = value;
    if (!widget.signupMode) {
      widget.onToggleMode();
    }
    setState(() {
      _checkingAccount = false;
      _detailsVisible = true;
      _localMessage = 'Add your email to create your Circum account.';
    });
  }

  @override
  Widget build(BuildContext context) {
    final colors = widget.colors;
    final message = _localMessage ?? widget.message;
    return SizedBox(
      width: double.infinity,
      height: MediaQuery.sizeOf(context).height,
