class _BusinessAccountsStep extends StatelessWidget {
  final _CircumColors colors;
  final List<Map<String, dynamic>> accounts;
  final List<SenderDeliveryRecord> deliveries;
  final TextEditingController businessName;
  final TextEditingController companyNumber;
  final TextEditingController contactName;
  final TextEditingController contactEmail;
  final TextEditingController phone;
  final TextEditingController billingEmail;
  final TextEditingController businessAddress;
  final TextEditingController teamEmail;
  final TextEditingController teamName;
  final String teamRole;
  final TextEditingController costCentre;
  final TextEditingController reference;
  final String? message;
  final VoidCallback onBack;
  final VoidCallback onCreate;
  final ValueChanged<String> onTeamRole;
  final ValueChanged<Map<String, dynamic>> onAddTeamMember;
  final void Function(Map<String, dynamic>, Map<String, dynamic>)
      onRemoveTeamMember;
  final ValueChanged<Map<String, dynamic>> onBookDelivery;

  const _BusinessAccountsStep({
    super.key,
    required this.colors,
    required this.accounts,
    required this.deliveries,
    required this.businessName,
    required this.companyNumber,
    required this.contactName,
    required this.contactEmail,
    required this.phone,
    required this.billingEmail,
    required this.businessAddress,
    required this.teamEmail,
    required this.teamName,
    required this.teamRole,
    required this.costCentre,
    required this.reference,
    required this.message,
    required this.onBack,
    required this.onCreate,
    required this.onTeamRole,
    required this.onAddTeamMember,
    required this.onRemoveTeamMember,
    required this.onBookDelivery,
  });

  @override
  Widget build(BuildContext context) {
    final businessDeliveries = deliveries
        .where((delivery) => delivery.serviceType.toUpperCase() == 'BUSINESS')
        .toList(growable: false);
    final desktop = MediaQuery.sizeOf(context).width >= 940;
    return Container(
      width: double.infinity,
      constraints: BoxConstraints(
        minHeight: MediaQuery.sizeOf(context).height,
      ),
      color: const Color(0xff07090f),
      child: Stack(
        children: [
          const Positioned(
            top: -170,
            right: -150,
            child: _BusinessGlow(size: 420, color: Color(0xff3b82f6)),
          ),
          const Positioned(
            bottom: -170,
            left: -130,
            child: _BusinessGlow(size: 360, color: Color(0xff8b5cf6)),
          ),
          SingleChildScrollView(
            padding: EdgeInsets.fromLTRB(
              desktop ? 26 : 18,
              18,
              desktop ? 26 : 18,
              34,
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    IconButton(
                      tooltip: 'Back',
                      onPressed: onBack,
                      icon: const Icon(Icons.arrow_back_rounded,
                          color: Colors.white),
                    ),
                    const SizedBox(width: 8),
                    Image.asset(
                      'assets/images/circum_wordmark.png',
                      width: 126,
                      height: 30,
                      fit: BoxFit.contain,
                    ),
                    const Spacer(),
                    const _BusinessBadge('BUSINESS'),
                  ],
                ),
                const SizedBox(height: 26),
                const _BusinessEyebrow('Business · Account overview'),
                const SizedBox(height: 10),
                Text(
                  'Your business command centre.',
                  style: GoogleFonts.dmSerifDisplay(
                    color: Colors.white,
                    fontSize: desktop ? 52 : 39,
                    height: 1.02,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  'Create and manage company profiles, team access, business deliveries, invoices, and the Circum ecosystem from one account.',
                  style: GoogleFonts.inter(
                    color: Colors.white.withValues(alpha: 0.72),
                    height: 1.5,
                    fontWeight: FontWeight.w600,
                  ),
                ),
                const SizedBox(height: 22),
                const _BusinessStatsGrid(),
                const SizedBox(height: 16),
                LayoutBuilder(
                  builder: (context, constraints) {
                    final stack = constraints.maxWidth < 900;
                    final ecosystem = _BusinessGlass(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: const [
                          _BusinessPanelHeader(
                            title: 'Your Circum ecosystem',
                            subtitle:
                                'Business deliveries reuse the same Circum movement engine.',
                          ),
                          SizedBox(height: 18),
                          _BusinessEcosystemHub(),
                        ],
                      ),
                    );
                    final side = Column(
                      children: [
                        const _BusinessInvoiceCard(),
                        const SizedBox(height: 14),
                        const _BusinessTeamCard(),
                      ],
                    );
                    if (stack) {
                      return Column(
                        children: [
                          ecosystem,
                          const SizedBox(height: 14),
                          side,
                        ],
                      );
                    }
                    return Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(flex: 7, child: ecosystem),
                        const SizedBox(width: 14),
                        Expanded(flex: 4, child: side),
                      ],
                    );
                  },
                ),
                const SizedBox(height: 16),
                const _BusinessActivityTable(),
                const SizedBox(height: 16),
                _BusinessGlass(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const _BusinessPanelHeader(
                        title: 'Create Business Account',
                        subtitle:
                            'Set up a company profile. Circum admin approves accounts before business booking is enabled.',
                      ),
                      const SizedBox(height: 14),
                      _InputBox(
                          colors: colors,
                          controller: businessName,
                          hint: 'Business name',
                          glassStyle: true),
                      const SizedBox(height: 10),
                      _InputBox(
                          colors: colors,
                          controller: companyNumber,
                          hint: 'Company number (optional)',
                          glassStyle: true),
                      const SizedBox(height: 10),
                      _InputBox(
                          colors: colors,
                          controller: contactName,
                          hint: 'Contact name',
                          glassStyle: true),
                      const SizedBox(height: 10),
                      _InputBox(
                          colors: colors,
                          controller: contactEmail,
                          hint: 'Contact email',
                          glassStyle: true),
                      const SizedBox(height: 10),
                      _InputBox(
                          colors: colors,
                          controller: phone,
                          hint: 'Phone',
                          glassStyle: true),
                      const SizedBox(height: 10),
                      _InputBox(
                          colors: colors,
                          controller: billingEmail,
                          hint: 'Billing email',
                          glassStyle: true),
                      const SizedBox(height: 10),
                      _AddressField(
                        colors: colors,
                        icon: Icons.business_outlined,
                        label: 'Business address',
                        controller: businessAddress,
                        glassStyle: true,
                        onSelected: (address) =>
                            businessAddress.text = address.displayAddress,
                      ),
                      const SizedBox(height: 14),
                      FilledButton.icon(
                        onPressed: onCreate,
                        icon: const Icon(Icons.add_business),
                        label: const Text('Create Business Account'),
                      ),
                    ],
                  ),
                ),
                if (message != null && message!.trim().isNotEmpty) ...[
                  const SizedBox(height: 12),
                  _BusinessGlass(
                    child: Text(
                      message!,
                      style: GoogleFonts.inter(
                        color: Colors.white,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                ],
                const SizedBox(height: 14),
                if (accounts.isEmpty)
                  _BusinessGlass(
                    child: Text(
                      'No business accounts yet.',
                      style: GoogleFonts.inter(
                        color: Colors.white.withValues(alpha: 0.68),
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  )
                else
                  ...accounts.map(
                    (account) => Padding(
                      padding: const EdgeInsets.only(bottom: 14),
                      child: _businessAccountCard(account, businessDeliveries),
                    ),
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _businessAccountCard(
    Map<String, dynamic> account,
    List<SenderDeliveryRecord> businessDeliveries,
  ) {
    final status = '${account['status'] ?? 'pending'}';
    final defaultPickupAddresses =
        ((account['defaultPickupAddresses'] as List?) ?? const [])
            .map((item) => '$item')
            .where((item) => item.trim().isNotEmpty)
            .toList(growable: false);
    final members = ((account['teamMembers'] as List?) ?? const [])
        .whereType<Map>()
        .map((item) => Map<String, dynamic>.from(item))
        .toList(growable: false);
    final recent = businessDeliveries.take(3).toList(growable: false);
    return _GlassPanel(
      colors: colors,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  '${account['businessName'] ?? 'Business'}',
                  style: TextStyle(
                    color: colors.text,
                    fontSize: 24,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Chip(label: Text(status)),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            '${account['contactEmail'] ?? account['billingEmail'] ?? ''}',
            style:
                TextStyle(color: colors.mutedText, fontWeight: FontWeight.w700),
          ),
          if (defaultPickupAddresses.isNotEmpty) ...[
            const SizedBox(height: 8),
            Text(
              'Default pickup: ${defaultPickupAddresses.first}',
              style: TextStyle(
                  color: colors.mutedText, fontWeight: FontWeight.w700),
            ),
          ],
          const SizedBox(height: 14),
          Wrap(
            spacing: 10,
            runSpacing: 10,
            children: [
              _MetricPill(
                  colors: colors, label: 'Team', value: '${members.length}'),
              _MetricPill(
                colors: colors,
                label: 'Recent',
                value: '${recent.length}',
              ),
              _MetricPill(
                  colors: colors, label: 'Monthly spend', value: 'Soon'),
            ],
          ),
          const SizedBox(height: 14),
          _SectionTitle(colors: colors, title: 'Book business delivery'),
          const SizedBox(height: 10),
          _InputBox(
              colors: colors,
              controller: costCentre,
              hint: 'Cost centre (optional)',
              glassStyle: true),
          const SizedBox(height: 10),
          _InputBox(
              colors: colors,
              controller: reference,
              hint: 'Reference (optional)',
              glassStyle: true),
          const SizedBox(height: 10),
          FilledButton.icon(
            onPressed:
                status == 'approved' ? () => onBookDelivery(account) : null,
            icon: const Icon(Icons.local_shipping_outlined),
            label: const Text('Book business delivery'),
          ),
          if (status != 'approved') ...[
            const SizedBox(height: 8),
            Text(
              'Business booking unlocks after admin approval.',
              style: TextStyle(
                  color: colors.mutedText, fontWeight: FontWeight.w700),
            ),
          ],
          const SizedBox(height: 16),
          _SectionTitle(colors: colors, title: 'Team members'),
          const SizedBox(height: 8),
          ...members.map(
            (member) => ListTile(
              contentPadding: EdgeInsets.zero,
              title: Text(
                '${member['name'] ?? member['email'] ?? 'Team member'}',
                style:
                    TextStyle(color: colors.text, fontWeight: FontWeight.w800),
              ),
              subtitle: Text(
                '${member['email'] ?? ''} · ${member['role'] ?? 'member'} · ${member['status'] ?? 'active'}',
                style: TextStyle(color: colors.mutedText),
              ),
              trailing: IconButton(
                icon: const Icon(Icons.remove_circle_outline),
                onPressed: () => onRemoveTeamMember(account, member),
              ),
            ),
          ),
          const SizedBox(height: 8),
          _InputBox(
              colors: colors,
              controller: teamEmail,
              hint: 'Team member email',
              glassStyle: true),
          const SizedBox(height: 10),
          _InputBox(
              colors: colors,
              controller: teamName,
              hint: 'Team member name',
              glassStyle: true),
          const SizedBox(height: 10),
          Wrap(
            spacing: 8,
            children: ['owner', 'admin', 'member']
                .map(
                  (role) => ChoiceChip(
                    selected: teamRole == role,
                    label: Text(role),
                    onSelected: (_) => onTeamRole(role),
                  ),
                )
                .toList(),
          ),
          const SizedBox(height: 10),
          OutlinedButton.icon(
            onPressed: () => onAddTeamMember(account),
            icon: const Icon(Icons.person_add_alt),
            label: const Text('Add team member'),
          ),
          const SizedBox(height: 16),
          _SectionTitle(colors: colors, title: 'Recent business deliveries'),
          const SizedBox(height: 8),
          if (recent.isEmpty)
            Text(
              'Business deliveries will appear here after booking.',
              style: TextStyle(
                  color: colors.mutedText, fontWeight: FontWeight.w700),
            )
          else
            ...recent.map(
              (delivery) => Text(
                '${delivery.requestId} · ${delivery.status}',
                style:
                    TextStyle(color: colors.text, fontWeight: FontWeight.w700),
              ),
            ),
        ],
      ),
    );
  }
}

