            const SizedBox(height: 10),
            _InputBox(colors: colors, controller: phone, hint: 'Phone number'),
            const SizedBox(height: 10),
            _InputBox(colors: colors, controller: email, hint: 'Email address'),
            const SizedBox(height: 10),
