    return switch (tabIndex) {
      0 => _profileTab(summary),
      1 => _historyTab(),
      2 => _addressesTab(),
      3 => _paymentsTab(),
      4 => _reviewsTab(),
      5 => _supportTab(),
      _ => _settingsTab(context, summary),
    };
