  Future<void> _confirmSignOut(BuildContext context) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Are you sure you want to sign out?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Sign Out'),
          ),
        ],
      ),
    );
    if (confirmed == true) onSignOut();
  }

  Future<void> _showDeleteAccountRequest(BuildContext context) async {
    final confirm = TextEditingController();
    final requested = await showDialog<bool>(
      context: context,
      builder: (context) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: const Text('Delete account request'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Text(
                'This may permanently remove your account profile, saved addresses, wallet access and account data. Some records may be retained where required for legal, payment, fraud prevention or operational reasons.',
              ),
              const SizedBox(height: 12),
              TextField(
                controller: confirm,
                decoration: const InputDecoration(
                  labelText: 'Type DELETE to continue',
                ),
                onChanged: (_) => setDialogState(() {}),
              ),
              const SizedBox(height: 12),
              const Text(
                'Account deletion requests are handled by Circum Support while secure deletion is being finalised.',
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: confirm.text.trim() == 'DELETE'
                  ? () => Navigator.pop(context, true)
                  : null,
              child: const Text('Request account deletion'),
            ),
          ],
        ),
      ),
    );
    confirm.dispose();
    if (requested == true) onRequestDeletion();
  }

  Widget _empty(String title, String body) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            title,
            style: TextStyle(
              color: colors.text,
              fontSize: 18,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 6),
          Text(body, style: TextStyle(color: colors.mutedText, height: 1.45)),
        ],
      ),
    );
  }
}

class _ProfileNavItem extends StatelessWidget {
  final _CircumColors colors;
  final String label;
  final IconData icon;
  final bool selected;
  final VoidCallback onTap;

  const _ProfileNavItem({
    required this.colors,
    required this.label,
    required this.icon,
    required this.selected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return InkWell(
      borderRadius: BorderRadius.circular(22),
      onTap: onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 17),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(26),
          gradient: selected
              ? const LinearGradient(
                  colors: [
                    Color(0xff1dd6ff),
                    Color(0xff476cff),
                    Color(0xffa855f7),
                  ],
                )
              : LinearGradient(
                  colors: [
                    colors.field.withValues(alpha: 0.76),
                    Colors.white.withValues(alpha: colors.dark ? 0.08 : 0.56),
                  ],
                ),
          border: Border.all(
            color: selected
                ? Colors.white.withValues(alpha: 0.24)
                : Colors.white.withValues(alpha: 0.10),
          ),
          boxShadow: selected
              ? [
                  BoxShadow(
                    color: colors.adminGlow.withValues(alpha: 0.38),
                    blurRadius: 36,
                    spreadRadius: 2,
                    offset: const Offset(0, 16),
                  ),
                ]
              : null,
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(icon, color: Colors.white, size: 19),
            const SizedBox(width: 12),
            Text(
              label,
              style: TextStyle(
                color: Colors.white.withValues(alpha: selected ? 1 : 0.70),
                fontWeight: FontWeight.w900,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

