class _LiveDeliveryTrackingPanel extends StatelessWidget {
  final _CircumColors colors;
  final _ValidatedAddress? pickup;
  final _ValidatedAddress? dropoff;
  final Map<String, dynamic>? liveLocation;
  final int statusIndex;

  const _LiveDeliveryTrackingPanel({
    required this.colors,
    required this.pickup,
    required this.dropoff,
    required this.liveLocation,
    required this.statusIndex,
  });

  @override
  Widget build(BuildContext context) {
    final live = liveLocation;
    final riderLat = _num(live?['latitude']);
    final riderLng = _num(live?['longitude']);
    final updatedAt = _dateTimeFromFirestore(live?['updatedAt']);
    final fresh = updatedAt != null &&
        DateTime.now().difference(updatedAt).inSeconds <= 60;
    final hasLiveTracking = fresh &&
        pickup?.hasCoordinates == true &&
        dropoff?.hasCoordinates == true &&
        riderLat != null &&
        riderLng != null &&
        _coordinatesAreUsable(riderLat, riderLng);

    if (!hasLiveTracking) {
      return _GlassPanel(
        colors: colors,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.location_off, color: colors.warning),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    'Tracking temporarily unavailable',
                    style: TextStyle(
                      color: colors.text,
                      fontSize: 18,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              'Live GPS will appear when the assigned rider is travelling and has location enabled.',
              style: TextStyle(
                color: colors.mutedText,
                height: 1.35,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 14),
            _Timeline(colors: colors, activeIndex: statusIndex),
          ],
        ),
      );
    }

    final destination = statusIndex < 2 ? pickup! : dropoff!;
    final remainingMiles = _coordinateDistanceMiles(
          riderLat,
          riderLng,
          destination.lat,
          destination.lng,
        ) ??
        0;
    final etaMinutes = math.max(1, (remainingMiles / 18 * 60).round());
    final mapUrl = _staticLiveMapUrl(
      pickup: pickup!,
      dropoff: dropoff!,
      riderLat: riderLat,
      riderLng: riderLng,
    );

    return _GlassPanel(
      colors: colors,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.gps_fixed, color: colors.success),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  'Live rider location',
                  style: TextStyle(
                    color: colors.text,
                    fontSize: 18,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Text(
                'Updated ${_relativeSeconds(updatedAt)} ago',
                style: TextStyle(
                  color: colors.mutedText,
                  fontSize: 12,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          ClipRRect(
            borderRadius: BorderRadius.circular(18),
            child: AspectRatio(
              aspectRatio: 1.65,
              child: Image.network(
                mapUrl,
                fit: BoxFit.cover,
                errorBuilder: (context, error, stackTrace) =>
                    _Timeline(colors: colors, activeIndex: statusIndex),
              ),
            ),
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child: _RiderStatTile(
                  colors: colors,
                  label: 'Remaining',
                  value: '${remainingMiles.toStringAsFixed(1)} mi',
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: _RiderStatTile(
                  colors: colors,
                  label: 'Dynamic ETA',
                  value: '$etaMinutes min',
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  static double? _num(Object? value) {
    if (value is num) return value.toDouble();
    return double.tryParse('$value');
  }

  static DateTime? _dateTimeFromFirestore(Object? value) {
    if (value is Timestamp) return value.toDate();
    if (value is DateTime) return value;
    return null;
  }

  static String _relativeSeconds(DateTime updatedAt) {
    final seconds = DateTime.now().difference(updatedAt).inSeconds;
    if (seconds < 1) return 'now';
    return '${seconds}s';
  }

  static String _staticLiveMapUrl({
    required _ValidatedAddress pickup,
    required _ValidatedAddress dropoff,
    required double riderLat,
    required double riderLng,
  }) {
    final params = {
      'size': '900x540',
      'scale': '2',
      'maptype': 'roadmap',
      'markers': [
        'color:blue|label:P|${pickup.lat},${pickup.lng}',
        'color:green|label:D|${dropoff.lat},${dropoff.lng}',
        'color:red|label:R|$riderLat,$riderLng',
      ],
      'path':
          'color:0x2563ebff|weight:5|${pickup.lat},${pickup.lng}|$riderLat,$riderLng|${dropoff.lat},${dropoff.lng}',
      'key': _googlePlacesApiKey,
    };
    return Uri.https(
      'maps.googleapis.com',
      '/maps/api/staticmap',
      params,
    ).toString();
  }
}

class _TrackingItemContext {
  final String description;
  final String irisItemName;
  final double weightKg;
  final String weightBand;
  final String vehicle;
  final bool fragile;
  final String handlingNotes;

  const _TrackingItemContext({
    required this.description,
    required this.irisItemName,
    required this.weightKg,
    required this.weightBand,
    required this.vehicle,
    required this.fragile,
    required this.handlingNotes,
  });

  factory _TrackingItemContext.fromRequest(
    Map<String, dynamic> data, {
    String? fallbackDescription,
    String? fallbackIrisItemName,
    required double fallbackWeightKg,
    required String fallbackWeightBand,
    required String fallbackVehicle,
  }) {
    final suitability =
        Map<String, dynamic>.from(data['vehicleSuitability'] ?? const {});
    return _TrackingItemContext(
      description: _firstNonEmpty([
        data['packageDescription'],
        data['originalDescription'],
        fallbackDescription,
      ]),
      irisItemName: _firstNonEmpty([
        data['irisMatchedItemName'],
        data['normalizedItemName'],
        fallbackIrisItemName,
      ]),
      weightKg: _doubleFromAny(data['finalWeightKg']) ??
          _doubleFromAny(data['finalWeightUsed']) ??
          _doubleFromAny(data['weightKg']) ??
          fallbackWeightKg,
      weightBand: _firstNonEmpty([
        data['finalWeightBand'],
        data['weightBand'],
        data['weightCategory'],
        fallbackWeightBand,
      ]),
      vehicle: _firstNonEmpty([
        data['irisRecommendedVehicle'],
        suitability['recommendedVehicle'],
        data['vehicleType'],
        data['vehicle'],
        fallbackVehicle,
      ]),
      fragile: data['fragile'] == true || suitability['fragile'] == true,
      handlingNotes: _firstNonEmpty([
        data['irisImageHandlingNotes'],
        suitability['handlingNotes'],
        data['specialHandlingNotes'],
      ]),
    );
  }

  factory _TrackingItemContext.fromDelivery(SenderDeliveryRecord delivery) {
    return _TrackingItemContext(
      description: delivery.parcelDescription,
      irisItemName: delivery.irisMatchedItemName,
      weightKg: delivery.parcelWeightKg,
      weightBand: delivery.weightBand,
      vehicle: delivery.recommendedVehicle,
      fragile: delivery.fragile,
      handlingNotes: delivery.handlingNotes,
    );
  }
}

