class _InputBox extends StatelessWidget {
  final _CircumColors colors;
  final TextEditingController controller;
  final String hint;
  final int maxLines;
  final bool obscureText;
  final bool enabled;
  final TextInputType? keyboardType;
  final bool glassStyle;
  final Widget? suffixIcon;
  final Iterable<String>? autofillHints;
  final TextInputAction? textInputAction;
  final ValueChanged<String>? onSubmitted;
  final String? semanticLabel;

  const _InputBox({
    required this.colors,
    required this.controller,
    required this.hint,
    this.maxLines = 1,
    this.obscureText = false,
    this.enabled = true,
    this.keyboardType,
    this.glassStyle = false,
    this.suffixIcon,
    this.autofillHints,
    this.textInputAction,
    this.onSubmitted,
    this.semanticLabel,
  });

  @override
  Widget build(BuildContext context) {
    final field = TextField(
      controller: controller,
      maxLines: maxLines,
      obscureText: obscureText,
      enabled: enabled,
      keyboardType: keyboardType,
      autofillHints: autofillHints,
      textInputAction: textInputAction,
      onSubmitted: onSubmitted,
      style: TextStyle(color: colors.text, fontWeight: FontWeight.w800),
      decoration: InputDecoration(
        hintText: hint,
        suffixIcon: suffixIcon,
        hintStyle: TextStyle(color: colors.mutedText),
        filled: !glassStyle,
        fillColor: colors.field,
        contentPadding: EdgeInsets.symmetric(
          horizontal: glassStyle ? 16 : 14,
          vertical: glassStyle ? 16 : 14,
        ),
        border: OutlineInputBorder(
          borderSide: BorderSide.none,
          borderRadius: BorderRadius.circular(glassStyle ? 22 : 16),
        ),
        enabledBorder: glassStyle
            ? InputBorder.none
            : OutlineInputBorder(
                borderSide: BorderSide.none,
                borderRadius: BorderRadius.circular(16),
              ),
        focusedBorder: glassStyle
            ? InputBorder.none
            : OutlineInputBorder(
                borderSide: BorderSide.none,
                borderRadius: BorderRadius.circular(16),
              ),
      ),
    );
    final labelledField = semanticLabel == null
        ? field
        : Semantics(label: semanticLabel, textField: true, child: field);
    if (!glassStyle) return labelledField;
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(22),
        gradient: LinearGradient(
          colors: [
            colors.adminAccent.withValues(alpha: 0.16),
            colors.field.withValues(alpha: 0.76),
          ],
        ),
        border: Border.all(color: colors.adminAccent.withValues(alpha: 0.22)),
        boxShadow: [
          BoxShadow(
            color: colors.adminGlow.withValues(alpha: 0.10),
            blurRadius: 18,
            offset: const Offset(0, 10),
          ),
        ],
      ),
      child: labelledField,
    );
  }
}

