class _CompactSelectBoxState extends State<_CompactSelectBox> {
  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_handleControllerChange);
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChange);
    super.dispose();
  }

  void _handleControllerChange() {
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final colors = widget.colors;
    final selected = widget.options.contains(widget.controller.text)
        ? widget.controller.text
        : null;

    return Container(
      padding: const EdgeInsets.fromLTRB(12, 6, 10, 5),
      decoration: BoxDecoration(
        color: colors.field,
        borderRadius: BorderRadius.circular(14),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            widget.label,
            style: TextStyle(color: colors.mutedText, fontSize: 11),
          ),
          DropdownButtonHideUnderline(
            child: DropdownButton<String>(
              value: selected,
              isExpanded: true,
              isDense: true,
              hint: Text(
                'Select',
                style: TextStyle(
                  color: colors.mutedText,
                  fontSize: 13,
                  fontWeight: FontWeight.w800,
                ),
              ),
              icon: Icon(Icons.expand_more, color: colors.text, size: 18),
              dropdownColor: colors.panel,
              style: TextStyle(
                color: colors.text,
                fontSize: 13,
                fontWeight: FontWeight.w800,
              ),
              items: widget.options
                  .map(
                    (option) => DropdownMenuItem<String>(
                      value: option,
                      child: Text(option, overflow: TextOverflow.ellipsis),
                    ),
                  )
                  .toList(),
              onChanged: (value) {
                if (value == null) return;
                widget.controller.text = value;
              },
            ),
          ),
        ],
      ),
    );
  }
}

