  Widget build(BuildContext context) {
    const serviceCopy = {
      'Economy':
          'Cheapest option. Slower matching. Best when the parcel is not urgent.',
      'Standard':
          'Balanced price. Normal rider broadcast. Best for everyday deliveries.',
      'Express':
