class _CircumPaymentSummary extends StatelessWidget {
  final _CircumColors colors;
  final String serviceName;
  final String totalLabel;
  final double total;
  final double rothAvailable;
  final String? ctaLabel;

  const _CircumPaymentSummary({
    required this.colors,
    required this.serviceName,
    required this.totalLabel,
    required this.total,
    required this.rothAvailable,
    this.ctaLabel,
  });

  @override
  Widget build(BuildContext context) {
    final available = math.max(0, rothAvailable);
    final applied = math.min(total, available);
    final remaining = math.max(0, total - applied);
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(28),
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            const Color(0xff0f4cff).withValues(alpha: 0.28),
            const Color(0xff111827).withValues(alpha: 0.86),
            const Color(0xff7c3aed).withValues(alpha: 0.24),
          ],
        ),
        border: Border.all(
          color: const Color(0xff67e8f9).withValues(alpha: 0.30),
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xff2563eb).withValues(alpha: 0.24),
            blurRadius: 32,
            offset: const Offset(0, 18),
          ),
          BoxShadow(
            color: const Color(0xffa855f7).withValues(alpha: 0.12),
            blurRadius: 46,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 42,
                height: 42,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  gradient: const LinearGradient(
                    colors: [Color(0xff67e8f9), Color(0xff8b5cf6)],
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xff67e8f9).withValues(alpha: 0.28),
                      blurRadius: 18,
                    ),
                  ],
                ),
                child: const Icon(
                  Icons.account_balance_wallet_outlined,
                  color: Colors.white,
                  size: 21,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  serviceName,
                  style: TextStyle(
                    color: colors.text,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          _PriceLine(
            colors: colors,
            label: totalLabel,
            value: '£${total.toStringAsFixed(2)}',
            strong: true,
          ),
          _PriceLine(
            colors: colors,
            label: 'Roth available',
            value: '£${available.toStringAsFixed(2)}',
          ),
          _PriceLine(
            colors: colors,
            label: 'Roth Applied',
            value: '£${applied.toStringAsFixed(2)}',
            strong: applied > 0,
          ),
          _PriceLine(
            colors: colors,
            label: 'Card Remaining',
            value: '£${remaining.toStringAsFixed(2)}',
            strong: true,
          ),
          const SizedBox(height: 10),
          Text(
            'Card Remaining',
            style: TextStyle(
              color: colors.mutedText,
              fontWeight: FontWeight.w800,
              letterSpacing: 0.4,
            ),
          ),
          Text(
            '£${remaining.toStringAsFixed(2)}',
            style: const TextStyle(
              color: Colors.white,
              fontSize: 34,
              fontWeight: FontWeight.w900,
              height: 1.05,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            remaining <= 0
                ? 'Payment method: Roth only. No card payment required.'
                : applied > 0
                    ? 'Payment method: Roth first, then card for the remaining balance.'
                    : 'Payment method: Card payment.',
            style: TextStyle(
              color: colors.mutedText,
              fontWeight: FontWeight.w700,
              height: 1.35,
            ),
          ),
          if (ctaLabel != null) ...[
            const SizedBox(height: 8),
            Text(
              ctaLabel!,
              style: TextStyle(
                color: colors.text,
                fontWeight: FontWeight.w900,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

