  }
}

class _RiderRankPresentation extends StatelessWidget {
  final _CircumColors colors;
  final String rank;
  final String rankTitle;
  final String name;
  final String rating;
  final int tripCount;
  final String vehiclePlate;

  const _RiderRankPresentation({
    required this.colors,
