  @override
  Widget build(BuildContext context) {
    final plate = vehiclePlate.trim();
    final progress = _rankProgress(rank, tripCount);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        DecoratedBox(
          decoration: BoxDecoration(
            gradient: const LinearGradient(colors: _spectrumGradient),
            borderRadius: BorderRadius.circular(999),
          ),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
            child: Text(
              '◈ ${rank.toUpperCase()}',
              style: const TextStyle(
                color: Colors.white,
                fontSize: 11,
                fontWeight: FontWeight.w900,
                letterSpacing: 0.6,
              ),
            ),
          ),
        ),
        const SizedBox(height: 7),
        Text(
          name,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: TextStyle(
            color: colors.text,
            fontSize: 18,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 3),
        Text(
          [
            rankTitle,
            '$tripCount Deliveries Completed',
            '$rating Rating',
            if (progress != null) progress,
            if (plate.isNotEmpty) 'Vehicle plate: $plate',
          ].join('\n'),
          maxLines: 6,
          overflow: TextOverflow.ellipsis,
          style: TextStyle(
            color: colors.mutedText,
            fontSize: 12,
            height: 1.35,
            fontWeight: FontWeight.w700,
          ),
        ),
      ],
    );
  }

  static String? _rankProgress(String rank, int trips) {
    return switch (rank.trim().toLowerCase()) {
      'agent' => '$trips / 50 deliveries to Sentinel',
      'sentinel' => '$trips / 200 deliveries to Warden',
      'warden' => '$trips / 500 deliveries to Knight',
      'knight' => '$trips / 1000 deliveries to Veteran',
      'veteran' => 'Top Circum trust rank',
      _ => null,
    };
  }
}

class _RiderAvatar extends StatelessWidget {
  final _CircumColors colors;
  final String name;
  final String? photoUrl;
  final double size;

  const _RiderAvatar({
    required this.colors,
    required this.name,
    required this.photoUrl,
    this.size = 56,
  });

  @override
  Widget build(BuildContext context) {
    final cleanUrl = (photoUrl ?? '').trim();
    final initials = _initials(name);
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        gradient: const LinearGradient(colors: _spectrumGradient),
        border: Border.all(color: colors.adminAccent.withValues(alpha: 0.38)),
        boxShadow: [
          BoxShadow(
            color: colors.adminAccent.withValues(alpha: 0.16),
            blurRadius: 18,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      child: ClipOval(
        child: cleanUrl.isEmpty || cleanUrl == 'null'
            ? _RiderInitialsAvatar(initials: initials)
            : Image.network(
                cleanUrl,
                fit: BoxFit.cover,
                width: size,
                height: size,
                loadingBuilder: (context, child, progress) {
                  if (progress == null) return child;
                  return Container(
                    decoration: BoxDecoration(
                      color: colors.field.withValues(alpha: 0.65),
                    ),
                    child: Center(
                      child: SizedBox(
                        width: size * 0.34,
                        height: size * 0.34,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          color: colors.adminAccent,
                        ),
                      ),
                    ),
                  );
                },
                errorBuilder: (context, error, stackTrace) =>
                    _RiderInitialsAvatar(initials: initials),
              ),
      ),
    );
  }

  static String _initials(String value) {
    final parts = value
        .trim()
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .toList(growable: false);
    if (parts.isEmpty) return 'C';
    if (parts.length == 1) return parts.first.substring(0, 1).toUpperCase();
    return '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}'
        .toUpperCase();
  }
}

