class _Timeline extends StatelessWidget {
  final _CircumColors colors;
  final int activeIndex;

  const _Timeline({required this.colors, required this.activeIndex});

  @override
  Widget build(BuildContext context) {
    return _GlassPanel(
      colors: colors,
      child: Column(
        children: List.generate(_trackingStatuses.length, (index) {
          final completed = index < activeIndex || activeIndex >= 3;
          final current = index == activeIndex && !completed;
          final status = _trackingStatuses[index];
          return Padding(
            padding: EdgeInsets.only(
              bottom: index == _trackingStatuses.length - 1 ? 0 : 14,
            ),
            child: Row(
              children: [
                Icon(
                  completed
                      ? Icons.check_circle
                      : current
                          ? Icons.radio_button_checked
                          : Icons.circle_outlined,
                  color: completed
                      ? colors.success
                      : current
                          ? colors.adminAccent
                          : colors.mutedText,
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        status.title,
                        style: TextStyle(
                          color: colors.text,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      Text(
                        status.body,
                        style: TextStyle(
                          color: colors.mutedText,
                          fontSize: 12,
                          height: 1.3,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          );
        }),
      ),
    );
  }
}

class _GlassPanel extends StatelessWidget {
  final _CircumColors colors;
  final Widget child;

  const _GlassPanel({super.key, required this.colors, required this.child});

  @override
  Widget build(BuildContext context) {
    final radius = BorderRadius.circular(24);
    return ClipRRect(
      borderRadius: radius,
      child: BackdropFilter(
        filter: ui.ImageFilter.blur(
            sigmaX: colors.dark ? 14 : 8, sigmaY: colors.dark ? 14 : 8),
        child: Container(
          width: double.infinity,
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [
                colors.panel.withOpacity(colors.dark ? 0.82 : 0.95),
                colors.adminAccent.withOpacity(colors.dark ? 0.13 : 0.07),
                colors.panel.withOpacity(colors.dark ? 0.74 : 0.93),
              ],
            ),
            borderRadius: radius,
            border: Border.all(
              color: Color.alphaBlend(
                colors.adminAccent.withOpacity(colors.dark ? 0.18 : 0.12),
                Colors.white.withOpacity(colors.dark ? 0.08 : 0.18),
              ),
            ),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withOpacity(colors.dark ? 0.24 : 0.06),
                blurRadius: 20,
                offset: const Offset(0, 10),
              ),
              BoxShadow(
                color: colors.adminGlow.withOpacity(colors.dark ? 0.14 : 0.06),
                blurRadius: 28,
                offset: const Offset(0, 14),
              ),
            ],
          ),
          child: child,
        ),
      ),
    );
  }
}

