                        if (_giftMode == 'gift_myself') ...[
                          const SizedBox(height: 12),
                          _giftGlassDropdown(
                            colors: colors,
                            label: 'Self-gift frequency',
                            value: _selfGiftFrequency,
                            options: const [
                              'one_off',
                              'monthly',
                              'quarterly',
                              'custom',
                            ],
                            labelFor: (value) => switch (value) {
                              'one_off' => 'One-off',
                              'monthly' => 'Monthly',
