}

class _GiftsComingSoonPageState extends State<_GiftsComingSoonPage> {
  final _name = TextEditingController();
  final _email = TextEditingController();
  bool _saving = false;
  String? _message;

  static const _occasions = [
    'Birthdays',
    'Anniversaries',
    'Graduations',
    'Thank You Gifts',
    'Christmas',
    'New Baby',
    'Just Because',
  ];
  static const _interests = [
    'Travel',
    'Technology',
    'Fitness',
    'Coffee',
    'Books',
    'Gaming',
    'Aviation',
  ];

  @override
  void dispose() {
    _name.dispose();
    _email.dispose();
    super.dispose();
  }

  Future<void> _joinWaitlist() async {
    final name = _name.text.trim();
    final email = _email.text.trim().toLowerCase();
    if (name.isEmpty ||
        !RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$').hasMatch(email)) {
      setState(() => _message = 'Enter your name and a valid email address.');
      return;
    }
    setState(() {
      _saving = true;
      _message = null;
    });
    try {
      await _ensureCircumFirebaseReady();
      await FirebaseFirestore.instance.collection('giftsWaitlist').add({
        'name': name,
        'email': email,
        'source': 'gifts-coming-soon',
        'createdAt': FieldValue.serverTimestamp(),
      });
      if (!mounted) return;
      _name.clear();
      _email.clear();
      setState(() => _message = 'You’re on the Gifts waitlist.');
    } catch (error) {
      debugPrint('Gifts waitlist error: $error');
      if (mounted) {
        setState(() => _message =
            'We could not add you just now. Please try again shortly.');
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final colors = widget.colors;
    final narrow = MediaQuery.sizeOf(context).width < 700;
    return Scaffold(
      backgroundColor: colors.background,
      body: SafeArea(
        child: ListView(
          padding:
              EdgeInsets.fromLTRB(narrow ? 18 : 28, 16, narrow ? 18 : 28, 42),
          children: [
            ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 1100),
              child: Row(
                children: [
                  IconButton(
                    tooltip: 'Back to Circum',
                    onPressed: widget.onBack,
                    icon: const Icon(Icons.arrow_back),
                  ),
                  const SizedBox(width: 8),
                  Image.asset(
                    'assets/images/circum_wordmark.png',
                    width: 126,
                    height: 30,
                    fit: BoxFit.contain,
                  ),
                ],
              ),
            ),
            const SizedBox(height: 24),
            Center(
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 900),
                child: Column(
                  children: [
                    AspectRatio(
                      aspectRatio: 1,
                      child: Container(
                        width: narrow ? double.infinity : 620,
                        constraints: const BoxConstraints(maxWidth: 620),
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(28),
                          color: Colors.black,
                          border: Border.all(
                            color:
                                const Color(0xff70f5d0).withValues(alpha: 0.24),
                          ),
                          boxShadow: [
