class _CompanyLiveChatButton extends StatefulWidget {
  final _CircumColors colors;

  const _CompanyLiveChatButton({required this.colors});

  @override
  State<_CompanyLiveChatButton> createState() => _CompanyLiveChatButtonState();
}

class _CompanyLiveChatButtonState extends State<_CompanyLiveChatButton> {
  final _name = TextEditingController();
  final _email = TextEditingController();
  final _message = TextEditingController();
  bool _open = false;
  bool _sending = false;
  String? _note;

  @override
  void dispose() {
    _name.dispose();
    _email.dispose();
    _message.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final colors = widget.colors;
    if (_open) {
      return Positioned.fill(
        child: Material(
          color: Colors.black.withValues(alpha: 0.46),
          child: Stack(
            children: [
              Positioned.fill(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () => setState(() => _open = false),
                ),
              ),
              _panel(context, colors),
            ],
          ),
        ),
      );
    }
    return Positioned(
      right: 18,
      bottom: 18,
      child: SafeArea(
        minimum: const EdgeInsets.only(bottom: 4),
        child: Tooltip(
          message: 'Live chat',
          child: Semantics(
            button: true,
            label: 'Open live chat',
            child: Material(
              color: Colors.transparent,
              child: InkWell(
                onTap: () => setState(() => _open = true),
                customBorder: const CircleBorder(),
                child: Ink(
                  width: 52,
                  height: 52,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    gradient: const LinearGradient(colors: _spectrumGradient),
                    border: Border.all(
                      color: Colors.white.withValues(alpha: 0.28),
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: const Color(0xff6558f5).withValues(alpha: 0.24),
                        blurRadius: 16,
                        offset: const Offset(0, 7),
                      ),
                    ],
                  ),
                  child: const Icon(
                    Icons.chat_bubble_outline_rounded,
                    color: Colors.white,
                    size: 23,
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _panel(BuildContext context, _CircumColors colors) {
    final size = MediaQuery.sizeOf(context);
    final compact = size.width < 720;
    return Align(
      alignment: compact ? Alignment.bottomCenter : Alignment.centerRight,
      child: SafeArea(
        minimum: EdgeInsets.only(
          left: compact ? 10 : 0,
          right: compact ? 10 : 0,
          bottom: compact ? 10 : 0,
        ),
        child: Material(
          color: Colors.transparent,
          child: Container(
            width: compact ? double.infinity : 400,
            height: compact ? size.height * 0.92 : double.infinity,
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: colors.panel,
              borderRadius: compact
                  ? BorderRadius.circular(24)
                  : const BorderRadius.horizontal(left: Radius.circular(24)),
              border: Border.all(color: colors.border),
              boxShadow: [
                BoxShadow(
                  color:
                      Colors.black.withValues(alpha: colors.dark ? 0.34 : 0.16),
                  blurRadius: 28,
                  offset: const Offset(0, 16),
                ),
              ],
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    Container(
                      width: 38,
                      height: 38,
                      decoration: BoxDecoration(
                        gradient:
                            const LinearGradient(colors: _spectrumGradient),
                        borderRadius: BorderRadius.circular(14),
                      ),
                      child:
                          const Icon(Icons.support_agent, color: Colors.white),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Talk to Circum',
                            style: TextStyle(
                              color: colors.text,
                              fontSize: 18,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          Text(
                            'Send us a note and the team will pick it up.',
                            style: TextStyle(
                              color: colors.mutedText,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ],
                      ),
                    ),
                    IconButton(
                      tooltip: 'Close live chat',
                      onPressed: () => setState(() => _open = false),
                      icon: Icon(Icons.close, color: colors.text),
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                _LiveChatField(
                  colors: colors,
                  controller: _name,
                  label: 'Name',
                  icon: Icons.person_outline,
                ),
                const SizedBox(height: 10),
                _LiveChatField(
                  colors: colors,
                  controller: _email,
                  label: 'Email or phone',
                  icon: Icons.alternate_email,
                ),
                const SizedBox(height: 10),
                _LiveChatField(
                  colors: colors,
                  controller: _message,
                  label: 'How can we help?',
                  icon: Icons.message_outlined,
                  minLines: 3,
                  maxLines: 5,
                ),
                if (_note != null) ...[
                  const SizedBox(height: 10),
                  Text(
                    _note!,
                    style: TextStyle(
                      color: _note!.startsWith('Sent')
                          ? colors.success
                          : const Color(0xffef4444),
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ],
                const SizedBox(height: 14),
                SizedBox(
                  width: double.infinity,
                  child: FilledButton.icon(
                    onPressed: _sending ? null : _send,
                    icon: _sending
                        ? const SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(strokeWidth: 2),
                          )
                        : const Icon(Icons.send),
                    label: Text(_sending ? 'Sending' : 'Send message'),
                    style: FilledButton.styleFrom(
                      backgroundColor: colors.text,
                      foregroundColor: colors.inverseText,
                      padding: const EdgeInsets.symmetric(vertical: 14),
                    ),
                  ),
                ),
                if (!compact) const Spacer(),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _send() async {
    final message = _message.text.trim();
    final contact = _email.text.trim();
    if (message.isEmpty || contact.isEmpty) {
      setState(() => _note = 'Add your contact and message first.');
      return;
    }
    setState(() {
      _sending = true;
      _note = null;
    });
    try {
      await _ensureCircumFirebaseReady();
      final db = FirebaseFirestore.instance;
      final ticketRef = db.collection('supportTickets').doc();
      final user = FirebaseAuth.instance.currentUser;
      final chatId = 'support_${ticketRef.id}';
      await ticketRef.set({
        'channel': 'web_live_chat',
        'status': 'open',
        'priority': 'normal',
        'name': _name.text.trim(),
        'email': contact,
        'message': message,
        'lastMessage': message,
        'lastMessageAt': FieldValue.serverTimestamp(),
        'adminUnreadCount': 1,
        'pageUrl': Uri.base.toString(),
        'chatId': chatId,
        if (user != null) 'userId': user.uid,
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      if (user != null) {
        final chatRef = db.collection('chats').doc(chatId);
        await chatRef.set({
          'threadId': chatId,
          'type': 'support',
          'ticketId': ticketRef.id,
          'participants': [user.uid, 'circum-support'],
          'participantRoles': {
            user.uid: 'shipper',
            'circum-support': 'admin',
          },
          'status': 'open',
          'createdAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
          'lastMessage': message,
        });
        await chatRef.collection('messages').add({
          'threadId': chatId,
          'ticketId': ticketRef.id,
          'senderId': user.uid,
          'senderRole': 'shipper',
          'messageText': message,
          'message': message,
          'attachments': const [],
          'initialSupportRequest': true,
          'readBy': [user.uid],
          'createdAt': FieldValue.serverTimestamp(),
        });
      }
      _message.clear();
      setState(() => _note = 'Sent. Circum support has your message.');
    } catch (_) {
      setState(() => _note = 'We could not send that. Please try again.');
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }
}

